/**
 * 手册章节——战斗与自保（v1.2.4 从 GuideContent 拆出）。
 * 
 * 战斗/战术/武器自动装备/救援主人。纯文本，逐字未改。
 */
public final class GuideChaptersCombat {
    private GuideChaptersCombat() {
    }

    static GuideContent.Chapter combatGuide() {
        return new GuideContent.Chapter("战斗与自保",
                "女仆有一套\u00a7e被动保命系统\u00a7r（自保行为，默认开启，优先级压过一切状态）："
                        + "血量低于触发线（默认 30%）时进入保命状态——喝治疗药水/吃食物回血、垫高躲怪、逃跑、"
                        + "环境危险（岩浆/溺水/窒息）自救，威胁消失且血回到安全线才解除。",
                "\u00a7e逃生手段\u00a7r：",
                "① \u00a7e末影珍珠\u00a7r：濒死且被贴身时扔珍珠脱身；",
                "② \u00a7e传送回家\u00a7r：自保结束后传回主人身边（主人身边有怪物、或有危险方块不传；"
                        + "\u00a7e主人身边没有安全落点也不传\u00a7r——她飞在半空/悬在崖边时不会被扔过去摔死，等落地归队）；"
                        + "\u00a7e传送有冷却\u00a7r（防抖：短时间内不会反复拉扯），被卡住时先尝试自己挣脱，实在脱困无望才传送；",
                "\u2462 \u7a92\u606f/\u5361\u5899\u65f6\u4f1a\u5c1d\u8bd5\u4e0a\u6d6e\uff0c\u5fc5\u8981\u65f6\u4f20\u9001\u5230\u4e3b\u4eba\u8eab\u8fb9\u3002\u00a7e\u53ea\u6709\u771f\u7684\u5403\u5230\u8d85\u8fc7 4 \u70b9\u7a92\u606f\u4f24\u5bb3\u00a7r\u624d\u4f1a\u558a\u300c\u6211\u5361\u4f4f\u4e86\uff0c\u5feb\u5598\u4e0d\u8fc7\u6c14\u4e86\u300d\u2014\u2014\u5934\u90e8\u51e0\u4f55\u6324\u8fdb\u65b9\u5757\u4f46\u4e00\u70b9\u8840\u6ca1\u6389\u5c31\u4e0d\u542d\u58f0\uff1b\u632a\u4f4d\u7f6e\u3001\u9876\u51fa\u8fd9\u4e9b\u81ea\u6551\u52a8\u4f5c\u7167\u65e7\uff0c\u8fd0\u884c\u65e5\u5fd7\u5206\u7c7b\u300c\u7a92\u606f\u300d\u53ef\u67e5\u300c\u8fd9\u6b21\u4e3a\u4ec0\u4e48\u8bf4 / \u4e3a\u4ec0\u4e48\u6ca1\u8bf4\u300d\u3002\u00a7e\u8fd9\u53e5\u64ad\u62a5\u662f\u5e38\u9a7b\u68c0\u67e5\u00a7r\u2014\u2014\u53ea\u770b\u300c\u6700\u8fd1 5 \u79d2\u7d2f\u8ba1\u5403\u5230\u7684\u7a92\u606f\u4f24\u5bb3\u591f\u6ca1\u591f 4 \u70b9\u300d\uff0c\u4e0e\u81ea\u4fdd\u4f1a\u8bdd\u5728\u4e0d\u5728\u3001\u5ca9\u6d46\u3001\u8ba9\u4f4d\u7a97\u53e3\u5168\u90fd\u65e0\u5173\uff1b\u4e00\u9635\u4e0d\u5361\u4e86\u8fd8\u80fd\u518d\u558a\u3002\u00a7e\u5750/\u8e72\u7740\u7684\u5979\u4e0d\u4f1a\u88ab\u8fd9\u53e5\u4f20\u9001\u62c9\u8d70\u00a7r\uff08\u89c1\u5f00\u5173\u300c\u5750\u4e0b\u7684\u5973\u4ec6\u4e0d\u88ab\u81ea\u4fdd\u4f20\u9001\u62c9\u8d70\u300d\uff0c\u9ed8\u8ba4\u5f00\u2014\u2014\u5979\u81ea\u5df1\u7ad9\u8d77\u6765\u5c31\u6062\u590d\uff09\u3002",
                "\u2463 \u00a7e\u4fdd\u547d\u9053\u5177\u4f18\u5148\u00a7r\uff1a\u5979\u5e26\u7740\u00a7e\u7ec0\u73e0\u4e4b\u836f/\u4e0d\u6b7b\u56fe\u817e\u00a7r\u7b49\u4fdd\u547d\u9970\u54c1\u65f6\uff0c\u4f4e\u8840\u00a7e\u4e0d\u4f1a\u9003\u8dd1\u00a7r\u2014\u2014\u6b7b\u4e0d\u4e86\u5c31\u7559\u4e0b\u6765\u7ee7\u7eed\u6253/\u6cbb\u7597\uff08\u300c\u4fdd\u547d\u7269\u54c1\u4e0b\u4fdd\u7559\u9003\u8dd1\u300d\u5f00\u5173\u9ed8\u8ba4\u5173\uff1b\u60f3\u8ba9\u5979\u7167\u5e38\u9003\u6253\u5f00\u5373\u53ef\uff0c\u4f4e\u8840\u9003\u8dd1\u4e2d\u4e5f\u4e0d\u4f1a\u88ab\u5f3a\u884c\u4f20\u9001\u56de\u4e3b\u4eba\u8eab\u8fb9\u9001\u6b7b\uff09\u3002",
                "\u2464 \u00a7e\u81f4\u6b7b\u81ea\u52a8\u56de\u9b42\u7b26\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u53d7\u5230\u00a7e\u4f1a\u81f4\u547d\u7684\u90a3\u4e00\u51fb\u00a7r\u4e14\u8eab\u4e0a\u00a7e\u6ca1\u6709\u00a7e\u7ec0\u73e0\u4e4b\u836f/\u4e0d\u6b7b\u56fe\u817e\u00a7r\u7b49\u4fdd\u547d\u7269\u54c1\u65f6\uff0c\u5979\u5f53\u573a\u81ea\u52a8\u6536\u56de\u9b42\u7b26\u2014\u2014\u00a7c\u4e0d\u7528\u518d\u8dd1\u53bb\u795e\u9f9b\u590d\u6d3b\u00a7r\uff0c\u4f60\u4ece\u9b42\u7b26\u628a\u5979\u91cd\u65b0\u653e\u51fa\u6765\u5c31\u80fd\u7ee7\u7eed\u7528\uff08\u804a\u5929\u680f\u4f1a\u63d0\u793a\u300c\u4f60\u7684\u5973\u4ec6\u53d7\u5230\u81f4\u547d\u4f24\u5bb3\uff0c\u5df2\u56de\u5230\u9b42\u7b26\u4e2d\u300d\uff0c\u5e76\u7ed9\u5979\u9644\u52a0\u77ed\u6682\u56de\u8840\uff09\u3002\u4f4e\u8840\u91cf\u00a7c\u4e0d\u4f1a\u00a7r\u89e6\u53d1\u56de\u9b42\u7b26\u2014\u2014\u90a3\u662f\u81ea\u4fdd\u884c\u4e3a\u7684\u6d3b\uff08\u559d\u836f/\u9003\u8dd1\uff09\uff0c\u53ea\u6709\u00a7e\u771f\u7684\u8981\u6b7b\u4e86\u00a7r\u624d\u6536\u3002\u91cd\u65b0\u91ca\u653e\u540e\u6709\u51b7\u5374\uff08\u9ed8\u8ba4 60 \u79d2\uff0c\u4ece\u00a7e\u91ca\u653e\u65f6\u523b\u00a7r\u8d77\u7b97\uff0c\u9762\u677f\u53ef\u8c03\u30010 = \u5173\u95ed\uff09\uff0c\u51b7\u5374\u671f\u95f4\u518d\u53d7\u81f4\u6b7b\u4f24\u4e0d\u4f1a\u91cd\u590d\u6536\u7b26\u3002",
                "\u2465 \u00a7e\u5973\u4ec6\u81ea\u52a8\u590d\u6d3b\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5982\u679c\u56de\u9b42\u7b26\u4e5f\u6ca1\u80fd\u6551\u4e0b\uff08\u5979\u771f\u7684\u6b7b\u4e86\uff09\uff0c\u5893\u7891\u4f1a\u5728\u00a7e\u5ef6\u8fdf\u65f6\u95f4\u5230\u671f\u65f6\u81ea\u52a8\u6d88\u5931\u00a7r\uff08\u9ed8\u8ba4 60 \u79d2\uff09\uff0c\u5973\u4ec6\u968f\u5373\u5728\u00a7e\u4e3b\u4eba\u7684\u91cd\u751f\u70b9\u00a7r\u590d\u6d3b\uff08\u5e8a/\u91cd\u751f\u951a\uff09\u2014\u2014\u00a7e\u4e0d\u7528\u518d\u624b\u52a8\u8dd1\u5230\u5893\u7891\u5904\u628a\u5979\u7684\u4e1c\u897f\u53d6\u56de\u00a7r\u3002\u00a7e\u91cd\u751f\u70b9\u4e0d\u53ef\u7528\u00a7r\u65f6\uff08\u5e8a\u88ab\u62c6/\u91cd\u751f\u951a\u6ca1\u7535/\u7ef4\u5ea6\u4e0d\u5141\u8bb8\uff09\u5979\u00a7e\u76f4\u63a5\u5728\u4e3b\u4eba\u6240\u5728\u7684\u4f4d\u7f6e\u590d\u6d3b\u00a7r\uff08\u5f3a\u5236\u751f\u6548\u3001\u4e0d\u770b\u5730\u5f62\uff0c\u4e3b\u4eba\u5728\u5929\u4e0a/\u5ca9\u6d46\u8fb9\u4e5f\u4e00\u6837\uff09\u3002\u590d\u6d3b\u65f6\u00a7e\u80cc\u5305/\u9970\u54c1/\u4efb\u52a1/\u6a21\u578b\u5168\u90e8\u539f\u6837\u6062\u590d\u00a7r\uff08\u6309\u6b7b\u4ea1\u77ac\u95f4\u7684\u5b8c\u6574\u5b58\u6863\u8fd8\u539f\uff09\uff0c\u8840\u91cf\u9ed8\u8ba4\u6ee1\u8840\uff08\u300c\u590d\u6d3b\u8840\u91cf\u6bd4\u300d\u53ef\u8c03\uff0c0.35 = \u4e09\u6210\u534a\uff09\uff1b\u00a7e\u590d\u6d3b\u77ac\u95f4\u5979\u4f1a\u8bf4\u8bdd\u544a\u8bc9\u4f60\u00a7r\uff08\u6c14\u6ce1\u300c\u4e3b\u4eba\uff0c\u6211\u56de\u6765\u5566\uff01\u300d+ \u4e00\u6761\u5e26\u5979\u540d\u5b57\u7684\u7cfb\u7edf\u6d88\u606f\uff09\uff1b\u4e3b\u4eba\u4e0d\u5728\u7ebf\u65f6\u5893\u7891\u4fdd\u7559\u3001\u7b49\u5979\u4e0a\u7ebf\u518d\u590d\u6d3b\uff0c\u4e0d\u4e22\u5973\u4ec6\u3002\u590d\u6d3b\u4f4d\u7f6e\u4e0e\u73a9\u5bb6\u4e00\u81f4\uff1a\u5e8a/\u91cd\u751f\u951a\u4f1a\u843d\u5728\u4f60\u590d\u6d3b\u65f6\u7ad9\u7684\u90a3\u4e00\u683c\uff0c\u5e76\u5e26 2 \u79d2\u6297\u6027\u63d0\u5347 V + \u6297\u706b\u4fdd\u62a4\u3002\u5f00\u5173\u4e0e\u53c2\u6570\u5728\u300c\u751f\u5b58\u4e0e\u590d\u6d3b \u2192 \u6b7b\u4ea1\u4e0e\u590d\u6d3b\u300d\u5c0f\u8282\u3002",
                "（落地水、岩浆逃生放水、主人死亡传送属于\u00a7e生存与复活\u00a7r，独立板块统一介绍——见「被动技能」章，此处不重复）",
                "\u00a7e\u3010\u6536\u653e\u9b42\u7b26\u540e\u8840\u91cf\u4e0a\u9650\u4fdd\u6301 / \u62d6\u5979\u7684\u88c5\u5907\u6b63\u5e38\u53d6\u51fa\u3011\u00a7r\u6536\u653e\u9b42\u7b26\u4e0d\u4f1a\u5f71\u54cd\u5979\u7684\u5c5e\u6027\u4e0e\u7269\u54c1\uff1a\u2460 \u597d\u611f\u5ea6\u5347\u9636\u7ed9\u7684\u8840\u91cf\u4e0a\u9650\uff08\u6bd4\u5982 80\uff09\u5728\u00a7e\u6536\u653e\u9b42\u7b26\u4e4b\u540e\u4ecd\u662f\u5979\u7684\u771f\u5b9e\u4e0a\u9650\u00a7r\uff0c\u4e0d\u4f1a\u6389\u56de 20\uff1b\u2461 \u4ece\u5979\u7684\u80cc\u5305/\u88c5\u5907\u680f\u91cc\u5f80\u5916\u62d6\u88c5\u5907\uff0c\u00a7e\u7269\u54c1\u4f1a\u7167\u5e38\u53d6\u51fa\u3001\u4e0d\u4f1a\u6d88\u5931\u00a7r\u3002",
                "\u00a7e\u6536\u653e\u9b42\u7b26\u7684\u6570\u636e\u4e0d\u4f1a\u4e22\u00a7r\uff1a\u5979\u5b58\u6863\u91cc\u4e00\u76f4\u662f\u597d\u7684\u2014\u2014TLM \u6536\u653e\u662f\u300c\u62cd\u5feb\u7167 \u2192 \u653e\u51fa\u6765\u65f6\u8bfb\u56de\u300d\uff0c\u8840\u91cf\u4e0a\u9650\u4e0e\u88c5\u5907\u90fd\u65e0\u635f\uff1b\u5ba2\u6237\u7aef\u90a3\u8fb9\u7531\u672c\u6a21\u7ec4\u7684\u00a7e\u5165\u4e16\u754c\u81ea\u52a8\u8865\u5305\u00a7r\u8d1f\u8d23\uff0c\u8865\u5305\u65f6\u673a\u6309\u5b9e\u4f53\u7f51\u7edc id \u5206\u6d41\uff0c\u6240\u4ee5\u6536\u653e\u540e\u5ba2\u6237\u7aef\u90a3\u53ea\u5973\u4ec6\u7684\u5c5e\u6027\u8868\u3001\u4ee5\u53ca\u4f60\u6253\u5f00\u7684\u7269\u54c1\u680f\uff0c\u6293\u7684\u90fd\u662f\u540c\u4e00\u53ea\u5b9e\u4f53\u3002",
                "\u00a7e\u5165\u4e16\u754c\u81ea\u52a8\u8865\u5305\u7684\u89c4\u5219\u00a7r\uff1a\u8865\u5305\u6309\u00a7e\u5b9e\u4f53\u7f51\u7edc id \u5206\u6d41\u00a7r\u2014\u2014\u9b42\u7b26\u653e\u51fa\u7684\u00a7e\u65b0\u5b9e\u4f53\u4e0d\u8865\u5305\u00a7r\uff08\u539f\u7248\u8ffd\u8e2a\u672c\u6765\u5c31\u4f1a\u53d1\u5168\u5957\uff1a\u751f\u6210 + \u6570\u636e + \u5c5e\u6027 + \u88c5\u5907\uff09\uff1b\u53ea\u6709\u00a7e\u540c\u4e00\u53ea\u5973\u4ec6\u79bb\u573a\u53c8\u56de\u6765\u00a7r\uff08\u533a\u5757\u5378\u8f7d\u91cd\u8f7d\u8fd9\u7c7b\u3001id \u6ca1\u53d8\uff09\u624d\u8865\uff0c\u8865\u7684\u65f6\u5019\u987a\u5e26\u8865\u53d1\u4e00\u6b21\u9970\u54c1\u5168\u91cf\u540c\u6b65\uff1b\u5979\u90a3\u9053\u300c\u754c\u9762\u6b63\u5f00\u7740\u5c31\u5148\u63a8\u8fdf\u4e00\u79d2\u518d\u770b\u300d\u7684\u95f8\u4fdd\u7559\u3002\u53e6\u6709\u4e00\u6761\u8bca\u65ad\uff1a\u5979\u7684\u88c5\u5907\u69fd\u00a7e\u4ece\u6709\u4e1c\u897f\u53d8\u7a7a\u00a7r\u65f6\u4f1a\u5199\u4e00\u884c\u65e5\u5fd7\uff08\u00a7elogs/promaid.log\u00a7r \u641c\u00a7e\u300c\u88c5\u5907\u79bb\u5f00\u300d\u00a7r\uff0c\u542b\u69fd\u4f4d\u3001\u4e22\u4e86\u4ec0\u4e48\u3001\u5979\u80cc\u5305\u5b9e\u65f6\u5feb\u7167\u4e0e\u8c03\u7528\u6808\uff09\u2014\u2014\u9047\u5230\u300c\u8c01\u628a\u5979\u7684\u88c5\u5907\u62ff\u8d70\u4e86\u300d\uff0c\u4e00\u884c\u65e5\u5fd7\u5c31\u80fd\u6307\u8ba4\u3002",
                "\u00a7e\u3010\u4f20\u9001\u540e\u8840\u91cf\u4e0a\u9650\u4fdd\u6301\u771f\u5b9e\u503c\u3011\u00a7r\u672c\u6a21\u7ec4\u7684\u00a7e\u6bcf\u4e00\u6761\u4f20\u9001\u94fe\u8def\u00a7r\uff08\u540c\u7ef4\u8fdc\u8ddd\u62c9\u56de / \u8de8\u7ef4\u5ea6\u8ddf\u968f / \u4e3b\u4eba\u6b7b\u4ea1\u4f20\u9001 / \u70eb\u4f24\u9003\u751f / \u81ea\u4fdd\u5f52\u4f4d / \u6392\u73ed\u8868\u4f20\u9001\uff0c\u4ee5\u53ca\u00a7e TLM \u81ea\u5df1\u90a3\u6761\u8ddf\u968f\u77ac\u79fb\u00a7r\uff09\u90fd\u4f1a\u00a7e\u81ea\u52a8\u8865\u53d1\u5c5e\u6027\u8868\u00a7r\uff0c\u5e76\u4e14\u662f\u00a7e\u8fde\u8865\u51e0\u62cd\u00a7r\u4ee5\u62b9\u5e73\u65f6\u5e8f\u7ade\u6001\u3002\u4f20\u9001\u540e\u754c\u9762\u91cc\u7684\u8840\u6761\u4e0a\u9650\u59cb\u7ec8\u4e0e\u5979\u771f\u5b9e\u7684\u4e0a\u9650\u4e00\u81f4\u3002",
                "\u00a7e\u3010\u5893\u7891\u5230\u671f\u5fc5\u88ab\u5220\u9664\u3011\u00a7r\u6b63\u5e38\u60c5\u51b5\u5893\u7891\u5230\u671f\u5c31\u6d88\u5931\uff1b\u5373\u4f7f\u00a7e\u5979\u6b7b\u5728\u522b\u7684\u4e16\u754c\u3001\u4f60\u4e5f\u5728\u522b\u5904\u00a7r\uff08\u5893\u7891\u90a3\u5757\u533a\u5757\u6ca1\u52a0\u8f7d\uff09\uff0c\u5220\u5893\u7891\u65f6\u82e5\u5b9e\u4f53\u8868\u91cc\u627e\u4e0d\u5230\uff0c\u4e5f\u4f1a\u00a7e\u6309 TLM \u81ea\u5df1\u767b\u8bb0\u7684\u5893\u7891\u5750\u6807\u628a\u90a3\u683c\u533a\u5757\u8f7d\u8fdb\u6765\u518d\u5220\u00a7r\uff0c\u8de8\u4e16\u754c\u4e5f\u4e0d\u4f1a\u6f0f\u2014\u2014\u5893\u7891\u8fde\u540c\u00a7e\u6574\u5957\u80cc\u5305\u7269\u54c1\u4e0e\u80f6\u7247\u00a7r\u90fd\u4f1a\u968f\u4e4b\u6e05\u6389\u3002",
                "\u00a7e\u3010\u597d\u611f\u5ea6\u5347\u9636\u53ea\u62ac\u4e0a\u9650\u3011\u00a7r\u5347\u9636\u53ea\u62ac\u5979\u7684\u00a7e\u8840\u91cf\u4e0a\u9650\u00a7r\uff0c\u00a7c\u4e0d\u8865\u5f53\u524d\u8840\u00a7r\uff0c\u672c\u6a21\u7ec4\u00a7e\u4e0d\u4f1a\u989d\u5916\u6539\u5979\u4e00\u6ef4\u8840\u00a7r\u3002\u4f4e\u8840\u81ea\u4fdd\u7684\u8fdb\u573a\u7ebf\u662f\u00a7e\u8840\u91cf\u6bd4\u7387\u00a7r\uff08\u9ed8\u8ba4 30%\uff09\u3002",
                "\u00a7e\u73af\u5883\u4f24\u5bb3\u8f6f\u5904\u7406\u00a7r\uff1a\u8e29\u4ed9\u4eba\u638c/\u6d46\u679c\u4e1b\u3001\u8f7b\u5fae\u6454\u4f24\u7b49\u00a7e\u5c0f\u4f24\u5bb3\u00a7r\u4e0d\u4f1a\u89e6\u53d1\u6574\u5957\u9003\u8dd1\u6d41\u7a0b\u2014\u2014\u5979\u4f1a\u00a7e\u8131\u79bb\u5371\u9669\u6e90\u540e\u539f\u5730\u4f11\u6574\u56de\u8840\u00a7r\uff0c\u4e0d\u4f1a\u6ee1\u5730\u56fe\u4e71\u8dd1\uff1b\u771f\u6b63\u7684\u6301\u7eed\u5a01\u80c1\uff08\u5ca9\u6d46/\u6eba\u6c34/\u56f4\u6bb4\uff09\u4ecd\u6309\u5b8c\u6574\u81ea\u4fdd\u5904\u7406\u3002",
                "\u00a7e\u4fdd\u547d\u8d44\u6e90\u7684\u51b7\u5374\u00a7r\uff1a\u5ca9\u6d46/\u7740\u706b\u6700\u540e\u515c\u5e95\u5403\u7684\u00a7e\u91d1\u82f9\u679c/\u9644\u9b54\u91d1\u82f9\u679c\u00a7r\uff0c\u5403\u5b8c\u4f1a\u6309\u00a7e\u5b83\u81ea\u5df1\u7ed9\u7684\u6548\u679c\u65f6\u957f\u00a7r\u8bb0\u4e00\u6b21\u51b7\u5374\uff08\u666e\u901a = \u5438\u6536 2 \u5206\u949f\uff0c\u9644\u9b54 = \u6297\u6027/\u6297\u706b 5 \u5206\u949f\uff09\u2014\u2014\u4e00\u6b21\u4e00\u9897\uff0c\u5438\u6536\u8017\u5c3d\u624d\u4f1a\u518d\u5403\u3002\u4f4e\u8840\u56de\u8840\u90a3\u4e24\u6761\u8def\uff08\u56de\u8840\u9636\u68af/\u5373\u65f6\u56de\u8840\uff09\u5171\u7528\u540c\u4e00\u6761\u51b7\u5374\u3002",
                "\u00a7e\u7740\u706b\u600e\u4e48\u529e\u00a7r\uff1a\u73af\u5883\u5371\u9669\u65f6\u5979\u4f1a\u81ea\u5df1\u706d\u706b\u2014\u2014\u9644\u8fd1\u6709\u6c34\u6e90\u4f1a\u00a7e\u76f4\u63a5\u4f20\u9001\u8fdb\u6c34\u00a7r\u3002",
                "\u00a7e\u642d\u9ad8\u8eb2\u602a\u00a7r\uff1a\u88ab\u8fd1\u8eab\u65f6\u5979\u5f80\u4e0a\u57ab\u65b9\u5757\u8eb2\u5f00\u2014\u2014\u00a7e\u722c\u5230\u5979\u6bd4\u654c\u4eba\u9ad8\u300c\u9ad8\u4e8e\u654c\u65b9\u683c\u6570\u300d\u00a7r\uff08\u9ed8\u8ba4 30 \u683c\uff09\u4e3a\u6b62\uff0c\u4e13\u6cbb\u00a7e\u76d1\u5b88\u8005 / \u5176\u5b83\u8fdc\u7a0b Boss\u00a7r\u3002\u722c\u9ad8\u671f\u95f4\u5979\u00a7e\u8bb0\u4f4f\u654c\u65b9\u9ad8\u5ea6\u00a7r\u2014\u2014\u57ab\u5230\u5341\u51e0\u683c\u540e\u7ad6\u76f4\u8ddd\u79bb\u8d85\u51fa\u5a01\u80c1\u626b\u63cf\u5708\u3001\u654c\u4eba\u4e00\u5ea6\"\u770b\u4e0d\u89c1\u4e86\"\u4e5f\u4e0d\u4f1a\u505c\uff0c\u4e00\u76f4\u57ab\u5230\u76ee\u6807\u9ad8\u5ea6\uff1b\u4e0a\u9650\u53d7\u00a7e\u300c\u81f3\u591a\u5411\u4e0a\u642d\u591a\u5c11\u4e2a\u65b9\u5757\u300d\u00a7r\u5c01\u9876\uff08\u9ed8\u8ba4 30\uff0c\u53ef\u8c03\uff09\uff0c\u5a01\u80c1\u771f\u7684\u6563\u4e86\u5219\u56de\u843d\u00a7e\u300c\u642d\u9ad8\u5b89\u5168\u9ad8\u5ea6\u300d\u00a7r\uff08\u9ed8\u8ba4 5 \u683c\u7684\u7edd\u5bf9\u515c\u5e95\uff0c\u4e0e\u843d\u5730\u6c34\u89e6\u53d1\u914d\u5bf9\uff09\uff1b",
                "参数位置：所有自保参数（触发/解除血量、威胁距离、搭高上限、\u00a7e高于敌方格数\u00a7r、搭高安全高度、逃跑速度、珍珠触发线、"
                        + "\u00a7e收符冷却\u00a7r等）都在「战斗与自保 → 自保战术 / 传送与逃生」小节；回魂符的开关/致死保护/"
                        + "主人半径在「\u00a7e致死伤害自动回魂符\u00a7r」小节。",
                "\u00a7e\u4e3b\u52a8\u5207\u6362\u6218\u6597\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u4f60\u88ab\u6709\u6765"
                + "\u6e90\u7684\u653b\u51fb\u6253\uff08\u00a7e\u602a\u7269/\u73a9\u5bb6/\u5f39\u5c04\u7269\u00a7r\uff1b\u6454\u843d"
                + "\u3001\u5ca9\u6d46\u7b49\u73af\u5883\u4f24\u5bb3\u4e0d\u7b97\uff0c\u514d\u5f97\u5973\u4ec6\u88ab\u8bef\u53eb"
                + "\u53c2\u6218\uff09\u6216\u00a7e\u4f60\u653b\u51fb\u4e86\u654c\u5bf9\u751f\u7269\u00a7r\u65f6\uff0c\u9644\u8fd1"
                + "\uff08\u9ed8\u8ba4 16 \u683c\uff09\u7684\u5973\u4ec6\u65e0\u8bba\u5728\u5e72\u4ec0\u4e48\u2014\u2014\u6316\u77ff"
                + "/\u4f10\u6728/\u70e7\u5236/\u5efa\u9020/\u8ddf\u968f\u2014\u2014\u90fd\u7acb\u5373\u5207\u6218\u6597\u6a21\u5f0f"
                + "\u6765\u4fdd\u62a4\u4f60\uff1b\u6253\u725b\u7f8a\u7b49\u00a7e\u88ab\u52a8\u751f\u7269\u4e0d\u7b97\u5f00\u6218"
                + "\u00a7r\u2014\u2014\u5bb0\u7272\u755c\u4e0d\u4f1a\u8ba9\u5168\u5458\u62d4\u5200\uff1b\u6b63\u4e0e\u4f60\u4eec"
                + "\u00a7e\u4ea4\u6076\u7684\u4e2d\u7acb\u751f\u7269\u00a7r\uff08\u8bb0\u4ec7\u7684\u72fc/\u871c\u8702/\u5317\u6781"
                + "\u718a\u7b49\uff09\u6309\u4ea4\u6218\u5bf9\u8c61\u5904\u7406\uff1a\u5b83\u4eec\u52a8\u624b\u4f1a\u89e6\u53d1"
                + "\u53c2\u6218\u3001\u8fd8\u539f\u5224\u5b9a\u4e5f\u628a\u8bb0\u4ec7\u72b6\u6001\u7684\u5b83\u4eec\u7b97\u4f5c"
                + "\u5a01\u80c1\u2014\u2014\u5e73\u9759\u6001\u7684\u7167\u6837\u4e0d\u7b97\uff1b\u00a7e\u5973\u4ec6\u81ea\u5df1"
                + "\u88ab\u602a\u7269\u653b\u51fb\u00a7r\u4e5f\u4f1a\u8ba9\u5979\u672c\u4eba+\u5468\u56f4\u59d0\u59b9\u7acb\u5373"
                + "\u53c2\u6218\u3002\u9009\u4ec0\u4e48\u6218\u6597\u6a21\u5f0f\uff1a\u626b\u63cf\u5979\u80cc\u5305\u80fd\u7528"
                + "\u7684\u00a7e\u6240\u6709\u653b\u51fb\u7c7b\u4efb\u52a1\u00a7r\uff08\u542b\u4e07\u6cd5\u7686\u901a/\u53f2\u8bd7"
                + "\u6218\u6597/\u771f\u6b63\u7684\u529b\u91cf\u7b49\u6a21\u7ec4\u653b\u51fb\u4efb\u52a1\u4e0e\u67aa\u68b0\uff09"
                + "\u2014\u2014\u00a7e\u80cc\u5305\u91cc\u6709\u6a21\u7ec4\u6b66\u5668\u65f6\u5fc5\u5b9a\u5207\u5b83\u4e13\u5c5e"
                + "\u7684\u6218\u6597\u4efb\u52a1\u00a7r\uff08\u62d4\u5200\u5251\u2192\u62d4\u5200\u5251\u6a21\u5f0f\u3001\u53f2"
                + "\u8bd7\u6218\u6597\u2192\u6218\u6597\u6a21\u5f0f\uff0c\u5019\u9009\u6c60\u53ea\u7559\u6a21\u7ec4\u4efb\u52a1"
                + "\uff0c\u7edd\u4e0d\u4f1a\u968f\u673a\u56de\u9000\u5230\u666e\u901a\u653b\u51fb\uff1b\u5168\u662f\u539f\u7248"
                + "\u88c5\u5907\u65f6\u624d\u5728\u539f\u7248\u4e94\u4ef6\u5957\u91cc\u6309\u6743\u91cd\u968f\u673a\u2014\u2014"
                + "\u6a21\u7ec4\u4efb\u52a1\u6743\u91cd\u66f4\u9ad8\uff1b\u5168\u90fd\u5339\u914d\u4e0d\u4e0a=\u80cc\u5305\u6ca1"
                + "\u6709\u4efb\u4f55\u653b\u51fb\u7269\u54c1\uff0c\u5c31\u4e0d\u53c2\u6218\u3001\u7ef4\u6301\u539f\u4efb\u52a1"
                + "\u2014\u2014\u300c\u7a7a\u624b\u4e0d\u53c2\u6218\u300d\u5f00\u5173\u53ef\u6539\u56de\u7a7a\u624b\u8fd1\u6218"
                + "\u515c\u5e95\uff09\u3002\u654c\u4eba\u8fdc\uff08>5 \u683c\uff09\u9009\u8fdc\u7a0b\uff1b\u8fd1\u8eab\uff08\u22645"
                + " \u683c\uff09\u8fd1\u6218\u8fdc\u7a0b\u90fd\u6709\u65f6\u6309\u00a7e\u8fd1\u6218:\u8fdc\u7a0b\u504f\u597d\u6743"
                + "\u91cd\u00a7r\u968f\u673a\uff08\u9ed8\u8ba4 3:1 \u504f\u8fd1\u6218\uff0c\u53ef\u5728\u300c\u4e3b\u52a8\u5207"
                + "\u6362\u6218\u6597\u300d\u5c0f\u8282\u8c03\uff0c\u8bbe 0 = \u6c38\u4e0d\u9009/\u5207\u5411\u8be5\u7c7b\uff09"
                + "\u3002",
                "\u00a7e\u6218\u6597\u6a21\u5f0f\u5206\u7c7b\u8868\u00a7r\uff1a\u4e0a\u9762\u8fd9\u5957\u300c\u8c01\u80fd\u53c2"
                + "\u4e0e\u3001\u7b97\u8fd1\u6218\u8fd8\u662f\u8fdc\u7a0b\u3001\u6a21\u7ec4\u4efb\u52a1\u4f18\u5148\u300d\u9ed8"
                + "\u8ba4\u662f\u00a7e\u5185\u7f6e\u63a8\u65ad\u00a7r\uff0c\u4f60\u53ef\u4ee5\u5728\u00a7e\u300c\u6218\u6597\u4e0e"
                + "\u81ea\u4fdd \u2192 \u4e3b\u52a8\u53c2\u6218 \u2192 \u6a21\u5f0f\u5206\u7c7b\u8868\u300d\u00a7r\u91cc\u9010"
                + "\u4efb\u52a1\u70b9\u540d\uff0c\u4e00\u884c\u4e00\u6761\u00a7e\u4efb\u52a1UID=\u8fd1\u6218/\u8fdc\u7a0b/\u4e0d"
                + "\u53c2\u4e0e\u00a7r\uff08\u9017\u53f7\u5206\u9694\uff09\uff1a\u5199\u00a7e\u8fd1\u6218/\u8fdc\u7a0b\u00a7r = "
                + "\u5206\u7c7b\u4ee5\u8868\u4e3a\u51c6\uff08\u8fdb\u8fd1\u6218\u6c60\u8fd8\u662f\u8fdc\u7a0b\u6c60\uff09\uff0c"
                + "\u5e76\u4e14\u8fd9\u4e2a\u4efb\u52a1\u00a7e\u4e0d\u518d\u88ab\u300c\u6a21\u7ec4\u4efb\u52a1\u4f18\u5148\u8ba9"
                + "\u4f4d\u300d\u6324\u6389\u00a7r\uff08\u4f60\u70b9\u540d\u7684\u4f18\u5148\uff09\uff1b\u5199\u00a7e\u4e0d\u53c2"
                + "\u4e0e\u00a7r = \u81ea\u4e3b\u53c2\u6218\u4e0e\u6218\u4e2d\u6362\u6218\u672f\u90fd\u00a7e\u6c38\u4e0d\u9009"
                + "\u5b83\u00a7r\uff08\u60f3\u8ba9\u5b83\u53ea\u5728\u4f60\u624b\u52a8\u6307\u6d3e\u65f6\u4e0a\u573a\u5c31\u7528"
                + "\u8fd9\u6863\uff09\uff1b\u00a7e\u7559\u7a7a = \u6309\u5185\u7f6e\u63a8\u65ad\u00a7r\u3002\u65c1\u8fb9\u7684"
                + "\u00a7e\u6a21\u7ec4\u4efb\u52a1\u4f18\u5148\u8ba9\u4f4d\u00a7r\u5f00\u5173\uff08\u9ed8\u8ba4\u5f00\uff09= \u5019"
                + "\u9009\u6c60\u91cc\u6709\u6a21\u7ec4\u4e13\u5c5e\u4efb\u52a1\u65f6\u539f\u7248\u901a\u7528\u4e94\u4ef6\u5957"
                + "\u6574\u4f53\u8ba9\u4f4d\uff1b\u5173\u6389 = \u7eaf\u6309\u6743\u91cd\u968f\u673a\u3002\u4e0d\u77e5\u9053 UID "
                + "\u5199\u4ec0\u4e48\u5c31\u6267\u884c\u00a7e/maid_smart combat modes\u00a7r\uff1a\u5b83\u628a\u5f53\u524d\u6240"
                + "\u6709\u653b\u51fb\u7c7b\u4efb\u52a1\u3001\u5185\u7f6e\u7b97\u4ec0\u4e48\u3001\u8868\u91cc\u5199\u4e86\u4ec0"
                + "\u4e48\u3001\u53c2\u4e0d\u53c2\u4e0e\u5217\u6210\u4e00\u5f20\u8868\uff0c\u6284\u4e00\u884c\u6539\u4e00\u6539"
                + "\u5c31\u662f\u8868\u9879\uff08\u5199\u300c\u53c2\u4e0e\u300d\u4e5f\u00a7e\u4e0d\u4fdd\u8bc1\u4e00\u5b9a\u88ab"
                + "\u9009\u4e2d\u00a7r\u2014\u2014\u5979\u8fd8\u5fc5\u987b\u624b\u91cc\u6709\u90a3\u4e2a\u4efb\u52a1\u8ba4\u7684"
                + "\u6b66\u5668/\u5f39\u836f/\u6cd5\u672f\u88c5\u5907\uff0c\u90a3\u51e0\u9053\u95e8\u7167\u65e7\uff09\u3002",
                "\u00a7e\u5efa\u9020\u5973\u4ec6\u9ed8\u8ba4\u4e0d\u53c2\u6218\u00a7r\uff1a\u5904\u4e8e\u00a7e\u5efa\u9020\u4efb"
                + "\u52a1\uff08maid_smart:build\uff09\u00a7r\u7684\u5973\u4ec6\u00a7e\u4e0d\u4f1a\u88ab\u81ea\u4e3b\u6218\u6597"
                + "\u62d6\u53bb\u6253\u67b6\u00a7r\u2014\u2014\u5979\u90a3\u4e00\u6863\u7684\u73a9\u6cd5\u672c\u6765\u5c31\u662f"
                + "\u00a7e\u65e0\u9650\u6297\u6027 V + \u53d7\u51fb\u53d6\u6d88 + \u602a\u7269\u4e0d\u9501\u5979\u00a7r\uff08\u5efa"
                + "\u9020\u62a4\u76fe\uff09\uff0c\u628a\u5979\u5207\u53bb\u653b\u51fb\u53ea\u4f1a\u8ba9\u5979\u00a7e\u653e\u4e0b"
                + "\u5de5\u5730\u00a7r\uff0c\u800c\u4e14\u00a7e\u62a4\u76fe\u4f1a\u8ddf\u7740\u300c\u5f53\u524d\u4efb\u52a1\u300d"
                + "\u4e00\u8d77\u6d88\u5931\u00a7r\u3002\u60f3\u8ba9\u5979\u7167\u65e7\u53c2\u6218\uff1a\u5728\u00a7e\u6a21\u5f0f"
                + "\u5206\u7c7b\u8868\u00a7r\u91cc\u70b9\u540d\u00a7emaid_smart:build=\u8fd1\u6218\u00a7r\uff08\u6216\u00a7e\u8fdc"
                + "\u7a0b\u00a7r\uff09\u5373\u53ef\uff0c\u8868\u4f18\u5148\uff1b\u53e6\u5916\u00a7e\u5efa\u9020\u62a4\u76fe\u672c"
                + "\u8eab\u4e5f\u52a0\u56fa\u4e86\u00a7r\u2014\u2014\u53ea\u8981\u662f\u672c\u6a21\u7ec4\u628a\u5979\u5207\u53bb"
                + "\u53c2\u6218\u7684\uff08\u6218\u6597\u524d\u4efb\u52a1 = \u5efa\u9020\uff09\uff0c\u00a7e\u62a4\u76fe\u5728\u6574"
                + "\u573a\u6218\u6597\u91cc\u4e0d\u6389\u00a7r\uff0c\u4e24\u5904\u4e92\u4e0d\u4f9d\u8d56\u3002",
                "\u00a7e\u6218\u4e2d\u52a8\u6001\u6362\u6218\u672f\u00a7r\uff1a\u5f00\u6218\u540e\u6bcf\u79d2\u8bc4\u4f30\u4e00"
                + "\u6b21\u2014\u2014\u5979\u7528\u8fdc\u7a0b\u65f6\u654c\u4eba\u00a7e\u8fd1\u8eab\u00a7r\uff08\u22645 \u683c\uff09"
                + "\u4e14\u80cc\u5305\u6709\u8fd1\u6218\u7c7b\u6b66\u5668\uff08\u542b\u53f2\u8bd7\u6218\u6597/\u62d4\u5200\u5251"
                + "\u7b49\u6a21\u7ec4\u8fd1\u6218\uff09\u2192 \u00a7e\u7acb\u5373\u5207\u8fd1\u6218\u00a7r\uff1b\u5979\u7528\u8fd1"
                + "\u6218\u65f6\u654c\u4eba\u8fdc\u5230\u00a7e\u5927\u8df3\u90fd\u8df3\u4e0d\u8fc7\u53bb\u00a7r\uff08>6 \u683c"
                + "\uff09\u4f46\u8fd8\u5728\u7d22\u654c\u8303\u56f4\uff08\u226416 \u683c\uff09\u2192 \u00a7e\u5207\u8fdc\u7a0b"
                + "\u653e\u98ce\u7b5d\u00a7r\u30025~6 \u683c\u6ede\u56de\u5e26\u9632\u6765\u56de\u6a2a\u8df3\uff1b\u00a7e\u8fd1"
                + "\u8fdc\u4e92\u6362\u5bf9\u6a21\u7ec4\u4efb\u52a1\u4e5f\u751f\u6548\u00a7r\uff1a\u6a21\u7ec4\u4efb\u52a1\u53ef"
                + "\u88ab\u5207\u5165\u3001\u4e5f\u53ef\u88ab\u6362\u51fa\uff0c\u7167\u5e38\u6309\u8ddd\u79bb\u5224\u8fd1\u8fdc"
                + "\u2014\u2014\u00a7e\u53ea\u60f3\u8ba9\u67d0\u4e9b\u6a21\u5f0f\u5b8c\u5168\u4e0d\u53c2\u4e0e\u81ea\u52a8\u5207"
                + "\u6362\uff0c\u5c31\u628a\u5b83\u4eec\u5199\u8fdb\u4e0a\u9762\u7684\u300c\u6a21\u5f0f\u5206\u7c7b\u8868\u300d= "
                + "\u4e0d\u53c2\u4e0e\u00a7r\uff1b\u8fd8\u539f\u65f6\u7167\u5e38\u5207\u56de\u6218\u6597\u524d\u539f\u4efb\u52a1"
                + "\uff0c\u4e0d\u53d7\u6218\u4e2d\u6362\u6b66\u5668\u5f71\u54cd\u3002\u00a7e\u8fd8\u539f\u65f6\u8fde\u300c\u9a7b"
                + "\u5b88 / \u8ddf\u968f\u300d\u4e0e\u5979\u5f53\u65f6\u7684\u4f5c\u606f\u4e00\u8d77\u8fd8\u539f\u00a7r\uff1a\u00a7"
                + "e\u6ca1\u8bb0\u5f55\u8fc7\u5feb\u7167\u5c31\u5b8c\u5168\u4e0d\u52a8\u5979\u7684\u8bbe\u7f6e\u00a7r\uff0c\u8fd8"
                + "\u539f\u540e\u8fd0\u884c\u65e5\u5fd7\u91cc\u4f1a\u5199\u4e00\u884c\u300c\u6218\u6597\u524d\u6a21\u5f0f\u5df2"
                + "\u8fd8\u539f\uff1a\u9a7b\u5b88\uff08home\uff09=\u5f00/\u8ddf\u968f\u300d\u53ef\u5bf9\u8d26\uff1b\u00a7e\u9632"
                + "\u6296\u00a7r\uff1a\u6362\u6218\u672f\u6709\u00a7e\u6700\u77ed\u6301\u6709\u00a7r\u4e0e\u00a7e\u53cd\u5411\u51b7"
                + "\u5374\u00a7r\uff08\u6a2a\u8df3\u5224\u5b9a\u540e\u4fdd\u6301\u5f53\u524d\u6218\u672f\u786c\u6253\u4e00\u6bb5"
                + "\u65f6\u95f4\uff09\uff0c\u6570\u503c\u90fd\u53ef\u5728\u300c\u4e3b\u52a8\u5207\u6362\u6218\u6597\u300d\u5c0f"
                + "\u8282\u8c03\u3002\u00a7e\u8fd8\u539f\u5bbd\u9650\u00a7r\uff1a\u6218\u6597\u7ed3\u675f\u8fd8\u539f\u540e\uff0c"
                + "\u6392\u73ed\u7b49\u51e0\u79d2\u624d\u63a5\u7ba1\uff08\u9632\u5a01\u80c1\u95ea\u70c1\u62c9\u626f\uff09\uff0c"
                + "\u65f6\u957f\u5728\u300c\u6392\u73ed\u8868\u300d\u5c0f\u8282\u8c03\u3002\u5a01\u80c1\u6d88\u5931\u7ea6 10 \u79d2"
                + "\u540e\u81ea\u52a8\u5207\u56de\u539f\u4efb\u52a1\uff08\u6316\u77ff\u7684\u7ee7\u7eed\u6316\uff1b\u5ef6\u8fdf"
                + "\u53ef\u5728\u300c\u4e3b\u52a8\u5207\u6362\u6218\u6597\u300d\u5c0f\u8282\u8c03\uff09\u3002\u6218\u6597\u4e2d"
                + "\u4f60\u00a7e\u624b\u52a8\u7ed9\u5979\u6362\u7684\u4efb\u52a1\u4e0d\u4f1a\u88ab\u81ea\u52a8\u8fd8\u539f\u7ffb"
                + "\u56de\u53bb\u00a7r\u2014\u2014\u7cfb\u7edf\u53d1\u73b0\u4efb\u52a1\u88ab\u6362\u8fc7\u5c31\u53ea\u9000\u51fa"
                + "\u3001\u4e0d\u52a8\u5979\uff1b\u5224\u5b9a\"\u5a01\u80c1\u6d88\u5931\"\u7528\u72ec\u7acb\u7684\u5c0f\u5a01\u80c1"
                + "\u534a\u5f84\uff08\u9ed8\u8ba4 8 \u683c\uff0c\u8fdc\u5904\u7684\u602a\u4e0d\u5f71\u54cd\u5979\u6536\u5de5\u56de"
                + "\u5c97\uff09\uff1b",
                "\u00a7e\u50f5\u5c40\u9003\u9038\u00a7r\uff1a\u602a\u5361\u5728\u5899\u540e/\u73bb\u7483\u540e/\u4f20\u9001\u95e8"
                + "\u91cc\u7b49\u6740\u4e0d\u6389\u4e5f\u591f\u4e0d\u7740\u7684\u4f4d\u7f6e\u65f6\uff0c\u8d85\u8fc7 60 \u79d2\u53cc"
                + "\u65b9\u6ca1\u6709\u4efb\u4f55\u4f24\u5bb3\u5f80\u6765 \u2192 \u4e0d\u518d\u5e72\u7b49\uff0c\u7167\u5e38\u8fd8"
                + "\u539f\u56de\u5c97\uff08\u65f6\u957f\u53ef\u8c03\uff0c0=\u5173\u95ed\uff09\uff1b\u00a7e\u52a8\u6001\u5a01\u80c1"
                + "\u5708\u00a7r\uff1a\u6700\u8fd1\u6253\u8fc7\u5979\u7684\u602a\u5c31\u7b97\u7ad9\u5728 8 \u683c\u534a\u5f84\u5916"
                + "\uff08\u226432 \u683c\uff09\uff0c\u77ed\u65f6\u95f4\u5185\u5a01\u80c1\u5708\u81ea\u52a8\u653e\u5927\u628a\u5b83"
                + "\u5305\u542b\u8fdb\u6765\u2014\u2014\u8fdc\u7a0b\u602a\u653e\u98ce\u7b5d\u538b\u7740\u6253\u65f6\u5979\u4fdd"
                + "\u6301\u6218\u6597\u8fd8\u51fb\uff0c\u4e0d\u4f1a\"\u521a\u8fd8\u539f\u53c8\u4e2d\u7bad\"\u6765\u56de\u6a2a\u8df3"
                + "\uff1b",
                "\u00a7e\u9694\u7740\u65b9\u5757\u7684\u602a\u4e0d\u7b97\u5a01\u80c1\u00a7r\uff1a\u5979\u53ea\u628a\u00a7e\u770b"
                + "\u5f97\u89c1\u00a7r\uff08\u539f\u7248\u53e3\u5f84\u7684\u89c6\u7ebf\u5224\u5b9a\uff0c\u88ab\u65b9\u5757\u6321"
                + "\u4f4f\u7684\u4e0d\u7b97\uff09\u53c8\u00a7e\u6b63\u9501\u5b9a\u4f60\u6216\u5979\u00a7r\u7684\u751f\u7269\u5f53"
                + "\u5a01\u80c1\u2014\u2014\u5730\u9762\u4e0b\u7a7a\u6d1e\u91cc\u7684\u50f5\u5c38\u3001\u5899\u90a3\u5934\u7684"
                + "\u602a\u4e0d\u4f1a\u88ab\u5199\u8fdb\u5979\u7684\u653b\u51fb\u76ee\u6807\uff1b\u00a7eALEX \u8fd9\u7c7b\u6a21"
                + "\u7ec4\u751f\u7269\u6253\u4f60\u7b97\u5a01\u80c1\u00a7r\uff1a\u539f\u7248\u5973\u4ec6\u7684\u7d22\u654c\u6709"
                + "\u4e00\u9053\u00a7e\u7c7b\u578b\u95f8\u00a7r\u2014\u2014\u53ea\u8ba4\u00a7e\u654c\u5bf9\u63a5\u53e3\u00a7r\u7684"
                + "\u751f\u7269\uff0c\u5176\u4f59\u8981\u4e48\u5f53\u00a7e\u53cb\u65b9\u00a7r\uff08\u53ef\u9a6f\u670d\u52a8\u7269"
                + "\u3001\u6751\u6c11\uff09\u76f4\u63a5\u653e\u8fc7\uff0c\u8981\u4e48\u5f53\u00a7e\u4e2d\u7acb\u00a7r\uff08\u53ea"
                + "\u6709\u5b83\u6b63\u597d\u5728\u300c\u6700\u8fd1\u6253\u8fc7\u8c01\u300d\u7684\u65e7\u8d26\u91cc\u624d\u8ba4"
                + "\uff09\u3002ALEX \u7684\u751f\u7269\uff08\u864e/\u7070\u718a/\u9cc4\u9c7c/\u7280\u725b/\u5927\u8c61/\u5927\u7329"
                + "\u7329\u2026\uff09\u6ca1\u6709\u4e00\u4e2a\u662f\u654c\u5bf9\u63a5\u53e3\uff0c\u4e8e\u662f\u5b83\u4eec\u6251"
                + "\u4e0a\u6765\u54ac\u4f60\u65f6\u5973\u4ec6\u00a7e\u4e00\u70b9\u53cd\u5e94\u90fd\u6ca1\u6709\u00a7r\u3002\u672c"
                + "\u6a21\u7ec4\u52a0\u4e86\u00a7e\u884c\u4e3a\u5316\u4f8b\u5916\u00a7r\uff1a\u00a7e\u53ea\u8981\u5b83\u6b64\u523b"
                + "\u6b63\u9501\u5b9a\u4f60\u6216\u5979\u3001\u6216\u521a\u6253\u8fc7\u4f60/\u5979\uff085 \u79d2\u5185\u3001\u4e14"
                + "\u771f\u7684\u6389\u4e86\u8840\uff09\u00a7r\uff0c\u4e0d\u7ba1\u5b83\u662f\u4ec0\u4e48\u7c7b\u578b\u7c7b\uff0c"
                + "\u5973\u4ec6\u90fd\u4f1a\u628a\u5b83\u5f53\u654c\u4eba\u8fce\u51fb\u3002\u5e73\u9759\u7684\u751f\u7269\u3001"
                + "\u4f60\u7684\u5ba0\u7269/\u53cb\u519b\u7167\u65e7\u4e0d\u78b0\uff1b",
                "\u00a7e0 \u4f24\u5bb3\u7684\u653b\u51fb\u4e0d\u7b97\u6570\u00a7r\uff1a\u671d\u4f60\u6254\u96ea\u7403/\u9e21"
                + "\u86cb\u8fd9\u7c7b\u4f24\u5bb3\u6052 0 \u7684\u5a31\u4e50\u5f39\u5c04\u7269\u4e0d\u7b97\u88ab\u653b\u51fb\uff0c"
                + "\u00a7e\u8fd9\u4e00\u8bb0\u5fc5\u987b\u771f\u7684\u6389\u8fc7\u8840\u00a7r\u624d\u7b97\uff1b\u5bf9\u4efb\u4f55"
                + "\u6a21\u7ec4\u7684\u300c\u9b54\u6539\u88ab\u52a8\u751f\u7269\u300d\u4e00\u5e76\u751f\u6548\uff1b\u00a7e\u6218"
                + "\u6597\u65f6\u4e34\u65f6\u6269\u5708\u00a7r\uff1a\u6392\u73ed/\u5728\u5bb6\u6a21\u5f0f\uff08\u4e0d\u8ddf\u968f"
                + "\uff09\u4e0b\u7684\u00a7e\u300c\u5de5\u4f5c\u8303\u56f4\u300d\u5708\u00a7r\u5728\u5979\u63a5\u6218\u671f\u95f4"
                + "\u4e34\u65f6\u653e\u5927\u5230\u00a7e\u6218\u6597\u65f6\u4e34\u65f6\u6269\u5708\u00a7r\uff08\u9ed8\u8ba4 32 "
                + "\u683c\uff0c\u53d6 max(\u672c\u503c, \u5f53\u524d\u534a\u5f84)\uff09\u2014\u2014\u539f\u7248\u6bcf 40 tick "
                + "\u68c0\u67e5\u4e00\u6b21\u300c\u79bb\u5708\u5fc3\u8d85\u8fc7 (\u534a\u5f84+4) \u683c\u5c31\u76f4\u63a5\u628a"
                + "\u5979\u4f20\u9001\u56de\u5de5\u4f4d\u300d\uff0c\u8ffd\u602a\u7684\u8fd1\u6218\u5973\u4ec6\u4f1a\u88ab\u53cd"
                + "\u590d\u62fd\u56de\u53bb\uff1b\u6269\u5708\u540e\u5979\u80fd\u628a\u4ed7\u6253\u5b8c\uff0c\u00a7e\u6218\u6597"
                + "\u7ed3\u675f\uff08\u76ee\u6807\u6d88\u5931 / \u6328\u6253\u540e 5 \u79d2\uff09\u81ea\u52a8\u843d\u56de\u00a7r"
                + "\u4f60\u8bbe\u7f6e\u7684\u6b63\u5e38\u5de5\u4f5c\u8303\u56f4\uff0c\u4e0d\u9700\u8981\u4efb\u4f55\u6536\u5c3e"
                + "\u64cd\u4f5c\uff1b\u6709\u6392\u73ed\u8868\u7684\u5973\u4ec6\u8fd8\u539f\u65f6\u76f4\u63a5\u4ea4\u7ed9\u6392"
                + "\u73ed\u5f53\u524d\u6bb5\u3002\u5f00\u5173\u5728\u300c\u6218\u6597\u4e0e\u81ea\u4fdd \u2192 \u4e3b\u52a8\u53c2"
                + "\u6218\u300d\u5c0f\u8282\uff1a\u603b\u5f00\u5173/\u54cd\u5e94\u534a\u5f84/\u81ea\u52a8\u8fd8\u539f/\u8fd8\u539f"
                + "\u5ef6\u8fdf/\u8fd8\u539f\u5a01\u80c1\u534a\u5f84/\u50f5\u5c40\u9003\u9038/\u6218\u6597\u65f6\u4e34\u65f6\u6269"
                + "\u5708/\u6a21\u5f0f\u5206\u7c7b\u8868/\u6a21\u7ec4\u4efb\u52a1\u4f18\u5148\u8ba9\u4f4d\u90fd\u53ef\u8c03\u3002",
                "\u00a7e\u5ba0\u7269\u514d\u4f24\u00a7r\uff08\u81ea\u52a8\u751f\u6548\uff0c\u65e0\u9700\u5f00\u5173\uff09\uff1a\u5973\u4ec6\u628a\u4e09\u7c7b\u751f\u7269\u5f53\u300c\u81ea\u5bb6\u5ba0\u7269\u300d\u2014\u2014\u2460 \u00a7e\u540d\u5b57\u5e26\u300c\u73a9\u5bb6\u5ba0\u7269\u300d\u6216\u300c\u4e3b\u4eba\u7684\u5ba0\u7269\u300d\u5b57\u6837\u00a7r\u7684\u751f\u7269\uff1a\u7528\u547d\u540d\u724c/\u94c1\u7827\u7ed9\u602a\u6539\u540d\u5373\u53ef\uff0c\u6539\u540d\u540e\u5979\u4e0d\u518d\u9501\u5b9a\u3001\u4e0d\u518d\u653b\u51fb\uff0c\u6e85\u5c04/\u7fa4\u4f53\u4f24\u5bb3\u4e5f\u4e0d\u8bef\u4f24\uff0c\u4ec7\u6068\u81ea\u52a8\u6e05\u9664\uff1b\u2461 \u00a7e\u4e3b\u4eba\u9a6f\u670d\u7684\u52a8\u7269\u00a7r\uff1a\u732b/\u72d7/\u72fc/\u9a6c\u7b49\u4efb\u4f55\u53ef\u9a6f\u670d\u751f\u7269\uff0c\u5bbf\u4e3b\u662f\u4f60\u5373\u81ea\u52a8\u8bc6\u522b\uff08\u4e0d\u7528\u6539\u540d\uff09\uff1b\u2462 \u00a7e\u5176\u4ed6\u6a21\u7ec4\u6253\u4e86\u5ba0\u7269\u4fdd\u62a4\u6807\u8bb0\u00a7r\u7684\u751f\u7269\uff08\u6309\u4fdd\u62a4\u6807\u8bb0\u8bc6\u522b\uff09\u3002",
                "\u00a7e【举例】观察自保：\u00a7r",
                "让女仆去打一只僵尸，故意不帮忙——她血量掉到 30% 以下会开始喝药/垫高/逃跑，"
                        + "威胁消失且血回安全线后才恢复正常（latest.log 搜 self-preserve 可看决策）。");
    }

    static GuideContent.Chapter aidGuide() {
        return new GuideContent.Chapter("贴身辅助（投喂 / 治疗 / 盾牌）",
                "主人靠近女仆（16 格内）时，她会自动照顾你——这是\u00a7e被动技能\u00a7r，不用切任何任务。"
                        + "总开关在「战斗与自保 → 贴身辅助」小节。",
                "\u00a7e\u2460 \u81ea\u52a8\u6295\u5582\u00a7r\uff1a\u4f60\u9971\u98df\u5ea6\u4f4e\u4e8e\u9608\u503c\uff08\u9ed8\u8ba4 12\uff0c\u53ef\u8bbe 4~20\uff09\u65f6\u81ea\u52a8\u5582\u2014\u2014\u00a7e\u76f4\u63a5\u5582\u8fdb\u9971\u98df\u5ea6\u00a7r\uff0c\u6709\u5403/\u559d\u97f3\u6548 + \u7cfb\u7edf\u6d88\u606f\u300c\u5973\u4ec6\u5582\u4f60\u5403\u4e86 X\u300d\u3002\u5973\u4ec6\u00a7e\u624b\u6301\u7684\u719f\u98df\u4e5f\u4f1a\u5582\u00a7r\uff08\u62ff\u5728\u624b\u4e0a\u7684\u8089\u6392\u4e00\u6837\u7b97\uff09\uff1b",
                "\u00a7e② 自动治疗\u00a7r：你血量低于阈值（默认 30%，可设 0.1~1.0）时走治疗链——"
                        + "扔喷溅治疗药水 → 金苹果 → 扔再生药水 → 塞普通治疗药水 → 喂高饱食物；",
                "\u00a7e③ 负面效果解除\u00a7r：你中毒/凋零等负面效果时喂牛奶（清全部效果，有增益时自动改喂蜂蜜只解中毒）"
                        + "——优先级在治疗之前；",
                "\u00a7e④ 情境保命\u00a7r：你着火投抗火药水、溺水投水肺药水（优先级最高）；",
                "\u00a7e⑤ 共享盾牌 / 不死图腾\u00a7r：你盾牌快坏时从她背包取新盾；你致命伤时她的图腾优先救你；",
                "\u00a7e⑥ 玩家对女仆伤害模式\u00a7r：TLM 原版（÷5 封顶 2）/ 完全免疫 / 无限制 / 有上限 / 仅一点。",
                "\u00a7e\u2466 \u5973\u4ec6\u4e4b\u95f4\u4e92\u76f8\u652f\u63f4\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u540c\u4e00\u4e3b\u4eba\u7684\u5973\u4ec6\u5728 16 \u683c\u5185\uff0c\u6709\u59d0\u59b9\u4f4e\u8840/\u7740\u706b/\u4e2d\u6bd2\u65f6\u4e5f\u4f1a\u00a7e\u4e92\u76f8\u6295\u836f\u6c34\u3001\u91d1\u82f9\u679c\u3001\u5582\u98df\u00a7r\uff08\u4e0e\u7167\u987e\u4e3b\u4eba\u540c\u4e00\u5957\u65b9\u6848\uff0c\u4e3b\u4eba\u6c38\u8fdc\u4f18\u5148\uff09\uff1b\u4e0d\u60f3\u8ba9\u5979\u4eec\u4e92\u76f8\u5206\u836f\u53ef\u4ee5\u5728\u8fd9\u884c\u5173\u6389\u2014\u2014\u5173\u95ed\u540e\u5973\u4ec6\u53ea\u7167\u987e\u4e3b\u4eba\u3002",
                "\u00a7e\u2467 \u652f\u63f4\u5176\u4ed6\u53cb\u65b9\u5355\u4f4d\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u652f\u63f4\u8303\u56f4\u4ece\u00a7e\u53ea\u652f\u63f4\u5973\u4ec6\u00a7r\u6269\u5230\u00a7e\u5176\u4ed6\u53cb\u65b9\u5355\u4f4d\u00a7r\u2014\u2014\u00a7e\u4e3b\u4eba\u7684\u5176\u4ed6\u5ba0\u7269\u00a7r\uff08\u539f\u7248\u72fc/\u732b/\u9a6c\u7b49\uff09\u4e0e\u00a7e\u540c\u4e3b\u4eba\u7684\u6a21\u7ec4\u4ec6\u4ece\u00a7r\uff08\u5982\u8be1\u5384\u5deb\u6cd5\u7684\u7ea2\u77f3\u5de8\u517d\uff09\u4f4e\u8840/\u7740\u706b/\u4e2d\u6bd2\u65f6\uff0c\u4e5f\u4f1a\u00a7e\u6295\u836f\u6c34\u3001\u5582\u91d1\u82f9\u679c\u3001\u5582\u725b\u5976\u8702\u871c\u00a7r\u3002\u53e3\u5f84\u662f\u00a7e\u5f52\u5c5e\u540c\u4e00\u4f4d\u4e3b\u4eba\u00a7r\u2014\u2014\u8fd9\u6b63\u662f\u539f\u7248\u5ba0\u7269\u4e0e\u6a21\u7ec4\u4ec6\u4ece\u7684\u5171\u540c\u7279\u70b9\uff08\u90fd\u5b9e\u73b0\u539f\u7248 \u00a7eOwnableEntity\u00a7r\uff09\uff1a\u539f\u7248\u72fc/\u732b/\u9a6c\u4e0e\u8be1\u5384\u4ec6\u4ece\u5168\u5728\u8fd9\u6761\u63a5\u53e3\u4e0a\uff0c\u51e1\u4e3b\u4eba\u540d\u4e0b\u7684\u5355\u4f4d\u90fd\u7b97\u53cb\u519b\u3002\u5b83\u4eec\u00a7e\u6ca1\u6709\u9965\u997f\u503c\u00a7r\uff0c\u6240\u4ee5\u53ea\u7ed9\u836f\u6c34/\u91d1\u82f9\u679c/\u725b\u5976\u8702\u871c\u8fd9\u6837\u7684\u00a7e\u6cbb\u7597\u4e0e\u6548\u7528\u7269\u54c1\u00a7r\uff0c\u00a7e\u4e0d\u5582\u666e\u901a\u98df\u7269\u3001\u4e0d\u7ed9\u4e0d\u6b7b\u56fe\u817e\u00a7r\uff08\u6bd4\u5973\u4ec6\u95f4\u652f\u63f4\u6b63\u597d\u5c11\u8fd9\u4e24\u6837\uff09\uff1b\u5173\u6389 = \u53ea\u652f\u63f4\u4e3b\u4eba\u4e0e\u5973\u4ec6\u3002",
                "\u00a7e\u2468 \u652f\u63f4\u54c1\u5206\u7c7b\u8868\uff08\u901a\u7528 / \u4ea1\u7075\u4e24\u5f20\uff09\u00a7r"
                + "\uff1a\u5973\u4ec6\u6295\u7684\u836f\u6c34/\u91d1\u82f9\u679c/\u725b\u5976\u8702\u871c\u53ef\u4ee5\u6309\u56db"
                + "\u7c7b\u81ea\u5df1\u7ba1\u2014\u2014\u00a7e\u5bf9\u7b56\u00a7r\uff08\u53ea\u5728\u5bf9\u5e94\u5904\u5883/debuff "
                + "\u51fa\u73b0\u65f6\u7528\uff1a\u6297\u706b\u3001\u6c34\u80ba\u3001\u725b\u5976\u8702\u871c\uff09\u3001\u00a7e"
                + "\u589e\u76ca\u00a7r\uff08\u6218\u5c40\u4e00\u5f00\u59cb\u5c31\u80fd\u7528\uff1a\u529b\u91cf/\u8fc5\u6377\u7b49"
                + "\uff09\u3001\u00a7e\u56de\u590d\u00a7r\uff08\u8840\u91cf\u4f4e\u4e8e\u300c\u6cbb\u7597\u89e6\u53d1\u8840\u91cf"
                + "\u300d\u65f6\u624d\u7528\uff1a\u6cbb\u7597/\u518d\u751f/\u91d1\u82f9\u679c\uff09\u3001\u00a7e\u7981\u7528\u00a7r"
                + "\u3002\u5728\u00a7e\u300c\u6218\u6597\u4e0e\u81ea\u4fdd \u2192 \u8d34\u8eab\u8f85\u52a9 \u2192 \u652f\u63f4"
                + "\u7269\u54c1\u5206\u7c7b\u300d\u00a7r\u4e00\u884c\u70b9\u300c\u6253\u5f00 \u2192\u300d\u8fdb\u53bb\u52fe\u9009"
                + "\uff0c\u4e0e\u6295\u5582\u98df\u7269\u540c\u6b3e\uff1b\u6761\u76ee\u5199\u6cd5\u5c31\u662f\u300c\u952e=\u5206"
                + "\u7c7b\u300d\uff08counter / buff / heal / off\uff09\uff0c\u836f\u6c34\u7684\u952e\u662f\u300c\u7269\u54c1id|"
                + "\u836f\u6c34id\u300d\u3002\u00a7e\u4ea1\u7075\u5355\u72ec\u4e00\u5f20\u8868\u00a7r\uff08\u6cbb\u7597\u836f\u6c34"
                + "\u5bf9\u4ea1\u7075\u662f\u6263\u8840\u3001\u4f24\u5bb3\u836f\u6c34\u624d\u662f\u56de\u8840\uff1b\u00a7e\u518d"
                + "\u751f\u5bf9\u4ea1\u7075\u65e0\u6548\u00a7r\u2014\u2014\u539f\u7248\u76f4\u63a5\u62d2\u6536\uff0c\u6240\u4ee5"
                + "\u81ea\u52a8\u7b97\u300c\u7981\u7528\u300d\uff09\u3002\u00a7e\u7559\u7a7a\u00a7r\uff1a\u5e38\u89c4\u98df\u7269"
                + "\u4e0d\u53d7\u672c\u8868\u7ba1\uff0c\u672a\u5199\u6761\u76ee\u7684\u652f\u63f4\u54c1\u6309\u6548\u679c\u81ea"
                + "\u52a8\u63a8\u65ad\u3002",
                "\u00a7e\u5f00\u5173\u300c\u652f\u63f4\u4ea1\u7075\u5355\u4f4d\u300d\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a"
                + "\u5173\u6389 = \u652f\u63f4\u94fe\u5b8c\u5168\u8df3\u8fc7\u4ea1\u7075\u76ee\u6807\uff08\u4e24\u5f20\u8868\u539f"
                + "\u6837\u4fdd\u7559\uff09\uff1b\u4e0e\u300c\u652f\u63f4\u5176\u4ed6\u53cb\u65b9\u5355\u4f4d\u300d\u4e92\u76f8"
                + "\u72ec\u7acb\uff0c\u90fd\u5f00\u624d\u652f\u63f4\u4ea1\u7075\u53cb\u519b\u3002\u00a7e\u5f00\u5173\u300c\u81ea"
                + "\u7528\u4e5f\u8d70\u652f\u63f4\u8868\u300d\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5973\u4ec6\u00a7e\u81ea"
                + "\u5df1\u00a7r\u559d\u836f\u6c34/\u5403\u98df\u7269\u65f6\u4e5f\u6309\u8fd9\u4e24\u5f20\u8868\u5224\u5b9a\u2014"
                + "\u2014\u4e0e\u300c\u652f\u63f4\u5973\u4ec6\u300d\u5171\u7528\u540c\u4e00\u4efd\u767d\u540d\u5355\uff1b\u5979"
                + "\u81ea\u5df1\u4e0d\u662f\u4ea1\u7075\u751f\u7269\uff0c\u6240\u4ee5\u81ea\u7528\u4e00\u5f8b\u8d70\u300c\u901a"
                + "\u7528\u300d\u8868\u3002\u5173\u6389 = \u81ea\u7528\u4e0d\u770b\u8fd9\u4e24\u5f20\u8868\uff0c\u4ecd\u6309\u6548"
                + "\u679c\u81ea\u52a8\u6311 + \u6cbb\u7597\u98df\u7269\u540d\u5355\u3002\u00a7e\u6ce8\u00a7r\uff1a\u9762\u677f"
                + "\u7b2c\u4e09\u7c7b\u5019\u9009\u300c\u81ea\u5e26\u6548\u679c\u7684\u666e\u901a\u98df\u7269\u300d\uff08\u4e09"
                + "\u660e\u6cbb\u8fd9\u7c7b\uff09\u76ee\u524d\u5230\u4e0d\u4e86\u652f\u63f4\u94fe\u2014\u2014\u652f\u63f4\u94fe"
                + "\u6309\u836f\u6c34/\u91d1\u82f9\u679c/\u725b\u5976\u8702\u871c\u4e09\u7c7b\u53d6\u7269\uff0c\u4e0d\u904d\u5386"
                + "\u5e26\u6548\u679c\u98df\u7269\uff0c\u6240\u4ee5\u5bf9\u5b83\u4eec\u6539\u5206\u7c7b\u6682\u65e0\u8fd0\u884c"
                + "\u65f6\u6548\u679c\uff1b\u666e\u901a\u98df\u7269\u80fd\u4e0d\u80fd\u5582\u4ecd\u7531\u300c\u6295\u5582\u98df"
                + "\u7269\u52fe\u9009\u300d\u7ba1\u3002\u00a7e\u5b50\u9875\u7248\u9762\u00a7r\uff1a\u7269\u54c1\u540d\u60ac\u505c"
                + "\u6846\u662f\u300c\u00a7f\u4e2d\u6587\u663e\u793a\u540d\u00a7r\uff08\u4f60\u81ea\u5df1\u8bed\u8a00\u4e0b\u7684"
                + "\u540d\u5b57\uff09\uff0b \u00a77\u6ce8\u518c\u540d\u00a7r\u300d\u4e24\u884c\u2014\u2014\u6ce8\u518c\u540d\u5c31"
                + "\u662f\u53ef\u76f4\u63a5\u586b\u8fdb\u767d\u540d\u5355\u8f93\u5165\u6846\u7684\u82f1\u6587\u5b57\u6bb5\uff1b"
                + "\u56db\u7c7b\uff08\u5bf9\u7b56/\u589e\u76ca/\u56de\u590d/\u7981\u7528\uff09\u7684\u8bf4\u660e\u5728\u9762\u677f"
                + "\u5e95\u90e8\u7684\u00a7e\u56fa\u5b9a\u56fe\u4f8b\u884c\u00a7r\uff1b\u7ffb\u9875\u7bad\u5934\u9760\u5de6\uff1b"
                + "\u7f51\u683c\u884c\u6570\u6309\u7a97\u53e3\u9ad8\u81ea\u9002\u5e94\u3002",
                "\u00a7e【举例】测试投喂（保姆式）：\u00a7r",
                "\u2460 \u914d\u7f6e\u9762\u677f \u2192 \u6218\u6597\u4e0e\u81ea\u4fdd \u2192 \u8d34\u8eab\u8f85\u52a9 \u2192 \u628a\u300c\u6295\u5582\u89e6\u53d1\u9971\u98df\u5ea6\u300d\u6539\u6210 20\uff08\u53ea\u8981\u4e0d\u6ee1\u5c31\u5582\uff09\u2192 \u4fdd\u5b58\u5e76\u8fd4\u56de\uff1b\u2461 \u7ed9\u5973\u4ec6\u80cc\u5305\u585e\u4e00\u5757\u719f\u725b\u6392\uff08\u6216\u8ba9\u5979\u62ff\u5728\u624b\u4e0a\uff09\uff1b\u2462 \u4f60\u628a\u81ea\u5df1\u997f\u5230 18\uff08\u8dd1\u51e0\u5708\uff09\uff1b\u2463 3 \u79d2\u5185\u5973\u4ec6\u4f1a\u5582\u4f60\u2014\u2014\u9971\u98df\u5ea6 +8\uff0c\u51fa\u73b0\u97f3\u6548\u548c\u7cfb\u7edf\u6d88\u606f\u300c\u5973\u4ec6\u5582\u4f60\u5403\u4e86 \u719f\u725b\u6392\u300d\uff1b\u2464 \u6ca1\u89e6\u53d1\uff1f\u770b latest.log \u641c aid feed\u2014\u2014\u65e5\u5fd7\u4f1a\u5199\u660e\u5f53\u524d\u9608\u503c\u3001\u4e3b\u4eba\u9971\u98df\u5ea6\u3001\u5582\u4e86\u4ec0\u4e48/\u4e3a\u4ec0\u4e48\u6ca1\u5582\u3002\u9608\u503c 4~20 \u4e4b\u95f4\u586b\u4efb\u4f55\u503c\u90fd\u771f\u5b9e\u751f\u6548\u3002",
                "\u8865\u5145\uff1a\u5979\u80cc\u5305\u6ca1\u98df\u7269/\u836f\u6c34\u65f6\u4e0d\u4f1a\u786c\u5582\uff0c\u4f1a\u00a7e\u64ad\u62a5\u300c\u7f3a\u5403\u7684\u300d\u00a7r\u63d0\u9192\u4f60\u5907\u8d27\uff08\u6c14\u6ce1 + \u7cfb\u7edf\u6d88\u606f\uff0c60 \u79d2\u4e00\u6b21\u4e0d\u5237\u5c4f\uff09\uff0c\u8bb0\u5f97\u7ed9\u5979\u5907\u8d27\u3002",
                "\u00a7e\u2467 \u6295\u5582\u98df\u7269\u52fe\u9009\uff08\u8ba4\u6a21\u7ec4\u98df\u7269\uff09\u00a7r\u2014\u2014\u6295\u5582\u4e0d\u9650\u5b9a\u539f\u7248\u98df\u7269\uff1a\u53ea\u8981\u7269\u54c1\u00a7e\u5e26\u98df\u7269\u5c5e\u6027\u00a7r\uff08`FoodProperties`\uff09\u5c31\u7b97\u80fd\u5582\u2014\u2014\u00a7e\u4e09\u660e\u6cbb\u3001\u6a21\u7ec4\u6599\u7406\u3001\u6a21\u7ec4\u6c34\u679c\u5168\u90fd\u8ba4\u00a7r\u3002",
                "\u00a7e\u6309\u300c\u5269\u4f59\u6b21\u6570\u300d\u7ec6\u5206\u00a7r\uff1a\u80fd\u5582/\u559d\u597d\u51e0\u6b21\u7684\u7269\u54c1\uff08\u6c34\u58f6\u8fd9\u7c7b\u8010\u4e45\u5bb9\u5668\uff09\u5728\u52fe\u9009\u9875\u91cc\u00a7e\u6bcf\u4e00\u6863\u5269\u4f59\u6b21\u6570\u5404\u5360\u4e00\u884c\u00a7r\u2014\u2014\u00a7e\u300c\u5269 4/4 \u6b21\u300d\u548c\u300c\u5269 3/4 \u6b21\u300d\u662f\u4e24\u4e2a\u72ec\u7acb\u6761\u76ee\u00a7r\uff0c\u5404\u81ea\u52fe\u9009\u4e92\u4e0d\u5f71\u54cd\uff08\u53ef\u4ee5\u53ea\u8ba9\u6ee1\u7684\u80fd\u5582\u3001\u5269 1 \u6b21\u7684\u522b\u5582\uff09\uff1b\u60ac\u505c\u4f1a\u5199\u660e\u300c\u5269\u4f59 N/M \u6b21\u300d\u3002\u540d\u5355\u6761\u76ee\u4e5f\u53ef\u4ee5\u624b\u5199\u00a7e\u300c\u5b8c\u6574\u6ce8\u518c\u540d#\u5269\u4f59\u6b21\u6570\u300d\u00a7r\uff0c\u4e0d\u5199 # \u5c31\u662f\u00a7e\u8be5\u7269\u54c1\u4efb\u610f\u6b21\u6570\u00a7r\u3002\n\u00b7 \u00a7e\u9057\u7269\u7c7b\u98df\u7269\u4e0d\u4f1a\u88ab\u5403\u6389\u00a7r\uff1a\u50cf\u5947\u5f02\u9970\u54c1\u7684\u00a7e\u300c\u6c38\u6052\u725b\u6392\u300d\u00a7r\u8fd9\u79cd\u00a7e\u7528\u5b8c\u4e0d\u6d88\u5931\u00a7r\u7684\u98df\u7269\uff0c\u6295\u5582\u65f6\u8d70\u7684\u662f\u00a7e\u7269\u54c1\u81ea\u5df1\u7684\u4f7f\u7528\u8def\u5f84\u00a7r\u2014\u2014\u5b83\u81ea\u5df1\u7684\u6548\u679c\u7167\u5e38\u751f\u6548\u3001\u7269\u54c1\u00a7e\u4e0d\u4f1a\u88ab\u6d88\u8017\u00a7r\uff0c\u5e76\u6309\u5b83\u81ea\u5df1\u7684\u51b7\u5374\u8282\u6d41\u3002",
                "\u00a7e怎么配置哪些能吃\u00a7r：\u00a7e「战斗与自保 → 贴身辅助 → 投喂食物勾选」\u00a7r一行点「打开 →」"
                        + "进入勾选页——\u00a7e列出全部带食物属性的物品（含全部模组食物）\u00a7r，"
                        + "\u00a7e点图标切换「能不能吃」\u00a7r：\u00a7a绿框 ✔ = 能喂\u00a7r、\u00a7c红框 ✖ = 不能吃\u00a7r"
                        + "（取消勾选 = 写进「投喂食物黑名单」）。支持搜索（中英文皆可）与翻页，"
                        + "底部实时显示「共 X 种食物，当前可喂 Y 种」；下方列表可一键把某个食物\u00a7e恢复成能吃\u00a7r。",
                "\u00a7e\u9ed8\u8ba4\u9ed1\u540d\u5355\u00a7r\uff08\u00a7a\u9ed8\u8ba4\u4e0d\u5582\u8fd9\u4e9b\u5783\u573e\u00a7r\uff09\uff1a\u8150\u8089\u3001\u8718\u86db\u773c\u3001\u6bd2\u9a6c\u94c3\u85af\u3001\u6cb3\u8c5a\u3001\u7d2b\u9882\u679c\u3001\u53ef\u7591\u7096\u83dc\u3001\u5404\u79cd\u00a7e\u751f\u8089\u751f\u9c7c\u00a7r\uff0c\u4ee5\u53ca\u00a7e\u91d1\u82f9\u679c/\u9644\u9b54\u91d1\u82f9\u679c\u00a7r\uff08\u91d1\u82f9\u679c\u7559\u7740\u8d70\u300c\u6cbb\u7597\u94fe\u300d\u90a3\u6761\u8def\uff0c\u4e0d\u5f53\u666e\u901a\u98df\u7269\u5582\u6389\uff09\u3002\u00a7e\u4e0d\u7965\u4e4b\u74f6\u00a7r\u4e5f\u9ed8\u8ba4\u62c9\u9ed1\u2014\u2014\u5b83\u80fd\u00a7e\u559d\u00a7r\u3001\u4f1a\u88ab\u5f53\u6210\u666e\u901a\u98df\u7269\uff0c\u4f46\u5582\u4e0b\u53bb\u7b49\u4e8e\u7ed9\u5979\u6302\u00a7c\u4e0d\u7965\u4e4b\u5146\u00a7r\uff08\u89e6\u53d1\u88ad\u51fb/\u8bd5\u70bc\uff09\uff0c\u56de\u9971\u98df\u5ea6\u4e0d\u8be5\u634e\u5e26\u8fd9\u4e2a\u3002\u9ed1\u540d\u5355\u5c31\u662f\u00a7e\u8fd9\u4e2a\u52fe\u9009\u9875\u7684\u7ed3\u679c\u00a7r\uff0c\u4f60\u968f\u65f6\u53ef\u6539\uff1b\u60f3\u5168\u90e8\u90fd\u80fd\u5582\u5c31\u628a\u5b83\u6e05\u7a7a\u3002",
                "\u00a7e【举例】让女仆喂模组食物：\u00a7r"
                        + "① 配置面板 → 战斗与自保 → 贴身辅助 → 「投喂食物勾选」点「打开 →」；"
                        + "② 搜索框输入 sandwich（或中文名）→ 找到那个三明治，确认它是\u00a7a✔\u00a7r（默认就是能喂）；"
                        + "③ 塞几个到女仆背包 → 饿到阈值以下 → 她就会喂你吃三明治。"
                        + "反过来：不想让她喂某样东西（比如你要留着的蛋糕），点一下变成 ✖ 即可。",
                "\u00a7e\u2468 \u5582\u6c34\uff08\u9700\u88c5\u300c\u53e3\u6e34\u300dThirst Was Taken\uff09\u00a7r\uff1a\u88c5\u4e86\u53e3\u6e34\u6a21\u7ec4\u540e\uff0c\u4f60\u53e3\u6e34\u503c\u4f4e\u4e8e\u9608\u503c\uff08\u9ed8\u8ba4 15\uff0c\u53ef\u8bbe 4~20\uff09\u65f6\u5979\u4f1a\u00a7e\u5582\u4f60\u559d\u6c34\u00a7r\u2014\u2014\u00a7e\u5224\u5b9a\u4f4d\u70b9\u5c31\u662f\u53e3\u6e34\u503c\u00a7r\uff0c\u6548\u679c\u4e0e\u73a9\u5bb6\u81ea\u5df1\u559d\u5b8c\u5168\u4e00\u81f4\uff1a\u6a21\u7ec4\u7684\u00a7e\u53e3\u6e34\u6062\u590d/\u7eaf\u5ea6\u7ed3\u7b97\u00a7r\u4e0e\u00a7e\u5bb9\u5668\u8fd4\u8fd8\u00a7r\uff08\u73bb\u7483\u74f6\u3001\u9676\u7897\u8fd9\u4e9b\u90fd\u7167\u5e38\u8fd8\uff09\u5168\u8d70\u539f\u7248\u559d\u7684\u8def\u5f84\u3002\u00a7e\u6ca1\u88c5\u8fd9\u4e2a\u6a21\u7ec4\u65f6\uff0c\u914d\u7f6e\u9875\u4e0e\u914d\u7f6e\u6587\u4ef6\u91cc\u90fd\u4e0d\u4f1a\u51fa\u73b0\u5582\u6c34\u76f8\u5173\u9879\u76ee\u00a7r\u3002",
                "\u00a7e喂水白名单\u00a7r：只喂名单里、且口渴模组认识（能回口渴值）的饮品"
                        + "（「战斗与自保 → 贴身辅助 → 喂水白名单」点\u00a7e「打开 →」\u00a7r在子页里勾选，"
                        + "与投喂食物的勾选页同款）——"
                        + "\u00a7e其他 mod 的装水容器\u00a7r（水袋、水壶、军用水壶之类）把注册名加进来即可；"
                        + "默认：\u00a7f水瓶\u00a7r、\u00a7f陶碗水\u00a7r；\u00a7cminecraft:potion 只认纯净水\u00a7r——"
                        + "其它药水（效果不可控）永不喂；留空 = 不喂水。",
                "\u00a7e\u5582\u6c34\u6c34\u8d28\u5206\u7ea7\u00a7r\uff1a\u53e3\u6e34\u6a21\u7ec4\u628a\u6c34\u5206\u6210\u56db\u6863\u2014\u2014\u00a7c\u80ae\u810f\u00a7r / \u00a7e\u6709\u70b9\u810f\u00a7r / \u00a7a\u53ef\u63a5\u53d7\u7684\u00a7r / \u00a7b\u7eaf\u51c0\u00a7r\u3002\u00a7e\u9ed8\u8ba4\u53ea\u5582\u300c\u53ef\u63a5\u53d7\u7684\u300d\u53ca\u4ee5\u4e0a\u00a7r\uff08\u810f\u6c34\u5582\u4e0b\u53bb\u53cd\u800c\u803d\u8bef\u4f60\uff09\uff1b\u8981\u6539\u5c31\u53bb\u00a7e\u300c\u6218\u6597\u4e0e\u81ea\u4fdd \u2192 \u8d34\u8eab\u8f85\u52a9 \u2192 \u5582\u6c34\u6700\u4f4e\u6c34\u8d28\uff080-3\uff09\u300d\u00a7r\u8c03\uff0c\u586b 0 = \u810f\u6c34\u4e5f\u5582\u3002\u00a7e\u53ea\u5bf9\u88c5\u6c34\u5bb9\u5668\u751f\u6548\u00a7r\uff08\u679c\u6c41/\u725b\u5976\u8fd9\u7c7b\u6ca1\u6709\u6c34\u8d28\u6982\u5ff5\u7684\u996e\u54c1\u4e0d\u53d7\u5f71\u54cd\uff09\uff0c\u5582\u6c34\u767d\u540d\u5355\u5b50\u9875\u91cc\u6bcf\u676f\u6c34\u4e5f\u4f1a\u6807\u51fa\u5b83\u7684\u6c34\u8d28\u3002");
    }

    static GuideContent.Chapter tacticsGuide() {
        return new GuideContent.Chapter("单兵战术（PVP 式战斗）",
                "\u7ed9\u6218\u6597\u5973\u4ec6\u7684\u00a7e\u8d70\u4f4d\u589e\u5f3a\u00a7r\uff08\u9ed8\u8ba4\u5f00\u542f\uff09\uff1a\u5979\u4f1a\u50cf\u73a9\u5bb6\u4e00\u6837\u8d70\u4f4d\u5bf9\u6253\uff0c\u4e0d\u4f1a\u50bb\u7ad9\u7740\u5bf9\u780d\u3002",
                "近战：贴脸绕圈侧移（少正面挨刀）、打一刀退一步（hit & run 拉扯）、接近时跳劈；",
                "远程：保持理想射程放风筝（原版会走到怪脸上射）、横移绕圈；",
                "举盾：攻击冷却间隙举盾格挡、冷却满放盾攻击（攻防交替，替代原版 8 格内一直举盾）；",
                "\u00a7e\u8fd1\u6218\u8d34\u8138\u540e\u9000\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u654c\u4eba\u8d34\u8fdb 2 \u683c\u5185\u4e3b\u52a8\u540e\u9000\u62c9\u5f00\u2014\u2014\u5973\u4ec6\u624b\u957f 3 \u683c\uff0c\u9000\u5f00\u540e\u7167\u6837\u780d\u5f97\u5230\uff0c\u540c\u65f6\u8131\u79bb\u654c\u4eba\u8fd1\u6218\u8303\u56f4\u4e0d\u518d\u767d\u6328\u5200\u3002",
                "\u00a7e【举例】看剑的跳劈：\u00a7r",
                "\u7ed9\u5973\u4ec6\u4e00\u628a\u5251\uff0c\u8ba9\u5979\u653b\u51fb\u4e00\u53ea\u50f5\u5c38\u2014\u2014\u5355\u53ea\u654c\u4eba\u65f6\u653b\u51fb\u51b7\u5374\u6ee1\u5fc5\u8df3\u5288\uff08\u7a7a\u4e2d\u66b4\u51fb 1.5 \u500d\uff0c\u5355\u654c\u8df3\u5288 100%\uff09\uff0c\u8df3\u5288\u95f4\u9699\u81ea\u52a8\u7a7f\u63d2\u6a2a\u626b/\u666e\u653b\uff1b\u88ab\u8d34\u8138\u65f6\u5979\u4f1a\u5148\u9000\u5f00\u4e24\u6b65\u518d\u6253\u3002",
                "\u00a7e\u67aa\u68b0\u6218\u672f\u00a7r\uff1a\u88c5\u4e86 TACZ \u6216\u5353\u8d8a\u524d\u7ebf\uff08Superb Warfare\uff09\u65f6\uff0c\u7ed9\u5973\u4ec6\u5207\u300c\u67aa\u68b0\u300d\u4efb\u52a1\uff08TLM \u5185\u7f6e\uff09\u2014\u2014\u5979\u81ea\u52a8\u6301\u67aa\u3001\u641c\u5f39\u836f\u3001\u6362\u5f39\u5f00\u67aa\uff0c\u4e0a\u9762\u7684\u8fdc\u7a0b\u6218\u672f\u00a7e\u5168\u5957\u7167\u5e38\u751f\u6548\u00a7r\uff1a\u4fdd\u6301\u7406\u60f3\u5c04\u7a0b\u653e\u98ce\u7b5d\uff08\u8fdc\u4e86\u8ffd\u3001\u8fd1\u4e86\u9000\u3001\u6a2a\u79fb\u7ed5\u5708\uff09\uff0c\u67aa\u68b0\u7684\u7406\u60f3\u5c04\u7a0b\u53d6 TLM \u67aa\u68b0\u4e2d\u8ddd\u79bb\u914d\u7f6e\uff0c\u540c\u6837\u4e58\u300c\u8fdc\u7a0b\u7406\u60f3\u5c04\u7a0b\u500d\u7387\u300d\u3002\u4e3b\u52a8\u5207\u6218\u6597\u4fdd\u62a4\u4f60\u65f6\u4e5f\u662f\u2014\u2014\u6709\u67aa+\u5f39\u836f\u7684\u5973\u4ec6\u4f18\u5148\u5207\u67aa\u68b0\u6a21\u5f0f\uff08\u89c1\u300c\u6218\u6597\u4e0e\u81ea\u4fdd\u300d\u7ae0\uff09\u3002",
                "\u00a7e\u67aa\u68b0\u5f39\u836f\u7bb1\u00a7r\uff1aTACZ \u7684\u00a7e\u5f39\u836f\u7bb1\u00a7r\u540c\u6837\u88ab\u5979\u8ba4\u4f5c\u00a7e\u300c\u6709\u5b50\u5f39\u300d\u00a7r\u2014\u2014\u00a7e\u7a7a\u88ad\u7684\u5f39\u836f\u95e8\u7981\u00a7r\u3001\u00a7e\u81ea\u4e3b\u6218\u6597\u5207\u67aa\u68b0\u00a7r\u3001\u00a7e\u6311\u67aa\u504f\u597d\u00a7r\u4e09\u5904\u90fd\u4e0d\u4f1a\u628a\u7bb1\u88c5\u5f39\u836f\u5f53\u6ca1\u5f39\u836f\uff1b\u771f\u6b63\u6362\u5f39\u65f6\u7531 TACZ \u81ea\u5df1\u00a7e\u5f00\u7bb1\u53d6\u5f39\u00a7r\uff08\u7bb1\u5185\u5f39\u836f\u578b\u53f7\u5fc5\u987b\u5bf9\u5f97\u4e0a\u67aa\u2014\u20149mm \u7684\u7bb1\u5582\u4e0d\u4e86\u6b65\u67aa\uff0c\u00a7e\u521b\u9020\u5f39\u836f\u7bb1\u00a7r\u65e0\u9650\uff09\uff0c\u6563\u88c5\u5f39\u836f\u548c\u7bb1\u5b50\u968f\u4fbf\u6df7\u653e\uff0c\u6362\u5f39\u65f6\u5148\u626b\u5230\u54ea\u4e2a\u5403\u54ea\u4e2a\u3002\u00a7e\u300c\u7a7a\u88ad / \u626b\u5e1a\u6a21\u5f0f\u80fd\u4e0d\u80fd\u6fc0\u6d3b\u300d\u90a3\u9053\u5f39\u836f\u95e8\u6574\u4f53\u4ea4\u7ed9\u67aa\u68b0 mod \u81ea\u5df1\u5224\u00a7r\uff08TACZ \u4e0e\u5353\u8d8a\u524d\u7ebf\u5404\u95ee\u5404\u7684\uff1b\u5f39\u836f\u578b\u53f7\u5fc5\u987b\u5bf9\u5f97\u4e0a\u67aa\u624d\u7b97\u6570\uff09\u2014\u2014\u7bb1\u88c5\u5f39\u836f\u7167\u8ba4\uff0c\u8be6\u89c1\u300c\u98de\u884c\u4e0e\u7a7a\u88ad\u300d\u7ae0\u90a3\u4e00\u8282\u3002",
                "\u00a7e\u53cb\u519b\u98ce\u514d\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5973\u4ec6\u653e\u51fa\u7684\u00a7e\u98ce\u66b4 / \u706b\u7403 / \u98ce\u5f39\u00a7r\u4e0d\u4f1a\u628a\u4f60\u548c\u540c\u4e3b\u5973\u4ec6\u9707\u5f00\u2014\u2014\u00a7e\u4f24\u5bb3\u672c\u6765\u5c31\u5df2\u514d\u75ab\u00a7r\uff08\u4e3b\u4eba/\u53cb\u519b\u514d\u4f24\u603b\u95f8 + \u4e07\u6cd5\u7686\u901a\u81ea\u5df1\u7684\u76df\u53cb\u5224\u5b9a\uff09\uff0c\u8fd9\u4e00\u9879\u62e6\u7684\u662f\u00a7e\u51fb\u9000\u00a7r\uff1a\u539f\u7248\u7206\u70b8\u7684\u51fb\u9000\u548c\u94c1\u9b54\u6cd5\u300c\u547c\u5578\u4e4b\u98ce\u300d\u8fd9\u7c7b\u6548\u679c\u90fd\u662f\u00a7e\u76f4\u63a5\u6539\u901f\u5ea6\u3001\u6839\u672c\u4e0d\u8d70\u4f24\u5bb3\u4e8b\u4ef6\u00a7r\uff0c\u6240\u4ee5\u8840\u4e0d\u6389\u3001\u4eba\u4e5f\u4e0d\u4f1a\u88ab\u9707\u98de\uff0c\u4ece\u9ad8\u7a7a\u6253\u4e0b\u6765\u65f6\u4e3b\u4eba\u4e5f\u4e0d\u4f1a\u88ab\u70b8\u4e0a\u5929\u3002\u53ea\u5bf9\u00a7e\u4e3b\u4eba\u4e0e\u540c\u4e3b\u5973\u4ec6\u00a7r\u751f\u6548\uff0c\u4e14\u53ea\u62e6\u00a7e\u660e\u663e\u7684\u5916\u529b\u4f4d\u79fb\u00a7r\uff08\u8d70\u8def/\u91cd\u529b/\u6324\u5f00\u90fd\u4e0d\u7b97\uff0c\u5973\u4ec6\u81ea\u5df1\u7684\u00a7e\u70df\u82b1\u63a8\u8fdb\u3001\u98ce\u5f39\u81ea\u8d77\u8df3\u00a7r\u4e00\u5b57\u4e0d\u6539\uff09\u3002\u5f00\u5173\u5728\u300c\u6218\u6597\u4e0e\u81ea\u4fdd \u2192 \u5355\u5175\u6218\u672f\u300d\u5c0f\u8282\u7684\u00a7e\u53cb\u519b\u98ce\u514d\u00a7r\u3002",
                "绕圈半径、远程理想射程倍率可调；总开关在「战斗与自保 → 单兵战术」小节。");
    }

    static GuideContent.Chapter weaponEquipGuide() {
        return new GuideContent.Chapter("武器与工具切换机制",
                "女仆干活/战斗前会自动换合适的工具——切换不打断任何行为，每 tick 悄悄检查，换完即停。",
                "\u00a7e一、什么算近战武器？\u00a7r",
                "与 TLM 原版一致：\u00a7e主手装备槽带「攻击伤害」属性的物品\u00a7r就算近战武器"
                        + "（剑/斧/三叉戟/自定义武器都算）；明确排除镐、弓、弩、御币（弹幕）、锄头（农具）。",
                "\u00a7e二、什么时候切换？\u00a7r",
                "按任务词条匹配：主手物品符合当前任务类型（攻击=近战武器、弓=弓…）且没快坏 → \u00a7e不换\u00a7r"
                        + "（你亲手安排的战术配置优先，女仆绝不动）；不符合 → 从背包装备评分最高的一把。",
                "\u00a7e三、评分公式\u00a7r：DPS（最终伤害 × 攻速）> 附魔词条数 > 剩余耐久。"
                        + "弓/弩没有攻击力属性算不出 DPS → 按附魔/耐久择优。",
                "\u00a7e四、镐（挖矿）\u00a7r：发现目标矿才判定——手中镐能挖且未快坏 → 不换；"
                        + "挖不动 → 从背包装「能挖目标」的镐（能挖的里面等级最低的最贴近，不浪费高级镐）；空手 → 装最高的。",
                "\u00a7e五、盾牌\u00a7r：战斗任务下副手空手 → 自动装盾；盾爆了自动补；副手已有任何非盾物品则绝不动。",
                "\u00a7e六、黑名单保护\u00a7r：只剩「剩余耐久 ≤ 10%」会被拉黑（背包里的备用物品不换到手上）；"
                        + "主手正在用的武器快坏会主动提前换下一把。",
                "\u00a7e七、其他模组的武器\u00a7r：判定全部基于原版属性系统，没有任何武器黑名单——"
                        + "Better Combat 等模组武器只要带攻击伤害属性就会被正常使用和切换。",
                "\u00a7e\u516b\u3001\u67aa\u68b0\u00a7r\uff1a\u88c5\u4e86 TACZ/\u5353\u8d8a\u524d\u7ebf\u65f6\uff0c\u5207\u300c\u67aa\u68b0\u300d\u4efb\u52a1\u7684\u5973\u4ec6\u4f1a\u4ece\u80cc\u5305\u88c5\u00a7e\u8bc4\u5206\u6700\u9ad8\u7684\u67aa\u00a7r\uff08\u80cc\u5305\u91cc\u00a7e\u6709\u5339\u914d\u5f39\u836f\u00a7r\u7684\u67aa\u4f18\u5148\u7ea7\u538b\u5012\u4e00\u5207\uff09\uff1b\u5f00\u67aa\u3001\u641c\u5f39\u836f\u3001\u6362\u5f39\u7531 TLM \u5185\u7f6e\u67aa\u68b0\u4efb\u52a1\u8d1f\u8d23\uff0c\u672c\u6a21\u7ec4\u53ea\u7ba1\u6311\u67aa\u548c\u8d70\u4f4d\u6218\u672f\uff08\u8be6\u89c1\u300c\u5355\u5175\u6218\u672f\u300d\u7ae0\u7684\u67aa\u68b0\u6bb5\uff09\u3002\u4f10\u6728\u4efb\u52a1\u4e5f\u6709\u540c\u6b3e\u00a7e\u81ea\u52a8\u6362\u65a7\u00a7r\u903b\u8f91\uff08\u80fd\u780d\u76ee\u6807\u6811\u7684\u65a7\u5b50\u91cc\u6311\u6700\u5408\u9002\u7684\uff09\u3002",
                "\u00a7e\u4e5d\u3001\u526a\u5200\u00a7r\uff1a\u5207\u300c\u526a\u5200\u300d\u4efb\u52a1\u65f6\u81ea\u52a8\u4ece\u80cc\u5305\u91cc\u62ff\u51fa\u526a\u5200\uff08\u539f\u7248\u526a\u5200\u548c\u00a7e\u4efb\u610f\u5e26 forge:shears \u6807\u7b7e\u7684\u6a21\u7ec4\u526a\u5200\u00a7r\u90fd\u8ba4\uff0c\u548c\u6316\u77ff\u6362\u9550\u540c\u6b3e\u903b\u8f91\uff09\uff1b\u4e3b\u624b\u5df2\u6709\u526a\u5200\u4e14\u6ca1\u5feb\u574f\u5c31\u4e0d\u52a8\u3002",
                "\u00a7e十、法术模式（车万女仆：万法皆通）\u00a7r：附属的\u00a7e近战法术 / 远程法术\u00a7r任务" 
                        + "附属模组对「法术模式的武器」收得很宽（几乎什么都算），所以这里单独收紧成两条："
                        + "\u00a7e① 她得真的带着法术装备\u00a7r（法术书/法器在主手、副手、背包或饰品栏，"
                        + "或者附属数据里已经有她的法术书）才允许换武器——没带就\u00a7e一次都不换\u00a7r，"
                        + "不会把背包里的剑/斧塞进法术模式；\u00a7e② 换也只换法术装备\u00a7r（附属认的法术书/法器，"
                        + "按附魔\u003e耐久择优）。没装这个附属时本节无效，一切照旧。",
                "\u00a7e【举例】\u00a7r：你给女仆主手放一把钻石剑、背包放一把附魔铁剑——攻击任务下她不换"
                        + "（你安排的优先）；你拿走钻石剑后她会自动换上背包里评分最高的那把。",
                "\u00a7e\u5341\u4e00\u3001\u6ca1\u6709\u6cd5\u672f\u4e66\u4e5f\u80fd\u770b\u5230\u300c\u8fd1\u6218\u6cd5\u672f / \u8fdc\u7a0b\u6cd5\u672f\u300d\u9009\u9879\uff1f\u00a7r\u90a3\u4e24\u4e2a\u4efb\u52a1\u662f\u300a\u8f66\u4e07\u5973\u4ec6\uff1a\u4e07\u6cd5\u7686\u901a\u300b\u6ce8\u518c\u7684\uff0c\u800c\u00a7e\u5b83\u4eec\u7684 isEnable \u6052\u8fd4\u56de true\u00a7r\uff08javap \u53cd\u7f16\u8bd1\uff1a\u65b9\u6cd5\u4f53\u53ea\u6709 iconst_1; ireturn\uff09\uff0cTLM \u7684\u5973\u4ec6\u754c\u9762\u5217\u4efb\u52a1\u65f6\u53ea\u6309\u00a7eisHidden\u00a7r \u8fc7\u6ee4\u3001\u4e0d\u770b\u80cc\u5305\u2014\u2014\u6240\u4ee5\u00a7e\u88c5\u4e86\u90a3\u4e2a\u9644\u5c5e\u5c31\u4f1a\u4e00\u76f4\u663e\u793a\u8fd9\u4e24\u9879\u00a7r\uff0c\u4e0e\u80cc\u5305\u91cc\u6709\u6ca1\u6709\u6cd5\u672f\u4e66\u65e0\u5173\uff0c\u4e5f\u548c\u672c\u6a21\u7ec4\u65e0\u5173\uff08\u672c\u6a21\u7ec4\u00a7e\u4ece\u4e0d\u62e6\u4f60\u624b\u52a8\u5207\u6362\u4efb\u52a1\u00a7r\uff09\u3002\u672c\u6a21\u7ec4\u7ba1\u7684\u662f\u53e6\u4e00\u4ef6\u4e8b\uff1a\u00a7e\u81ea\u4e3b\u53c2\u6218\u8981\u4e0d\u8981\u81ea\u52a8\u628a\u5979\u5207\u8fc7\u53bb\u00a7r\u3002",
                "\u00a7e\u5341\u4e8c\u3001\u4ec0\u4e48\u53eb\u300c\u5979\u771f\u7684\u4f1a\u7528\u6cd5\u672f\u300d\u00a7r\uff1a\u4e0a\u9762\u7b2c\u5341\u8282\u90a3\u6761\u5224\u5b9a\u7684\u53e3\u5f84\u2014\u2014\u9644\u5c5e\u628a\u300c\u6cd5\u672f\u88c5\u5907\u300d\u7684\u5b9a\u4e49\u4ea4\u7ed9\u5404\u524d\u7f6e\u9644\u5c5e\u81ea\u5df1\u7684 provider\uff1a\u94c1\u9b54\u6cd5\u8ba4\u6cd5\u672f\u4e66/\u5377\u8f74\u3001\u65b0\u751f\u9b54\u827a\u8ba4\u65bd\u6cd5\u6cd5\u5668\u3001\u5deb\u672f\u8ba4\u9b54\u6756/\u6cd5\u672f\u4e66\u2026\u2026\u00a7e\u5176\u4e2d\u4e24\u4e2a provider \u8ba4\u7684\u300c\u6cd5\u672f\u88c5\u5907\u300d\u672c\u8eab\u5c31\u662f\u6b66\u5668\u00a7r\uff1a\u00a7eslashblade \u8ba4\u62d4\u5200\u5251\u00a7r\u3001\u00a7eyoukaishomecoming \u8ba4\u5f39\u5e55/\u6fc0\u5149/\u7b26\u5361\u00a7r\uff0c\u800c\u5b83\u4eec\u5728 TLM \u4fa7\u5404\u81ea\u5df2\u6709\u4e13\u5c5e\u6218\u6597\u6a21\u5f0f\u3002\u00a7e\u300c\u6218\u6597\u4e0e\u81ea\u4fdd \u2192 \u4e3b\u52a8\u53c2\u6218 \u2192 \u6cd5\u672f\u88c5\u5907\u5ffd\u7565\u8868\u300d\u00a7r\uff08\u914d\u7f6e combat.spellGearIgnore\uff0c\u9ed8\u8ba4 slashblade, youkaishomecoming\uff09\u7528\u6765\u6392\u9664\u8fd9\u7c7b provider\u2014\u2014\u5217\u8fdb\u53bb\u7684 provider \u4e0d\u7b97\u300c\u5979\u4f1a\u7528\u6cd5\u672f\u300d\uff0c\u7559\u7a7a = \u5168\u90e8\u6309 provider \u5224\u5b9a\u3002\u00a7e\u6392\u67e5\u00a7r\uff1alatest.log \u641c\u00a7ecombat pools\u00a7r\uff0c\u6c60\u91cc\u6709\u6cd5\u672f\u4efb\u52a1\u65f6\u4f1a\u9644\u4e00\u884c spellGear=\uff0c\u76f4\u63a5\u70b9\u540d\u662f\u54ea\u4ef6\u4e1c\u897f\u653e\u884c\u7684\u3002");
    }

    /**
     * v1.3.0(beta) 实测六百七十五【武装拴绳】——粉丝点单的"直升机二号位"。
     *
     * <p>为什么补这一章：
     *
     * 一次都没提过——现在它有自己的一章（本章）+ 自己的配置板块（「移动与行为 → 武装拴绳（二号位）」）。
     */
    static GuideContent.Chapter tetherGuide() {
        return new GuideContent.Chapter("武装拴绳（二号位 · 挂在飞行女仆身下开火）",
                "粉丝点单的\u00a7e武装直升机\u00a7r玩法：女仆当一号位（她飞、她开火），你当二号位（挂在她身下开火）。"
                        + "道具是\u00a7e【武装拴绳】\u00a7r[[i:maid_smart:combat_leash|武装拴绳]]，用法和原版拴绳一样——"
                        + "\u00a7e拿着它右击女仆\u00a7r。",
                // 实测八百一十三：合成表整块画（无固定形状：拴绳 + 铁锭×2）
                "\u00a7e合成\u00a7r（工作台，无序）："
                        + "[[#shapeless;minecraft:lead;minecraft:iron_ingot;minecraft:iron_ingot;>maid_smart:combat_leash;@拴绳×1 + 铁锭×2]]",
                "\u00a7e一、怎么绑\u00a7r",
                "\u00a7e\u2460 \u626b\u5e1a\u6a21\u5f0f\u00a7r\uff1a\u5979\u00a7e\u5df2\u7ecf\u9a91\u5728\u626b\u5e1a\u4e0a\u00a7r\u65f6\u53f3\u51fb\u5979\uff08\u6216\u8005\u4f60\u5750\u5728\u626b\u5e1a\u9a7e\u9a76\u4f4d\u4e0a\u53f3\u51fb\u5979\uff09\u2192 \u4f60\u4ece\u626b\u5e1a\u4e0a\u4e0b\u6765\u3001\u6302\u5230\u5979\u7684\u4e8c\u53f7\u4f4d\u3002\u6ce8\u610f\u00a7e\u5730\u9762\u6302\u7740\u4f1a\u628a\u4eba\u62d6\u8fdb\u5730\u91cc\u00a7r\uff0c\u6240\u4ee5\u8fd9\u4e00\u6863\u8981\u6c42\u5979\u5148\u98de\u8d77\u6765\u3002\n\u00a7e\u2461 \u7a7a\u88ad\u6a21\u5f0f\u00a7r\uff08\u8fd1\u6218\u7a7a\u88ad / \u8fdc\u7a0b\u7a7a\u88ad\uff09\uff1a\u00a7e\u968f\u65f6\u80fd\u7ed1\u00a7r\u3002\u5979\u8fd8\u6ca1\u8d77\u98de\u65f6\u5148\u8fdb\u5165\u00a7e\u7275\u7ef3\u6863\u00a7r\u2014\u2014\u4f60\u81ea\u7531\u6d3b\u52a8\u3001\u5979\u8ddf\u7740\u4f60\u8d70\uff08\u5c31\u50cf\u539f\u7248\u62f4\u7ef3\u7275\u7740\u8d70\uff0c\u7ef3\u5b50\u7167\u753b\uff09\uff1b\u7b49\u5979\u00a7e\u771f\u7684\u8d77\u98de\u00a7r\uff08\u6ed1\u7fd4 / \u51fa\u7a7a\u88ad\u624b\uff09\u624d\u628a\u4f60\u6302\u5230\u4e8c\u53f7\u4f4d\uff0c\u5979\u843d\u5730\u6ee1 2 \u79d2\u518d\u628a\u4f60\u653e\u4e0b\u3001\u56de\u5230\u7275\u7ef3\u3002\n\u00a7e\u2462 \u53ea\u8ba4\u4e3b\u4eba\u00a7r\uff1b\u4e00\u53ea\u5973\u4ec6\u540c\u65f6\u53ea\u6302\u4e00\u4eba\uff1b\u00a7e\u4f60\u540c\u65f6\u53ea\u80fd\u7275\u4e00\u53ea\u00a7r\u2014\u2014\u7ed1\u7b2c\u4e8c\u53ea\u65f6\u4f1a\u81ea\u52a8\u628a\u7b2c\u4e00\u53ea\u5b8c\u6574\u677e\u5f00\uff08\u89e3\u9664\u6302\u8f7d\u3001\u53bb\u6389\u91d1\u8272\u63cf\u8fb9\u3001\u4f60\u4e0d\u518d\u540a\u5728\u5979\u4e0b\u9762\uff0c\u65e5\u5fd7\u91cc\u5199\u4e00\u884c\u300c\u6362\u7ed1\u300d\uff09\u3002",
                "\u00a7e二、怎么解\u00a7r",
                "\u518d\u53f3\u51fb\u4e00\u6b21\uff0c\u6216\u8005\u6309\u00a7e\u6f5c\u8df3\u00a7r\u4e0b\u978d\u3002\u00a7e\u7ed1\u5b9a\u6001\u53f3\u51fb\u5979\u00a7r = \u89e3\u9664\u5e76\u00a7e\u5750\u56de\u626b\u5e1a\u9a7e\u9a76\u4f4d\u00a7r\uff08\u5979\u5750\u7b2c\u4e8c\u4e58\u5ba2\uff09\uff1b\u00a7e\u5728\u626b\u5e1a\u9a7e\u9a76\u4f4d\u4e0a\u53f3\u51fb\u5979\u00a7r = \u00a7e\u6362\u5230\u4e8c\u53f7\u4f4d\u00a7r\u2014\u2014\u8fd9\u4e24\u534a\u662f\u4e92\u9006\u7684\uff0c\u6765\u56de\u5207\u5c31\u662f\"\u6211\u5f00 / \u5979\u5f00\"\u4e24\u79cd\u5750\u6cd5\u3002\n\u00a7e\u2463 \u6362\u5ea7\u65f6\u5979\u4e0d\u4f1a\u6389\u4e0b\u53bb\u00a7r\uff1a\u6362\u5ea7\u8d70\u7684\u662f\u00a7e\u539f\u7248\u81ea\u5df1\u7684\"\u73a9\u5bb6\u63d2\u961f\"\u89c4\u5219\u00a7r\u2014\u2014\u73a9\u5bb6\u4e0a\u978d\u81ea\u52a8\u5750\u8fdb\u7b2c\u4e00\u4e58\u5ba2\uff08\u9a7e\u9a76\u4f4d\uff09\uff0c\u5979\u00a7e\u5168\u7a0b\u4e0d\u4f1a\u4e0b\u978d\u00a7r\uff0c\u9a91\u4e58\u5173\u7cfb\u4e00\u4e2a\u5b57\u8282\u90fd\u4e0d\u52a8\u3002\n\u00a7e\u7ef3\u5b50\u4e0d\u4f1a\u81ea\u5df1\u65ad\u00a7r\uff1a\u843d\u5730\u4e0d\u4f1a\u81ea\u52a8\u653e\u4eba\uff1b\u53ea\u6709\u00a7e\u843d\u6c34\u8d85\u8fc7 0.6 \u79d2\u00a7r\u4f1a\u628a\u4f60\u653e\u4e0b\u6765\uff08\u514d\u5f97\u8ddf\u7740\u5979\u4e00\u8d77\u6eba\u6c34\uff09\u3002\u89e3\u9664\u77ac\u95f4\u4eba\u5728\u7a7a\u4e2d\uff0c\u7ed9\u00a7e 5 \u79d2\u6454\u4f24\u8c41\u514d\u00a7r\uff1b\u6302\u7740\u7684\u65f6\u5019\u4f60\u548c\u5973\u4ec6\u00a7e\u540c\u6b3e\u514d\u4f24\u00a7r\uff1a\u5361\u5899 / \u6324\u5899 / \u6454\u843d / \u649e\u5899\u3002",
                "\u00a7e三、挂在下面看得见吗（画面上的三件事）\u00a7r",
                "\u00a7e\u2460 \u534a\u900f\u660e\u00a7r\uff1a\u6302\u5728\u5979\u8eab\u4e0b\u65f6\u5979\u7684\u6a21\u578b\u4f1a\u6321\u89c6\u91ce \u2192 \u53ea\u5bf9\u00a7e\u4f60 + \u7b2c\u4e00\u4eba\u79f0\u00a7r\u628a\u5979\uff08\u4ee5\u53ca\u4f60\u9a91\u7684\u90a3\u628a\u626b\u5e1a\uff09\u753b\u6210\u534a\u900f\u660e\uff0c\u9ed8\u8ba4\u900f\u660e\u5ea6 0.1\u3001\u53ef\u8c03\u3001\u586b 1.0 \u5c31\u662f\u5173\u6389\u3002\u00a7e\u7b2c\u4e09\u4eba\u79f0\u3001\u522b\u7684\u73a9\u5bb6\u00a7r\u770b\u5230\u7684\u4e00\u5207\u7167\u65e7\u4e0d\u900f\u660e\u2014\u2014\u8054\u673a / \u5f55\u50cf\u4e0d\u53d7\u5f71\u54cd\u3002\n\n\u00a7e\u2461 \u91d1\u8272\u63cf\u8fb9\u00a7r\uff1a\u88ab\u7ef3\u5b50\u9009\u4e2d\u3001\u00a7e\u8fd8\u6ca1\u6b63\u5f0f\u8d77\u98de\u00a7r\u7684\u5979\u8eab\u4e0a\u6709\u4e00\u5c42\u91d1\u8272\u63cf\u8fb9\uff08\u5c31\u662f\u5149\u7075\u7bad\u5c04\u4e2d\u654c\u4eba\u90a3\u79cd\u53d1\u5149\u63cf\u8fb9\uff0c\u989c\u8272\u6539\u6210\u91d1\u8272\u3001\u7a7f\u5899\u53ef\u89c1\uff09\uff0c\u5979\u00a7e\u6b63\u5f0f\u8d77\u98de\u90a3\u4e00\u523b\u89e3\u9664\u00a7r\u2014\u2014\u7b49\u4e8e\u300c\u5df2\u9501\u5b9a\u3001\u51c6\u5907\u8d77\u540a\u300d\u7684\u63d0\u793a\u3002\u00a7e\u6536\u8fdb\u9b42\u7b26\u518d\u653e\u51fa\u6765\u7684\u6b8b\u7559\u6807\u8bb0\u4f1a\u81ea\u52a8\u6e05\u6389\u00a7r\u3002\n\n\u00a7e\u2462 \u7ef3\u5b50\u00a7r\uff1a\u7528\u7684\u662f\n\u00a7e\u539f\u7248\u62f4\u7ef3\u540c\u6b3e\u00a7r\u7684\u4e1d\u5e26\u51e0\u4f55\uff0824 \u6bb5\u4e09\u89d2\u5e26 + \u7f16\u7ec7\u660e\u6697 + \u4e24\u7aef\u5149\u7167\u63d2\u503c\uff09\uff0c\u914d\u8272\u6539\u6210\u00a7e\u767d\u00a7r\u3002\u7ef3\u5b50\u00a7e\u9694\u8fdc\u4e0d\u4f1a\u6d88\u5931\u00a7r\uff1b\u4e24\u7aef\u00a7e\u6309\u5e27\u63d2\u503c\u00a7r\u3001\u8ddf\u7740\u5979\u7684\u6a21\u578b\u4e00\u8d77\u52a8\uff0c\u4e0d\u518d\u4e00\u683c\u683c\u5730\u62bd\uff1b\u00a7e\u4f60\u6b63\u597d\u540a\u5728\u5979\u6b63\u4e0b\u65b9\u65f6\u00a7r\u6539\u7528\u00a7e\u4e09\u7247\u56f4\u7740\u7ef3\u8f74\u8f6c\u4e00\u5708\u7684\u5e26\u5b50\u00a7r\uff0c\u4efb\u4f55\u89d2\u5ea6\u90fd\u770b\u5f97\u89c1\u3002\u5f2f\u66f2\u53ea\u5728\u00a7e\u7ef3\u5b50\u677e\u4e0b\u6765\u00a7r\u7684\u65f6\u5019\u51fa\u73b0\uff08\u4e24\u7aef\u8ddd\u79bb\u77ed\u4e8e\u7ef3\u957f\uff09\uff0c\u00a7e\u7ef7\u7d27\u65f6\u662f\u76f4\u7ebf\u00a7r\uff1b\u62d6\u66f3\u7684\u6765\u6e90\u53d6\u00a7e\u5979\u76f8\u5bf9\u4f60\u7684\u901f\u5ea6\u00a7r\uff08\u4f60\u4fe9\u4e00\u8d77\u98de\u7684\u65f6\u5019\u7ef3\u5b50\u4e0d\u5f2f\uff09\u3002\n\n\u00a7e\u2463 \u5de6\u4e0a\u89d2\u7684\u84dd\u8272\u300c\u7ed1\u5b9a\u4e2d\u300d\u00a7r\uff1a\u62f4\u7740\u7684\u65f6\u5019\uff0c\u4f60\u5c4f\u5e55\u5de6\u4e0a\u89d2\u591a\u4e00\u884c\u84dd\u8272\u7684\u00a7e\u300c\u25c6 \u7ed1\u5b9a\u4e2d <\u5979\u7684\u540d\u5b57> \u7275\u7ef3 / \u4e8c\u53f7\u4f4d\u300d\u00a7r\u2014\u2014\u00a7e\u7275\u7ef3\u00a7r\u8868\u793a\u4f60\u81ea\u7531\u6d3b\u52a8\u3001\u5979\u8ddf\u7740\u4f60\u8d70\uff0c\u00a7e\u4e8c\u53f7\u4f4d\u00a7r\u8868\u793a\u4f60\u6b63\u540a\u5728\u5979\u4e0b\u9762\u3002\u4f4d\u7f6e\u548c\u51b7\u5374\u8ba1\u65f6\u90a3\u4e00\u6bb5\u662f\u00a7e\u540c\u4e00\u6761\u7ad6\u76f4\u4e32\u00a7r\uff08\u5c31\u753b\u5728\u5b83\u4e0b\u9762\uff09\uff0c\u6240\u4ee5\u300c\u6253\u5f00\u754c\u9762 / F3 \u65f6\u6574\u5757\u9690\u85cf\u300d\u300c\u51e0\u79d2\u6ca1\u6570\u636e\u81ea\u52a8\u6e05\u7a7a\u300d\u7684\u884c\u4e3a\u5b8c\u5168\u4e00\u81f4\uff1b\u89e3\u7ed1\uff08\u6216\u5979\u6ca1\u4e86\uff09\u90a3\u4e00\u884c\u81ea\u5df1\u5c31\u6d88\u5931\u3002\u00a7e\u5173\u6389\u51b7\u5374\u8ba1\u65f6\u4e0d\u5f71\u54cd\u5b83\u00a7r\u2014\u2014\u90a3\u662f\u4e24\u4ef6\u4e8b\u3002",
                "\u00a7e四、数值：吊多深、谁开火\u00a7r",
                "\u00a7e\u60ac\u6302\u8ddd\u79bb\u00a7r\uff1a\u73a9\u5bb6\u811a\u5e95\u5230\u5979\u811a\u5e95\u7684\u5782\u76f4"
                + "\u8ddd\u79bb\uff0c\u4e5f\u5c31\u662f\u7ef3\u957f\uff08\u9ed8\u8ba4 2.6 \u683c\uff0c\u53ef\u8c03 0.5~6.0\uff09"
                + "\u3002\u5979\u00a7e\u7ad9\u5728\u5730\u4e0a / \u8d34\u7740\u5730\u5f62\u00a7r\u65f6\u6539\u6210\u00a7e\u6c34"
                + "\u5e73\u62c9\u5f00\u00a7r\u8fd9\u4e48\u8fdc\u5e76\u80a9\u7ad9\u7740\uff08\u4e0d\u518d\u548c\u5979\u7684\u5efa"
                + "\u6a21\u91cd\u53e0\uff09\uff1b\u5b9a\u4f4d\u662f\u00a7e\u5e73\u6ed1\u6ed1\u53d8\u00a7r\u7684\uff0c\u5730\u5f62"
                + "\u8d77\u4f0f\u4e5f\u4e0d\u4f1a\u4e0a\u4e0b\u6a2a\u8df3\u3002\n\u00a7e\u626b\u5e1a\u989d\u5916\u4e0b\u6c89\u00a7r"
                + "\uff1a\u626b\u5e1a\u6a21\u5f0f\u4e0b\u5979\u9a91\u5728\u626b\u5e1a\u4e0a\uff0c\u626b\u5e1a\u6a21\u578b\u6bd4"
                + "\u5979\u7684\u811a\u5e95\u8fd8\u4f4e \u2192 \u518d\u5f80\u4e0b\u8ba9 0.3 \u683c\uff08\u9ed8\u8ba4 0.3\uff0c"
                + "\u53ef\u8c03 0~2.0\uff09\uff0c\u514d\u5f97\u4f60\u7684\u4eba\u548c\u626b\u5e1a\u53e0\u5728\u4e00\u8d77\u3002",
                "\u00a7e\u62c9\u626f\u00a7r\uff1a\u7ef3\u5b50\u7ef7\u7d27\u65f6\u00a7e\u771f\u7684\u62c9\u5979\u00a7r\uff0c\u5206"
                + "\u6863\u7167\u642c\u539f\u7248\u62f4\u7ef3\uff08NeoForge \u7248 Leashable.tickLeash / Forge \u7248 PathfinderMob"
                + ".customServerAiStep\uff09\uff1a\u00a7e\u8d85\u8fc7 6 \u683c\u00a7r \u7167\u6284\u539f\u7248\u90a3\u4e00\u8bb0 "
                + "\u00a70.4 \u00d7 \u65b9\u5411\u00b2\u00a7r \u7684\u51b2\u91cf\uff08\u5f80\u4f60\u8fd9\u8fb9\u62fd\uff09\uff1b"
                + "\u00a7e2~6 \u683c\u00a7r \u8865\u4e00\u4e2a\"\u671d\u4f60\u63a5\u8fd1\u7684\u901f\u5ea6\u4e0a\u9650\"\uff08= "
                + "\u8d70\u5230\u79bb\u4f60 2 \u683c\u4e3a\u6b62\uff0c\u4e0e\u73a9\u5bb6\u7684\u884c\u8d70\u901f\u5ea6\u540c\u6863"
                + "\uff09\u2014\u2014\u8fd9\u4e00\u6863\u53ea\u8865\u901f\u5ea6\u3001\u4e0d\u78b0\u5bfc\u822a\uff08\u5973\u4ec6"
                + "\u4e00\u591a\uff0c\u6bcf tick \u4e00\u6b21\u5bfb\u8def\u5c31\u662f\u670d\u52a1\u5668\u707e\u96be\uff09\u3002"
                + "\u00a7e\u539f\u7248\u8d85\u8fc7 10 \u683c\u4f1a\u6492\u624b\u6389\u62f4\u7ef3\uff0c\u672c\u6a21\u7ec4\u7684"
                + "\u7ef3\u5b50\u4e0d\u4f1a\u65ad\u00a7r\uff0c\u7167\u65e7\u62c9\uff1b\u518d\u8fdc\u7531\u5979\u81ea\u5df1\u7684"
                + "\u7275\u5f15\u7ef3\u8fde\u4eba\u5e26\u626b\u5e1a\u4f20\u56de\u6765\u3002\u53ea\u5728\u00a7e\u7275\u7ef3\u6863"
                + "\u00a7r\uff08\u5979\u8fd8\u6ca1\u8d77\u98de\u3001\u4f60\u7275\u7740\u5979\u5728\u8d70\uff09\u4f7f\u52b2\u2014"
                + "\u2014\u60ac\u6302\u6863\u4f60\u540a\u5728\u5979\u8eab\u4e0b\u3001\u7531\u9a91\u4e58\u5b9a\u4f4d\u521a\u6027"
                + "\u63a7\u5236\uff0c\u7ef3\u5b50\u4e0d\u53d7\u529b\u3002\u5f00\u5173\uff1a\u00a7e\u6b66\u88c5\u62f4\u7ef3\u00b7"
                + "\u62c9\u626f\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\u3002",
                "\u00a7e\u4e8c\u53f7\u4f4d\u5f00\u706b\u00a7r\uff1a\u6302\u7740\u65f6\u7167\u5e38\u5c04\u51fb\uff08\u5f13 / "
                + "\u5f29 / \u67aa\u68b0\u90fd\u884c\uff09\u2014\u2014\u5979\u6253\u5979\u7684\u76ee\u6807\u3001\u4f60\u6253\u4f60"
                + "\u7784\u7684\uff0c\u5404\u81ea\u72ec\u7acb\uff0c\u4e92\u4e0d\u5e72\u6270\u3002",
                "\u00a7e\u4e8c\u53f7\u4f4d\u91cd\u9524\u731b\u51fb\u00a7r\uff08\u00a7e\u672c\u6811\u4e13\u5c5e\u00a7r\uff1b\u91cd"
                + "\u9524\u662f NeoForge \u7248\u624d\u6709\u7684\u4e1c\u897f\uff09\uff1a\u540a\u5728\u5979\u4e0b\u65b9\u65f6\uff0c"
                + "\u4f60\u624b\u91cc\u90a3\u628a\u91cd\u9524\u00a7e\u4e5f\u80fd\u5403\u5230\u4e0b\u843d\u52a0\u6210\u00a7r\u2014"
                + "\u2014\u6309\u00a7e\u4f60\u8ddf\u7740\u5979\u8fd9\u4e00\u6bb5\u4fef\u51b2\u4e0b\u964d\u4e86\u591a\u5c11\u683c"
                + "\u00a7r \u7b97\uff0c\u4e0b\u843d\u8d8a\u591a\u7838\u5f97\u8d8a\u91cd\uff08\u539f\u7248\u7684\u731b\u51fb\u97f3"
                + "\u6548\u3001\u5468\u56f4\u51fb\u9000\u3001\u589e\u4f24\u4e00\u8d77\u751f\u6548\uff09\u3002\u91cd\u9524\u53ea"
                + "\u8bfb fallDistance \u4e00\u4e2a\u5b57\u6bb5\uff0c\u800c\u5b83\u53ea\u5728\u00a7e\u5b9e\u4f53\u81ea\u5df1\u8d70"
                + "\u52a8\u00a7r\u65f6\u624d\u7d2f\u52a0\u2014\u2014\u00a7e\u4e58\u5ba2\u4e0d\u8d70\u90a3\u4e00\u6b65\u00a7r\uff0c"
                + "\u6240\u4ee5\u540a\u5728\u5979\u4e0b\u9762\u7684\u4f60\u90a3\u4e2a\u6570\u5b57\u6052\u4e3a 0\uff0c\u4e00\u9524"
                + "\u90fd\u7838\u4e0d\u51fa\u731b\u51fb\uff1b\u73b0\u5728\u00a7e\u5979\u5e26\u7740\u4f60\u4fef\u51b2\u65f6\u8fd9"
                + "\u4e00\u9524\u4e5f\u6309\u4e0b\u843d\u7b97\u00a7r\uff08\u91cd\u9524\u53ea\u6b64\u4e00\u6863\u4f8b\u5916\uff09"
                + "\u3002\u00a7e\u53e3\u5f84\u00a7r\uff1a\u4e00\u6b21\u4e0b\u843d\u53ea\u6362\u4e00\u9524\uff08\u7838\u51fa\u53bb"
                + "\u5c31\u6e05\u96f6\uff0c\u540c\u539f\u7248\uff09\uff1b\u00a7e\u60ac\u505c / \u6162\u6162\u98d8\u7740\u4e0d\u7b97"
                + "\u00a7r\uff08\u5355\u6b21 2 tick \u91c7\u6837\u4e0b\u964d\u4e0d\u8db3 0.2 \u683c\uff08= 0.1 \u683c/tick\uff09"
                + "\u5c31\u628a\u7d2f\u8ba1\u94b3\u56de 1.0\uff0c\u514d\u5f97\u60ac\u505c\u65f6\u7684\u6f02\u79fb\u4e5f\u6512\u51fa"
                + "\u8d85\u91cd\u51fb\uff09\uff0c\u6240\u4ee5\u60f3\u7838\u91cd\u9524\u5c31\u5f97\u771f\u8ddf\u7740\u5979\u4e0b"
                + "\u843d\u4e00\u6b21\uff1b\u00a7e\u5979\u843d\u5730 = \u6e05\u96f6\u00a7r\u3002\u00a7e\u53ea\u5bf9\u7a7a\u88ad"
                + "\u90a3\u4e00\u6863\u751f\u6548\u00a7r\uff1a\u8fd1\u6218\u7a7a\u88ad\u9a6e\u7740\u4f60\u4fef\u51b2\u65f6\u8fd9"
                + "\u4e00\u9524\u6309\u4e0b\u843d\u7b97\uff0c\u800c\u00a7e\u626b\u5e1a\u6863\u5b8c\u5168\u6062\u590d\u539f\u7248"
                + "\u00a7r\uff08\u626b\u5e1a\u662f\u8fd0\u8f93\u3001\u4e0d\u662f\u4fef\u51b2\uff0c\u6302\u7740\u626b\u5e1a\u5e73"
                + "\u98de\u6162\u6162\u964d\u4e24\u4e09\u683c\u4e0d\u8be5\u6362\u6765\u4e00\u8bb0\u731b\u51fb\uff09\uff1b\u626b"
                + "\u5e1a\u6863\u7684\u65e5\u5fd7\u91cc\u4e5f\u4e0d\u4f1a\u51fa\u73b0\u300c\u73a9\u5bb6=\u300d\u90a3\u4e00\u884c"
                + "\u3002\u00a7e\u60f3\u77e5\u9053\u5403\u6ca1\u5403\u5230\u00a7r\uff1a\u65e5\u5fd7\u641c\u00a7e\u91cd\u9524\u95e8"
                + "\u00a7r\u2014\u2014\u00a7e\u73a9\u5bb6=\u00a7r\u90a3\u4e00\u884c\u5c31\u662f\u4f60\u8fd9\u628a\u91cd\u9524\u7684"
                + "\u5224\u5b9a\u7ed3\u679c\uff08\u00a7e\u5199\u56de fallDistance = \u8fd9\u4e00\u9524\u6309\u731b\u51fb\u7b97"
                + "\u00a7r / \u00a7e\u4e0d\u5230\u95e8\u69db\u00a7r\uff0c\u4e0b\u843d\u7c7b\u9644\u9b54\u00a7e\u5bc6\u5ea6 / \u7834"
                + "\u7532 / \u98ce\u7206\u00a7r\u90fd\u8ddf\u7740\u8fd9\u4e2a\u6570\u8d70\uff09\u3002\u5f00\u5173\uff1a\u914d\u7f6e"
                + "\u9762\u677f\u300c\u6b66\u88c5\u62f4\u7ef3\u00b7\u4e8c\u53f7\u4f4d\u91cd\u9524\u731b\u51fb\u300d\uff08\u9ed8"
                + "\u8ba4\u5f00\uff09\u3002",
                "\u00a7e五、排查\u00a7r",
                "latest.log \u641c\u00a7e\u6b66\u88c5\u62f4\u7ef3\u00a7r\uff1a\u6302\u8f7d / \u7275\u7ef3 / \u8d77\u98de\u6302\u8f7d / \u843d\u5730\u653e\u4eba / \u89e3\u9664(\u539f\u56e0) / \u6362\u7ed1 / \u5165\u4e16\u754c\u6e05\u7406 \u90fd\u4f1a\u5199\u4e00\u884c\uff0c\u5e26\u5973\u4ec6\u540d\u4e0e\u73a9\u5bb6\u540d\uff1b\u88ab\u62d2\u7edd\u65f6\u4e5f\u4f1a\u5199\u660e\u00a7e\u5361\u5728\u54ea\u4e00\u9053\u95e8\u00a7r\uff08\"\u7b49\u6211\u98de\u8d77\u6765\u518d\u53f3\u51fb\u6211\" / \"\u8fd9\u4e0d\u662f\u6211\u7684\u4e3b\u4eba\" / \"\u5df2\u7ecf\u6709\u4eba\u6302\u5728\u6211\u8eab\u4e0a\u4e86\" \u7b49\uff09\u3002\u00a7e\u60ac\u6302\u6863\u7684\u53f3\u51fb\u00a7r\u53e6\u6709\u4e00\u884c\"\u53f3\u51fb\uff08\u60ac\u6302\u6863\uff0c\u5c04\u7ebf\u6ca1\u6253\u5230\u5979\uff09\"\u2014\u2014\u540a\u5728\u5979\u4e0b\u9762\u65f6\u5979\u5c31\u5728\u4f60\u5934\u9876\uff0c\u51c6\u661f\u5c04\u7ebf\u6253\u4e0d\u5230\u5979\uff0c\u6240\u4ee5\u8fd9\u4e00\u523b\u53f3\u51fb\u8d70\u7684\u662f\u00a7e\u300c\u6211\u9a91\u7740\u7684\u5c31\u662f\u5979\u300d\u00a7r\u8fd9\u6761\u8ba4\u4eba\u89c4\u5219\uff08\u4e0d\u4f9d\u8d56\u7784\u51c6\uff09\u3002\u00a7e\u62c9\u626f\u00a7r\u5728\"\u5979\u79bb\u4f60\u8d85\u8fc7 10 \u683c\"\u65f6\u6bcf 5 \u79d2\u5199\u4e00\u884c\"\u62c9\u626f\uff1a\u5979\u79bb\u4e3b\u4eba N \u683c\"\uff1b\u9762\u677f\u91cc\u6bcf\u4e00\u884c\u811a\u4e0b\u4e5f\u90fd\u6709\u8be6\u7ec6\u8bf4\u660e\uff08\u603b\u5f00\u5173 / \u60ac\u6302\u8ddd\u79bb / \u7b2c\u4e00\u4eba\u79f0\u534a\u900f\u660e / \u626b\u5e1a\u989d\u5916\u4e0b\u6c89 / \u91d1\u8272\u63cf\u8fb9\u5f00\u5173 / \u62c9\u626f / \u4e8c\u53f7\u4f4d\u91cd\u9524\u731b\u51fb\uff09\u3002\u00a7e\u62f4\u7ef3\u64cd\u63a7\uff08\u4ec5\u7a7a\u88ad\u6863\uff09\u00a7r\uff1a\u5979\u6b64\u523b\u00a7e\u6ca1\u6709\u76ee\u6807\u00a7r\u65f6\u2014\u2014\u4e22\u4e86\u9501\u654c\u3001\u6216\u672c\u6765\u5c31\u6ca1\u654c\u4eba\u2014\u2014\u53ea\u8981\u00a7e\u4f60\u624b\u91cc\u62ff\u7740\u6b66\u88c5\u62f4\u7ef3\u00a7r\uff08\u4e3b\u624b\u526f\u624b\u90fd\u884c\uff09\uff0c\u00a7e\u4f60\u7684\u89c6\u7ebf\u5c31\u662f\u5979\u7684\u673a\u5934\u00a7r\uff1a\u5e73\u89c6 = \u5e73\u98de\u4e0d\u6389\u9ad8\u3001\u62ac\u5934 = \u722c\u5347\u3001\u4f4e\u5934 = \u4e0b\u964d\uff08\u4fef\u4ef0 \u00b160\u00b0 \u5c01\u9876\uff09\uff0c\u901f\u5ea6\u56fa\u5b9a 0.30 \u683c/tick\uff08\u22486 \u683c/\u79d2\uff09\u3002\n\u00a7e\u4e3a\u4ec0\u4e48\u53ea\u6709\u300c\u6ca1\u76ee\u6807\u300d\u65f6\u624d\u63a5\u7ba1\u00a7r\uff1a\u6709\u654c\u4eba\u65f6\u5979\u90a3\u6761\u8ddf\u968f\u7740\u7684\u94fe\u8def\u6574\u4e2a\u4e0d\u8dd1\uff08\u63a7\u5236\u6743\u4ea4\u56de\u7a7a\u88ad\u94fe\u8def\uff09\uff0c\u6240\u4ee5\u300c\u6ca1\u5728\u64cd\u63a7\u300d\u4e0d\u7b49\u4e8e\u7ef3\u5b50\u6ca1\u7528\uff0c\u800c\u662f\u5979\u6b63\u5728\u6253\u4ed7\u3002\n\u00a7e\u5f00\u5173\u00a7r\uff1a\u9762\u677f\u300c\u6b66\u88c5\u62f4\u7ef3 \u2192 \u60ac\u6302\u65f6\u7528\u6b66\u88c5\u62f4\u7ef3\u64cd\u63a7\u65b9\u5411\u300d\uff08\u9ed8\u8ba4\u5f00\uff09\u3002\u65e5\u5fd7\u641c\u300c\u62f4\u7ef3\u64cd\u63a7\u300d\uff0c\u7b2c\u4e00\u6b21\u63a5\u7ba1\u4f1a\u5199\u4e00\u884c\uff08\u5e26\u5979\u7684\u540d\u5b57\u4e0e\u4f60\u7684\u540d\u5b57\uff09\u3002",
                "\u00a7e\u6709\u521b\u9020\u98de\u884c\u80fd\u529b\u5c31\u4e0d\u642d\u8def\u00a7r\uff1a\u53ea\u5728\u5979\u786e\u5b9e\u5177\u5907\u300c\u4eff\u521b\u9020\u98de\u884c\u300d\u80fd\u529b\u65f6\u751f\u6548\u2014\u2014\u642d\u8def\uff08\u57ab\u65b9\u5757\uff09\u6574\u6bb5\u8ba9\u4f4d\uff0c\u5979\u8981\u8fc7\u6c9f\u3001\u4e0a\u5761\u3001\u8ffd\u4e0a\u4f60\uff0c\u76f4\u63a5\u8d77\u98de\u3002\uff08\u89c1\u672c\u624b\u518c\u98de\u884c\u7ae0\u300c\u4eff\u521b\u9020\u98de\u884c\u300d\u4e00\u8282\u3002\uff09");
    }

    /**
     * v1.3.0(beta) 【骑乘指挥棒】手册章节。
     *
     * <p>实测七百四十八：整章重写为「只讲当前功能」。旧版把 714→747 每一轮的
     * 修复叙事（症状 / 根因 / 改法）全搬进了正文，越堆越长且读起来像更新日志——那些
     * 过程记录属于更新日志章，正文只该回答「现在怎么用」。本版只保留当前行为、
     * 把六台不可驾载具写明、把冰火传说龙压成一句「能挂但不建议」。
     */
    static GuideContent.Chapter rideGuide() {
        return new GuideContent.Chapter("骑乘指挥棒（让女仆骑坐骑 / 载具 / 龙）",
                "骑乘指挥棒让女仆骑上坐骑、跟着你走：原版兽（马 / 驴 / 骡 / 猪 / 炽足兽 / 骆驼…；僵尸马、骷髅马 Java 版装不上鞍、骑不了）、卓越前线的载具（坦克 / 装甲车 / 直升机 / 固定"
                        + "翼 / 飞艇…），以及冰火传说的龙（可以挂上去，但不建议，见第五节）。道具是\u00a7e【骑乘指挥棒】\u00a7r。",
                // 实测八百四十九：合成表整块画（无序：拴绳 + 木棍）
                "\u00a7e合成\u00a7r（工作台，无序）："
                        + "[[#shapeless;minecraft:lead;minecraft:stick;>maid_smart:ride_baton;@拴绳×1 + 木棍×1]]",
                "\u00a7e一、怎么绑（顺序固定：先点坐骑、再点女仆）\u00a7r",
                "\u00a7e\u624b\u6301\u9a91\u4e58\u6307\u6325\u68d2\uff0c\u53f3\u51fb\u5750\u9a91 \u2192 \u9009\u4e2d\u5b83\u00a7r\uff08\u9009\u4e2d\u90a3\u4e00\u523b\u5b83\u4eae\u8d77\u00a7e\u91d1\u8272\u63cf\u8fb9\u00a7r\uff0c\u5c31\u662f\u300c\u5149\u6807\u300d\uff09\uff1b\u00a7e\u518d\u53f3\u51fb\u81ea\u5df1\u7684\u5973\u4ec6\u00a7r \u2192 \u5f53\u573a\u914d\u5bf9\uff0c\u5979\u5750\u4e0a\u53bb\u3002\n\u00a7e\u53cd\u8fc7\u6765\u4e0d\u884c\u00a7r\uff1a\u5148\u53f3\u51fb\u5973\u4ec6\u4f1a\u88ab\u56de\u4e00\u53e5\u300c\u5148\u7528\u9a91\u4e58\u68d2\u53f3\u51fb\u5750\u9a91\uff0c\u518d\u6765\u53f3\u51fb\u6211\u300d\u3002\u987a\u5e8f\u56fa\u5b9a\u4e3a\u5148\u9009\u5750\u9a91\u3001\u518d\u9009\u5973\u4ec6\u2014\u2014\u7269\u54c1\u8bf4\u660e\u4e5f\u6309\u8fd9\u4e2a\u987a\u5e8f\u5199\u3002",
                "\u00a7e\u80fd\u4e0d\u80fd\u9a91\u00a7r\uff1a\u539f\u7248\u5750\u9a91\u5fc5\u987b\u00a7e\u5df2\u4e0a\u978d\u00a7r"
                + "\uff08\u6ca1\u4e0a\u978d\u4f1a\u63d0\u793a\u300c\u5148\u7ed9\u5b83\u88c5\u4e0a\u978d\u518d\u7ed1\u7ed9\u6211"
                + "\u5427\u300d\uff09\uff1b\u5353\u8d8a\u524d\u7ebf\u7684\u8f7d\u5177\u8981\u00a7e\u6709\u5ea7\u4f4d\u3001\u6ca1"
                + "\u62a5\u5e9f\u00a7r\uff1b\u9f99\u8981\u00a7e\u5df2\u9a6f\u670d\u3001\u9636\u6bb5 \u2265 2\u00a7r\uff081 \u9636"
                + "\u6bb5\u7684\u5c0f\u9f99\u9a91\u4e0d\u4e86\uff09\u3002\n\n\u00a7e\u65e0\u978d\u53ef\u9a91\u7684\u4ec6\u4ece"
                + "\u00a7r\uff1a\u8be1\u5384\u5deb\u6cd5\u7684\u7ea2\u77f3\u5de8\u517d / \u718a / \u52ab\u63a0\u517d / \u8718\u86db"
                + "\u7cfb\u8fd9\u7c7b\n\u00a7e\u4e0d\u9700\u8981\u978d\u00a7r\u3001\u539f\u7248\u9760\u300c\u4e3b\u4eba\u7a7a\u624b"
                + "\u53f3\u51fb\u4e00\u4e0b\u5c31\u9a91\u4e0a\u53bb\u300d\u7684\u6a21\u7ec4\u4ec6\u4ece\uff08\u4ee5\u53ca\u5957"
                + "\u7528\u540c\u4e00\u5957\u4ee3\u7801\u7684\u6574\u5408\u5305\u4ec6\u4ece\uff0c\u5982\u8be1\u5384\u707e\u53d8"
                + "\u7684\u4e0b\u754c\u5408\u91d1\u5de8\u517d\u4ec6\u4ece\uff09\u4e5f\u80fd\u9a91\u2014\u2014\u5b83\u4eec\n\u00a7e"
                + "\u4e0d\u662f\u300c\u5df2\u4e0a\u978d\u7684\u5750\u9a91\u300d\u00a7r\uff0c\u8d70\u7684\u662f\u4e13\u95e8\u5f00"
                + "\u7684\n\u00a7e\u300c\u65e0\u978d\u53ef\u9a91\u4ec6\u4ece\u300d\u00a7r\u540e\u95e8\uff08\u9ed8\u8ba4\u5f00\uff09"
                + "\u3002",
                "\u00a7e\u8fd9\u7c7b\u4ec6\u4ece\u9a91\u4e0a\u4e4b\u540e\u00a7e\u53ea\u8d4b\u4e88\u5b83\u901f\u5ea6\uff0c\u5176"
                + "\u4f59\u884c\u52a8\u903b\u8f91\u5168\u6362\u6210\u5b83\u81ea\u5df1\u7684 AI\u00a7r\u3002\u5b83\u4eec\u00a7e"
                + "\u81ea\u5e26\u4e00\u6574\u5957\u6218\u6597 AI\u00a7r\uff08\u81ea\u4e3b\u9501\u654c + \u5de1\u903b / \u63a5\u8fd1"
                + " / \u5168\u90e8\u6280\u80fd\uff09\uff0c\u6240\u4ee5\u672c\u6a21\u7ec4\u00a7e\u4e0d\u518d\u5582\u8d70\u4f4d\u3001"
                + "\u4e0d\u518d\u66ff\u5b83\u5199\u76ee\u6807\u3001\u4e0d\u518d\u66ff\u5b83\u51fa\u62db\u00a7r\u2014\u2014\u6574"
                + "\u53ea\u4ea4\u56de\u5b83\u81ea\u5df1\u7684 AI\uff08\u00a7e\u4f60\u53ea\u7ba1\u9a91\uff0c\u5b83\u81ea\u5df1\u6253"
                + "\u00a7r\uff09\u3002\u552f\u4e00\u7684\u4f8b\u5916\u662f\u00a7e home \u6a21\u5f0f\u00a7r\uff1a\u90a3\u65f6\u5750"
                + "\u9a91\u4f1a\u505c\u4e0b\u6765\uff08\u6240\u6709\u5750\u9a91\u901a\u7528\u7684\u4f8b\u5916\uff09\u3002\u00a7e"
                + "\u4f24\u5bb3\u8f6c\u79fb\u00a7r\uff1a\u5979\u9a91\u7740\u8fd9\u7c7b\u4ec6\u4ece\u65f6\u00a7e\u53d7\u5230\u7684"
                + "\u4f24\u5bb3\u8f6c\u7ed9\u8eab\u4e0b\u7684\u5750\u9a91\u00a7r\uff08\u8fd1\u6218 / \u5f39\u5c04\u7269 / \u7206"
                + "\u70b8 / \u706b / \u5ca9\u6d46\u2026\u5168\u90e8\u8f6c\u79fb\uff1b\u865a\u7a7a / \u5361\u5899 / \u6324\u538b / "
                + "\u649e\u5899\u8fd9\u7c7b\u6bcf\u62cd\u91cd\u590d\u7684\u73af\u5883\u81ea\u4f24\u4e0d\u8f6c\u79fb\uff0c\u514d"
                + "\u5f97\u4e24\u4e2a\u4e00\u8d77\u88ab\u6324\u6b7b\uff09\u3002\u00a7e\u5f00\u5173\u89c1\u7b2c\u4e94\u8282\u3002",
                "\u00a7e\u4e3b\u4eba\u7a7a\u624b\u53f3\u51fb = \u4e3b\u4eba\u76f4\u63a5\u63a5\u7ba1\u00a7r\uff1a\u8fd9\u7c7b"
                + "\u4ec6\u4ece\u53ea\u6709\u4e00\u4e2a\u9a7e\u9a76\u4f4d\uff0c\u4f60\u60f3\u81ea\u5df1\u5f00\u7684\u65f6\u5019"
                + "\uff0c\u00a7e\u7a7a\u624b\u53f3\u51fb\u5b83\u4e00\u4e0b\u00a7r\u2014\u2014\u5973\u4ec6\u4f1a\u7acb\u523b\u5e72"
                + "\u51c0\u4e0b\u978d\uff08\u64a4\u6807\u8bb0\u3001\u65ad\u94fe\u8def\u3001\u8fd8\u539f\u5750\u59ff\uff09\uff0c"
                + "\u8fd9\u4e00\u4e0b\u53f3\u51fb\u7ee7\u7eed\u4ea4\u7ed9\u8be1\u5384\u539f\u7248\u628a\u00a7e\u4f60\u00a7r\u9a91"
                + "\u4e0a\u53bb\uff0c\u4e4b\u540e\u6309\u539f\u7248\u7531\u4f60\u64cd\u63a7\u3002\u00a7e\u53ea\u6709\u5b83\u81ea"
                + "\u5df1\u7684\u4e3b\u4eba\u00a7r\u505a\u5f97\u5230\uff08\u539f\u7248\u5c31\u53ea\u8ba4\u4e3b\u4eba\uff09\uff1b"
                + "\u62ff\u4e1c\u897f / \u62ff\u6307\u6325\u68d2\u7a7a\u624b\u4e0d\u7b97\uff0c\u53f3\u51fb\u5973\u4ec6\u6216\u522b"
                + "\u7684\u5750\u9a91\u4e5f\u4e0d\u53d7\u5f71\u54cd\u3002\n\n\u00a7e\u9009\u4e2d\u8981\u6c42\u00a7r\uff1a\u70b9"
                + "\u8fc7\u5374\u6ca1\u914d\u5bf9\u7684\uff0c\u91d1\u8272\u63cf\u8fb9 \u00a7e30 \u79d2\u540e\u81ea\u5df1\u7184"
                + "\u706f\u00a7r\uff1b\u5e26\u6807\u8bb0\u4f46\u5df2\u67e5\u65e0\u5f52\u5c5e\u7684\u6bcf 5 \u79d2\u6e05\u4e00\u6b21"
                + "\uff0c\u4e0d\u4f1a\u6b8b\u7559\u3002\u4f60\u81ea\u5df1\u4e2d\u5149\u7075\u7bad\u3001\u522b\u7684\u6a21\u7ec4"
                + "\u8ba9\u8c01\u53d1\u5149\uff0c\u672c\u6a21\u7ec4\u4e00\u4e2a\u90fd\u4e0d\u78b0\u3002\n\n\u00a7e\u5360\u7528"
                + "\u89c4\u5219\u00a7r\uff1a\u00a7e\u4e00\u53ea\u5750\u9a91\u540c\u65f6\u53ea\u670d\u52a1\u4e00\u4f4d\u5973\u4ec6"
                + "\u00a7r\u3002\u5f80\u4e00\u8f86\u5df2\u7ecf\u6709\u5973\u4ec6\u7684\u8f66\u4e0a\u518d\u7ed1\uff0c\u4f1a\u88ab"
                + "\u56de\u4e00\u53e5\u300c\u8fd9\u53ea\u5750\u9a91\u5df2\u7ecf\u6709\u5973\u4ec6\u4e86\uff5e\u300d\uff0c\u00a7e"
                + "\u5148\u524d\u90a3\u4f4d\u4e00\u4e2a\u5b57\u90fd\u4e0d\u52a8\u00a7r\u3002",
                "\u00a7e\u5979\u518d\u7ed1\u4e00\u6b21 = \u6362\u7ed1\u00a7r\uff1a\u540c\u4e00\u4f4d\u5973\u4ec6\u62ff\u6307"
                + "\u6325\u68d2\u91cd\u65b0\u914d\u5bf9\u5230\u53e6\u4e00\u53ea\u5750\u9a91\uff0c\u5979\u81ea\u5df1\u90a3\u6761"
                + "\u4f1a\u81ea\u52a8\u6362\u6210\u65b0\u7684\u3002",
                "\u00a7e二、怎么解\u00a7r",
                "\u00a7e\u6f5c\u884c\uff08\u8e72\u4e0b\uff09+ \u53f3\u51fb\u00a7r\u5973\u4ec6\u6216\u5750\u9a91\uff0c\u5979\u5c31\u4e0b\u6765\u3002\n\u00a7e\u7ed1\u5b9a\u6001\u4e0b\u518d\u53f3\u51fb\u4e00\u6b21\u00a7r\u5973\u4ec6\u6216\u5750\u9a91\u4e5f\u662f\u89e3\u9664\u3002\n\u00a7e\u6536\u8fdb\u9b42\u7b26 = \u7acb\u523b\u89e3\u4e00\u6b21\u00a7r\uff1a\u7528\u9b42\u7b26\u628a\u5979\u6536\u8d77\u6765\u7684\u90a3\u4e00\u523b\uff0c\u00a7e\u5973\u4ec6\u4e0e\u5750\u9a91\u8eab\u4e0a\u7684\u5149\u6807\u4f1a\u7acb\u523b\u64a4\u6389\u00a7r\uff08\u8fde\u540c\u9a91\u4e58\u5173\u7cfb\u4e00\u8d77\u5e72\u51c0\u89e3\u9664\uff09\uff0c\u00a7e\u518d\u653e\u51fa\u6765\u4e5f\u4e0d\u4f1a\u5e26\u7740\u65e7\u5149\u6807\u00a7r\u3002\u5149\u6807\u7684\u771f\u8eab\u662f\u5199\u8fdb\u5979\u5b58\u6863\u91cc\u7684\u53d1\u5149\u6807\u8bb0\uff0c\u6536\u7b26\u65f6\u00a7e\u8fde\u7b26\u91cc\u90a3\u4efd\u5b58\u6863\u00a7r\u4e00\u8d77\u6539\uff0c\u653e\u51fa\u6765\u4e24\u8fb9\u90fd\u5e72\u51c0\u3002\n\u5979\u81ea\u5df1\u00a7e\u6389\u4e0b\u5750\u9a91 / \u5750\u9a91\u6ca1\u4e86 / \u6362\u4efb\u52a1 / \u8de8\u7ef4\u5ea6\u00a7r\u90fd\u4f1a\u5728\u4e0b\u4e00\u62cd\u81ea\u52a8\u89e3\u9664\u5e76\u6e05\u6807\u8bb0\u3002\u771f\u89e3\u9664\u65f6\u00a7e\u5750\u59ff\u3001\u91cd\u529b\u3001\u9f99\u7684\u884c\u52a8\u6863\u4e00\u5e76\u8fd8\u539f\u00a7r\u3002",
                "\u00a7e三、手持指挥棒的三种操作（这里最容易记混）\u00a7r",
                "\u00a7e\u2460 \u53f3\u51fb\u5750\u9a91 / \u5973\u4ec6 = \u9009\u4e2d\u3001\u914d\u5bf9\u3001\u89e3\u9664\u00a7r\uff08\u5c31\u662f\u4e0a\u9762\u7684\u7ed1\u4e0e\u89e3\uff09\u3002\n\u00a7e\u2461 \u5de6\u51fb = \u4e3b\u9a7e \u2194 \u526f\u9a7e \u6362\u5ea7\u00a7r\uff1a\u4f60\u5750\u5728\u5973\u4ec6\u5f00\u7684\u8f66\u4e0a\u65f6\uff0c\u00a7e\u62ff\u7740\u6307\u6325\u68d2\u5de6\u51fb\u4e00\u4e0b\u00a7r\u5c31\u6362\u5230\u53e6\u4e00\u4e2a\u5ea7\u4f4d\uff0c\u00a7e\u518d\u5de6\u51fb\u4e00\u4e0b\u6362\u56de\u6765\u00a7r\uff08\u5979\u5f00\u7684\u65f6\u5019\u4f60\u5750\u526f\u9a7e\u3001\u4f60\u5f00\u7684\u65f6\u5019\u5979\u56de\u9a7e\u9a76\u4f4d\uff09\u3002\u00a7e\u53ea\u6709\u5353\u8d8a\u524d\u7ebf\u7684\u591a\u5ea7\u8f7d\u5177\u00a7r\u6709\u8fd9\u4e00\u6863\uff08\u539f\u7248\u9a6c / \u732a\u53ea\u6709\u4e00\u4e2a\u5ea7\u4f4d\uff09\u3002\u5de6\u51fb\u90a3\u4e00\u4e0b\u00a7e\u4e0d\u4f1a\u6253\u5230\u4f60\u81ea\u5df1\u5750\u7684\u8f66\u00a7r\uff0c\u52a8\u4f5c\u680f\u4f1a\u7ed9\u4e00\u884c\u63d0\u793a\u3002\n\u00a7e\u2462 \u7a7a\u624b\u53f3\u51fb\u00a7r\u5973\u4ec6\u5f00\u7684\u8f7d\u5177 = \u00a7e\u5750\u8fdb\u7a7a\u7740\u7684\u526f\u9a7e\u00a7r\uff08\u5979\u7559\u5728\u9a7e\u9a76\u4f4d\u7ee7\u7eed\u5f00\uff09\u3002\u00a7e\u624b\u91cc\u62ff\u7740\u6307\u6325\u68d2\u65f6\u7edd\u5bf9\u4e0d\u767b\u4e58\u00a7r\u2014\u2014\u00a7e\u9a91\u4e58\u6307\u6325\u68d2\u4f18\u5148\u7ea7\u6700\u9ad8\u00a7r\uff0c\u90a3\u4e00\u4e0b\u53ea\u6709\u9009\u4e2d / \u89e3\u9664\u529f\u80fd\uff1b\u5355\u5ea7\u8f66\u6216\u5750\u6ee1\u4e86\u5219\u8fd9\u4e00\u4e0b\u4ec0\u4e48\u4e5f\u4e0d\u505a\u3002\u00a7e\u2463 \u9a91\u4e58\u4e2d\u62ff\u6307\u6325\u68d2\u53f3\u51fb = \u4ec0\u4e48\u90fd\u4e0d\u4f1a\u53d1\u751f\u00a7r\uff1a\u53ea\u8981\u4f60\u00a7e\u6b63\u9a91\u7740\u4efb\u4f55\u4e1c\u897f\u00a7r\uff08\u8f66\u3001\u9a6c\u3001\u9f99\u3001\u626b\u5e1a\u2026\uff09\uff0c\u624b\u91cc\u7684\u6307\u6325\u68d2\u53f3\u51fb\u4f1a\u88ab\u00a7e\u6574\u4e0b\u53d6\u6d88\u00a7r\u2014\u2014\u4e0d\u7ed1\u5b9a\u3001\u4e0d\u89e3\u9664\u3001\u4e5f\u4e0d\u78b0\u8f7d\u5177\u81ea\u5df1\u7684\u53f3\u51fb\u5206\u652f\u3002\u60f3\u64cd\u4f5c\u5c31\u00a7e\u5148\u4e0b\u5750\u9a91\u3001\u7ad9\u5728\u5730\u4e0a\u00a7r\u518d\u53f3\u51fb\u3002",
                "\u00a7e四、她怎么「走」：没任务就跟着你，有任务才走任务的路\u00a7r",
                "\u00a7e\u5957\u7684\u5c31\u662f\u539f\u7248\u50f5\u5c38\u9a91\u9e21\u90a3\u5957\u00a7r\uff1a\u5979\u5750\u4e0a"
                + "\u53bb\u4e4b\u540e\n\u00a7e\u79fb\u52a8\u7531\u5750\u9a91\u8d1f\u8d23\u00a7r\uff0c\u672c\u6a21\u7ec4\u53ea\u51b3"
                + "\u5b9a\u300c\u5f80\u54ea\u8d70\u300d\uff0c\u4e0a\u4e0b\u5761 / \u7ed5\u969c / \u8df3\u8dc3\u4e00\u5f8b\u4ea4"
                + "\u7ed9\u5750\u9a91\u81ea\u5df1\u7684\u5bfb\u8def\u3002\n\u00a7e\u9646\u5730\u5750\u9a91\u76f4\u63a5\u7528\u300c"
                + "\u5979\u81ea\u5df1\u7684\u79fb\u52a8\u903b\u8f91\u300d\u00a7r\uff1a\u00a7e\u539f\u7248\u9a6c / \u9a74 / \u9aa1 /"
                + " \u9a86\u9a7c\u00a7r\uff08\u4ee5\u53ca\u4efb\u4f55\u522b\u7684\u6a21\u7ec4\u7684\u53ef\u9a91\u4e58\u751f\u7269"
                + "\uff09\u00a7e\u4e0d\u518d\u7531\u672c\u6a21\u7ec4\u53e6\u5199\u4e00\u5957\u8d70\u4f4d\u00a7r\u2014\u2014\u5979"
                + "\u7684\u6218\u6597\u8d70\u4f4d\u3001\u4efb\u52a1\u8d70\u4f4d\u3001\u8ddf\u7740\u4f60\u8d70\uff0c\u5168\u90fd"
                + "\u5728\u00a7e\u5979\u81ea\u5df1\u7684\u5bfb\u8def\u00a7r\u4e0a\u4ea7\u751f\uff0c\u672c\u6a21\u7ec4\u53ea\u628a"
                + "\u5979\u5bfb\u8def\u4e0a\u90a3\u4e2a\u300c\u8981\u53bb\u7684\u5730\u65b9\u300d\u539f\u6837\u8f6c\u7ed9\u5750"
                + "\u9a91\u00a7r\u3002\u5979\u600e\u4e48\u7ed5\u969c\u788d\u3001\u7528\u4ec0\u4e48\u901f\u5ea6\u3001\u63a5\u654c"
                + "\u600e\u4e48\u8fc2\u56de\uff0c\u00a7e\u5168\u90fd\u662f\u5979\u81ea\u5df1\u90a3\u5957\u00a7r\uff0c\u8ddf\u968f"
                + "\u4e0e\u4f5c\u6218\u81ea\u7136\u540c\u6b65\u3002\u5979\u6ca1\u5728\u63a5\u654c\u3001\u81ea\u5df1\u4e5f\u6ca1"
                + "\u6709\u4efb\u52a1\u8d70\u4f4d\u65f6\uff0c\u672c\u6a21\u7ec4\u6309\u00a7e\u4e0e TLM \u8ddf\u968f\u76f8\u540c"
                + "\u7684\u8bed\u4e49\u00a7r\u628a\u00a7e\u4f60\u672c\u4eba\u00a7r\u4ea4\u7ed9\u5750\u9a91\uff08\u591f\u8fd1\u5c31"
                + "\u505c + \u8f6c\u5934\u770b\u4f60\uff09\uff0c\u800c\u4e0d\u662f\u66ff\u5979\u51b3\u5b9a\u8def\u7ebf\u3002",
                "\u00a7e\u5353\u8d8a\u524d\u7ebf\u7684\u8f7d\u5177\uff08\u5766\u514b / \u76f4\u5347\u673a / \u56fa\u5b9a\u7ffc / "
                + "\u8f6e\u6905\u2026\uff09\u4e0e\u51b0\u706b\u4f20\u8bf4\u7684\u9f99\u00a7r\u662f\n\u00a7e\u4f8b\u5916\u00a7r"
                + "\uff1a\u5b83\u4eec\u4e0d\u662f\u539f\u7248\u5750\u9a91\uff0c\u6709\u81ea\u5df1\u7684\u5f15\u64ce / \u98de\u884c"
                + "\u7269\u7406\uff0c\u8d70\u7684\u662f\u00a7e\u4e13\u7528\u9a71\u52a8\u00a7r\u3002",
                "\u00a7e\u5ea7\u9a91\u53e3\u5f84\u4e09\u4ef6\u4e8b\u00a7r\uff1a\n\n\u00a7e\u2460 \u8f6c\u7ed9\u5979\u5bfb\u8def"
                + "\u4e0a\u7684\u7ec8\u70b9\u00a7r\uff1a\u4ea4\u7ed9\u5750\u9a91\u7684\u662f\u00a7e\u5979\u8fd9\u4e00\u8d9f\u771f"
                + "\u6b63\u8981\u53bb\u7684\u5730\u65b9\u00a7r\uff08\u901a\u5e38\u79bb\u5f97\u8fdc\uff09\uff0c\u5750\u9a91\u00a7e"
                + "\u4e00\u6b21\u89c4\u5212\u3001\u5168\u7a0b\u5168\u901f\u00a7r\uff1b\u5979\u7a7a\u95f2\u65f6\u6309 TLM \u8ddf"
                + "\u968f\u540c\u4e00\u53e3\u5f84\u628a\u00a7e\u4f60\u672c\u4eba\u00a7r\u4ea4\u7ed9\u5750\u9a91\uff0c\u00a7e\u8d70"
                + "\u5230 2 \u683c\u5185\u505c\u4e0b\u5e76\u8f6c\u5934\u770b\u4f60\u00a7r\u3002\n\n\u00a7e\u2461 \u9a71\u52a8\u8282"
                + "\u594f\u4e3a\u00a7e\u6bcf tick\u00a7r\uff1a\u5979\u5728\u5730\u4e0a\u8dd1\u662f 20 Hz\uff0c\u5750\u9a91\u4e5f"
                + "\u6bcf tick \u62ff\u4e00\u6b21\u65b0\u76ee\u6807\uff0c\u8d77\u6b65 / \u8f6c\u5411\u4e0d\u518d\u6709\u5ef6\u8fdf"
                + "\u3002\n\n\u00a7e\u2462 \u4e24\u4e2a\u64cd\u4f5c\u53e3\u5f84\u00a7r\uff1a\n\u00a7e\u5b88\u5bb6\uff08home \u6a21"
                + "\u5f0f\uff09\u00a7r\u65f6\u5979\u5750\u7684\u5750\u9a91\n\u00a7e\u7acb\u523b\u505c\u00a7r\uff08\u4e0e TLM\u300c"
                + "\u5b88\u5bb6\u4e0d\u8ddf\u968f\u300d\u540c\u6e90\uff09\uff1b\n\u00a7e\u591a\u53ea\u5973\u4ec6\u5750\u5353\u8d8a"
                + "\u524d\u7ebf\u8f7d\u5177\u65f6\uff0c5 \u683c\u4ee5\u5185\u7684\u522b\u7684\u8f7d\u5177\u4f1a\u4e92\u76f8\u5f39"
                + "\u5f00\u00a7r\uff08\u6bcf tick \u53e0\u4e00\u70b9\u5411\u5916\u7684\u901f\u5ea6\uff0c\u8d8a\u8fd1\u63a8\u5f97"
                + "\u8d8a\u72e0\u3001\u5c01\u9876 3 \u500d\uff09\uff0c\u4e0d\u518d\u6324\u6210\u4e00\u56e2\u3002",
                "\u00a7e\u5b88\u5bb6\u5bf9\u98de\u884c\u8f7d\u5177\u4e5f\u751f\u6548\u00a7r\uff1a\u00a7e\u5b88\u5bb6\u7684\u98de"
                + "\u884c\u8f7d\u5177\u5c31\u5730\u60ac\u505c\u00a7r\uff08\u628a\u76ee\u6807\u70b9\u8bbe\u6210\u5b83\u00a7e\u6b64"
                + "\u523b\u7684\u4f4d\u7f6e\u00a7r\u3001\u6c34\u5e73+\u7ad6\u76f4\u90fd\u4fdd\u6301\uff0c\u5c31\u662f\u00a7e\u5b9a"
                + "\u9ad8\u60ac\u505c\u00a7r\uff09\uff0c\u00a7e\u4e0d\u518d\u4ea7\u751f\u4efb\u4f55\u5f80\u4e3b\u4eba/\u654c\u4eba"
                + "\u53bb\u7684\u9a71\u52a8\u00a7r\uff08\u5730\u9762\u5750\u9a91\u7acb\u523b\u505c+\u8f6c\u5934\u770b\u4f60\uff09"
                + "\u3002\n\u00a7e\u8f66\u4e0a\u7d22\u654c\u4e0d\u628a\u300c\u4ec0\u4e48\u4e1c\u897f\u300d\u90fd\u5f53\u654c\u4eba"
                + "\u00a7r\uff1a\u00a7e\u81ea\u52a8\u7d22\u654c\u4e0e\u8f7d\u5177\u5f00\u706b\u5171\u7528\u4e00\u6761\u5e26 5 "
                + "\u79d2\u7a97\u53e3\u7684\u5224\u5b9a\u00a7r\uff08\u672c\u6a21\u7ec4\u81ea\u5df1\u7684 NeutralThreatDriver\uff09"
                + "\uff1a\u00a7e\u771f\u654c\u5bf9\uff08Enemy\uff09\u00a7r\u3001\u00a7e5 \u79d2\u5185\u771f\u7684\u4ea4\u8fc7\u624b"
                + "\u00a7r\uff08\u5979/\u4e3b\u4eba\u6253\u8fc7\u5b83\u3001\u5b83\u6253\u8fc7\u5979/\u4e3b\u4eba\uff09\u3001\u00a7e"
                + "\u6216\u5b83\u6b64\u523b\u6b63\u9501\u7740\u672c\u6a21\u7ec4\u00a7r\u2014\u2014\u4e09\u6761\u90fd\u4e0d\u6ee1"
                + "\u8db3\u5c31\u00a7e\u4e0d\u5f53\u654c\u4eba\u00a7r\u3002\u6b63\u5728\u6253\u7684\u4ed7\uff08\u542b\u4e0d\u5b9e"
                + "\u73b0 Enemy \u7684\u6a21\u7ec4 boss\uff09\u4e00\u6761\u90fd\u4e0d\u53d7\u5f71\u54cd\uff1b\u73a9\u5bb6/\u76d4"
                + "\u7532\u67b6/\u5ba0\u7269/\u6751\u6c11\u8fd9\u4e9b\u7c7b\u578b\u95f8\u4e5f\u4e00\u4e2a\u90fd\u6ca1\u653e\u5bbd"
                + "\u3002",
                "\u00a7e\u9a91\u4e58\u65f6\u5979\u7684\u5bfb\u8def\u4e0d\u518d\u88ab\u81ea\u5df1\u4eba\u6bcf\u62cd\u6e05\u6389"
                + "\u00a7r\uff1a\u81ea\u4fdd\u91cc\u6709\u4e00\u6761\u00a7e\u300c\u5750\u4e0b\u5c31\u9501\u79fb\u52a8\u300d\u00a7r"
                + "\uff08\u5750\u4e0b = \u73a9\u5bb6\u8981\u5979\u5f85\u7740\u522b\u52a8\uff0c\u4e8e\u662f\u6bcf\u62cd\u6e05\u5979"
                + "\u7684\u5bfb\u8def\u4e0e\u6c34\u5e73\u901f\u5ea6\uff09\uff0c\u800c\u00a7e\u5979\u9a91\u5728\u5750\u9a91\u4e0a"
                + "\u65f6\u7684\u5750\u59ff\u4e0d\u662f\u4f60\u7684\u6307\u4ee4\u00a7r\uff0c\u662f\u00a7e\u672c\u6a21\u7ec4\u81ea"
                + "\u5df1\u6bcf\u62cd\u66ff\u5979\u538b\u4e0a\u53bb\u7684\u00a7r\uff08\u4e3a\u4e86\u8ba9\u5979\u7528\u5750\u59ff"
                + "\u6a21\u578b\u8d34\u978d\uff09\uff1b\n\u73b0\u5728\n\u00a7e\u9a91\u4e58\u5973\u4ec6\u4e0d\u518d\u5403\u8fd9"
                + "\u628a\u9501\u00a7r\uff1a\u5750\u59ff\u5f52\u9a91\u4e58\u94fe\u8def\u7ba1\u3001\u79fb\u52a8\u5f52\u5979\u81ea"
                + "\u5df1\u7684\u5bfb\u8def\u7ba1\u3002",
                "\u00a7e\u300cNPC \u5f62\u6001\u300d\u7684\u76ee\u6807\u4e0d\u4f1a\u88ab\u7a7a\u88ad\u8bef\u4f24\u00a7r\uff1a"
                + "\u8fd9\u7c7b\u6a21\u7ec4 NPC \u4e0d\u5b9e\u73b0 Enemy\u3001\u88ab TLM \u5f52\u5165\u300c\u4e2d\u7acb\u300d\uff0c"
                + "\u4e2d\u7acb\u7684\u5408\u6cd5\u6027\u53ea\u770b\u00a7e\u8bb0\u4ec7\u5b57\u6bb5\u00a7r\u2014\u2014\u4f60\u4ee5"
                + "\u524d\u8ddf\u5b83\u4ea4\u8fc7\u624b\uff0c\u5b83\u5c31\u88ab\u5f53\u6210\u5408\u6cd5\u76ee\u6807\uff1b\u5973"
                + "\u4ec6\u81ea\u5df1\u7684\u4efb\u52a1\u94fe\u534a\u5f84\u5c0f\u3001\u5e73\u65f6\u626b\u4e0d\u5230\u5b83\uff0c"
                + "\u7a7a\u88ad/\u626b\u5e1a\u7684 50 \u683c\u81ea\u52a8\u7d22\u654c\u626b\u5f97\u5230 \u21d2 \u53ea\u6709\u7a7a"
                + "\u88ad\u6253\u3002\u73b0\u5728\u00a7e\u626b\u5e1a\u6a21\u5f0f\u300c\u95ee\u4e0d\u5230\u5c31\u9000\u56de TLM "
                + "\u539f\u94fe\u300d\u7684\u90a3\u6761\u515c\u5e95\u4e5f\u7eb3\u5165\u540c\u4e00\u628a\u5c3a\u00a7r\uff085 \u79d2"
                + "\u7a97\u53e3\u7684 LiveThreat\uff09\uff1a\u7a7a\u88ad\u4e0e\u626b\u5e1a\u7684\u6bcf\u4e00\u6b21\u9501\u654c"
                + "\u3001\u6bcf\u4e00\u6b21\u5f00\u706b\u3001\u6bcf\u4e00\u6b21\u6295\u5f39\u90fd\u8d70\u5b83\u3002\u00a7e\u6b63"
                + "\u5728\u6253\u7684\u4ed7\u4e0d\u53d7\u5f71\u54cd\u00a7r\u2014\u2014\u771f\u654c\u5bf9\u30015 \u79d2\u5185\u771f"
                + "\u7684\u4ea4\u8fc7\u624b\u3001\u6216\u5b83\u6b63\u9501\u7740\u672c\u6a21\u7ec4\uff08\u542b\u4e0d\u5b9e\u73b0 Ene"
                + "my \u7684\u6a21\u7ec4 boss\uff09\u7167\u6253\uff1b\u73a9\u5bb6/\u76d4\u7532\u67b6/\u5ba0\u7269/\u6751\u6c11"
                + "\u7684\u7c7b\u578b\u95f8\u4e5f\u6ca1\u653e\u5bbd\u3002",
                "\u00a7e\u3010\u591a\u8f66\u4e0d\u518d\u300c\u53e0\u7f57\u6c49\u300d\u00a7r\u3011\u591a\u8f86\u8f7d\u5177\u5e76"
                + "\u884c\u65f6\u4f1a\u4e92\u76f8\u8ba9\u4f4d\uff1a\u63a8\u6324\u6539\u6210\u00a7e\u76f4\u63a5\u632a\u4f4d\u7f6e"
                + "\u00a7r\uff08\u6c34\u5e73\u3001\u6bcf\u62cd\u6700\u591a\u7ea6 0.28 \u683c\uff09\uff0c\u4e0d\u4f1a\u88ab\u8f7d"
                + "\u5177\u5f15\u64ce\u91cd\u7b97\uff1b\u95f4\u8ddd\u4e0e\u5c01\u9876\u00a7e\u6309\u8f66\u4f53\u5c3a\u5bf8\u00a7r"
                + "\uff08\u8f7d\u5177\u6309\u300c\u8f66\u4f53\u5168\u5bbd + 1.5 \u683c\u7f1d\u300d\u653e\u5927\uff0c\u4e24\u8f66"
                + "\u95f4\u8ddd = max(5 \u683c, \u4e24\u8f66\u5168\u5bbd\u4e4b\u548c \u00f7 2 + 1 \u683c\u7f1d)\uff09\uff1b\u63a5"
                + "\u654c\u7ed5\u5708\u7684\u300c\u80e1\u841d\u535c\u300d\u70b9\u4e5f\u8d70\u540c\u4e00\u9053\u4e92\u65a5\uff1b"
                + "\u00a7e\u53ea\u6709\u6cbf\u5206\u79bb\u65b9\u5411\u5df2\u5728\u5f80\u5916\u8d70\u624d\u7b97\u300c\u5df2\u7ecf"
                + "\u5728\u8dd1\u300d\u00a7r\u3001\u4e0d\u518d\u63a8\u3002\u00a7e\u65e5\u5fd7\u7559\u75d5\u00a7r\uff1a\u8fd0\u884c"
                + "\u65e5\u5fd7\u641c\u300c\u00a7e\u8f7d\u5177\u4e92\u65a5\u00a7r\u300d\u53ef\u770b\u54ea\u4e24\u8f86\u8f66\u3001"
                + "\u5f53\u65f6\u591a\u8fd1\u3001\u63a8\u5f00\u591a\u5c11\u3002",
                "\u00a7e\u3010\u9a91\u5728\u5750\u9a91\u4e0a\u4e5f\u80fd\u89e6\u53d1\u6a2a\u626b\u4e4b\u5203\u00a7r\u3011\u5979"
                + "\u00a7e\u662f\u4e58\u5ba2\u00a7r\uff08\u539f\u7248\u5750\u9a91 / \u5353\u8d8a\u524d\u7ebf\u8f7d\u5177 / \u626b"
                + "\u5e1a / \u8239 / \u77ff\u8f66\uff09\u6216\u00a7e\u6302\u5728\u51b0\u706b\u4f20\u8bf4\u9f99\u7684\u60ac\u7a7a"
                + "\u978d\u4f4d\u00a7r\u4e0a\u65f6\u7167\u5e38\u6a2a\u626b\uff0c\u4e0e\u4f60\u4eb2\u81ea\u9a91\u7740\u5750\u9a91"
                + "\u6325\u5251\u540c\u6b3e\uff1b\u53ea\u6709\u00a7e\u771f\u7684\u8df3\u5288/\u5760\u843d\u624d\u7b97\u7a7a\u4e2d"
                + "\u00a7r\uff0c\u8df3\u5288\u4fdd\u6301\u5355\u4f53\u66b4\u51fb\u3001\u4e0d\u6a2a\u626b\u3002\n\n\u00a7e\u3010"
                + "\u5750\u9f99\u98de\u884c\u65f6\u5979\u8ddf\u7740\u9f99\u4e00\u8d77\u4fef\u4ef0\u00a7r\u3011\u9f99\u9a91\u4f4d"
                + "\u540c\u6b65\n\u00a7e\u4fef\u4ef0\u00a7r\uff08\u542b\u4e0a\u4e00\u62cd\uff0c\u4fdd\u8bc1\u62ac\u5934\u63d2\u503c"
                + "\u4e0e\u9f99\u540c\u6e90\uff09\uff0c\u5979\u7684\u671d\u5411\u4e0e\u9f99\u00a7e\u9010\u5e27\u4e00\u81f4\u00a7r"
                + "\u3002\uff08\u9f99\u9a91\u4f4d\u7684\u5176\u4f59\u53e3\u5f84\u89c1\u4e0b\u8282\u4e0e\u300c\u9f99\u300d\u76f8"
                + "\u5173\u6761\u76ee\u3002\uff09\n\u00a7e\u3010\u6ca1\u7535\u7684\u8f7d\u5177\uff08\u76f4\u5347\u673a/\u56fa\u5b9a"
                + "\u7ffc\u7b49\uff09\u4e0d\u80fd\u8d77\u98de\u00a7r\u3011\u5199\u63a8\u529b\u4e4b\u524d\u5148\u95ee\u4e00\u904d"
                + "\u5f15\u64ce\u7684\u7535\u91cf\u95f8\uff08\u4e0e\u5f15\u64ce\u540c\u53e3\u5f84\uff1a\u00a7e\u7535\u91cf \u2264 "
                + "\u6bcf\u62cd\u8017\u7535\u00a7r\u5373\u7184\u706b\u3001\u63a8\u529b\u8870\u51cf\uff09\uff1b\u00a7e\u7535\u91cf"
                + "\u89c1\u5e95\u5c31\u8fd9\u4e00\u62cd\u4e0d\u9a71\u52a8\u00a7r\uff08\u677e\u6cb9\u95e8 + \u6e05\u8f93\u5165\uff09"
                + "\uff0c\u8f7d\u5177\u81ea\u7136\u843d\u4e0b\uff1b\u6ca1\u6709\u80fd\u91cf\u4ed3\u7684\u8f7d\u5177\u6c38\u4e0d"
                + "\u62e6\u3002\u65e5\u5fd7\u641c\u00a7e\u300c\u8f7d\u5177\u7535\u91cf\u300d\u00a7r\u3002",
                "\u00a7e\u9ed8\u8ba4\u6863\uff08\u5979\u5f53\u524d\u6ca1\u6709\u4efb\u52a1\uff0c\u6216\u4efb\u52a1\u5c31\u662f"
                + "\u300c\u7a7a\u95f2\u300d\uff09\u2014\u2014\u8ddf\u7740\u4f60\u8d70\u00a7r\uff1a\u79bb\u4f60\u8d85\u8fc7\u00a7e"
                + "\u300c\u8ddf\u968f\u505c\u4e0b\u8ddd\u79bb\u300d\u00a7r\uff08\u9ed8\u8ba4 \u00a7e5 \u683c\u00a7r\uff0c\u53ef"
                + "\u8c03 1~16\uff09\u624d\u9a71\u52a8\u5750\u9a91\uff1b\u00a7e\u4e00\u8fdb\u8fd9\u4e2a\u8ddd\u79bb\u5c31\u505c"
                + "\u4e0b\u00a7r\uff0c\u5e76\u00a7e\u628a\u5750\u9a91\u7684\u5934\u8f6c\u5411\u4f60\u00a7r\u3002\u8fd9\u662f\u6700"
                + "\u5e38\u89c1\u7684\u60c5\u5f62\uff1a\u4f60\u8d70\u5979\u8ddf\u3001\u4f60\u505c\u5979\u4e5f\u505c\uff0c\u8138"
                + "\u671d\u7740\u4f60\u3002\n\n\u00a7e\u6709\u4efb\u52a1\u65f6\u2014\u2014\u8d70\u90a3\u4e2a\u4efb\u52a1\u7684"
                + "\u8def\u00a7r\uff1a\u5979\u63a5\u4e86\u6316\u77ff / \u4f10\u6728 / \u519c\u7530 / \u5efa\u9020 / \u6218\u6597"
                + "\u7b49\u4efb\u4f55\u4efb\u52a1\u65f6\uff0c\u00a7e\u90a3\u4e2a\u4efb\u52a1\u672c\u6765\u7684\u8d70\u4f4d\u610f"
                + "\u56fe\u539f\u6837\u8f6c\u8fbe\u7ed9\u5750\u9a91\u00a7r\uff08\u5c31\u662f\u628a\u300c\u5979\u8d70\u300d\u6362"
                + "\u6210\u300c\u5750\u9a91\u8d70\u300d\uff09\u2014\u2014\u00a7e\u8fd1\u6218 / \u8fdc\u7a0b\u63a5\u654c\u65f6\u4e5f"
                + "\u8d70\u8fd9\u4e00\u6863\u00a7r\uff0c\u7ed5\u5708 / \u62c9\u5f00\u8fd9\u4e9b\u63a5\u654c\u8d70\u4f4d\u7167\u5e38"
                + "\u4fdd\u7559\u3002",
                "\u00a7e\u8ddf\u968f\u6b8b\u7559\u4f1a\u88ab\u5254\u9664\u00a7r\uff1a\u8ddf\u968f\u884c\u4e3a\u00a7e\u59cb\u7ec8"
                + "\u5728\u8dd1\u00a7r\uff0c\u79bb\u4f60 62~66 \u683c\u65f6\u5b83\u4f1a\u628a\u00a7e\u300c\u671d\u4f60\u8d70\u300d"
                + "\u00a7r\u5199\u8fdb\u8d70\u4f4d\u8bb0\u5fc6\uff1b\u8fd9\u4e00\u6863\u53ea\u8ba4\u00a7e\u4efb\u52a1\u8fd9\u4e00"
                + "\u62cd\u771f\u6709\u76ee\u6807\u00a7r\u7684\u8d70\u4f4d\uff0c\u8d70\u4f4d\u70b9/\u8d70\u4f4d\u8bb0\u5fc6\u843d"
                + "\u5728\u00a7e\u4f60\u8eab\u4e0a\u00a7r\uff081.5 \u683c\u5185\uff09\u5c31\u4e0d\u7b97\u300c\u4efb\u52a1\u8981"
                + "\u53bb\u7684\u5730\u65b9\u300d\uff0c\u00a7e\u9000\u56de\u8ddf\u7740\u4f60\u8d70\u00a7r\u3002\n\u00a7e\u5176"
                + "\u4f59\u4e00\u5f8b\u8ddf\u7740\u4f60\u8d70\u00a7r\uff1a\u00a7e\u7a7a\u95f2\uff08\u6ca1\u4efb\u52a1\uff09\u00a7r"
                + "\u3001\u6216\u00a7e\u6709\u4efb\u52a1\u4f46\u8fd9\u4e00\u62cd\u6ca1\u6709\u5bf9\u5e94\u76ee\u6807\u00a7r\uff08"
                + "\u7ad9\u7740\u79cd\u5730\u3001\u519c\u7530\u6682\u65f6\u6ca1\u6d3b\u3001\u63a5\u654c\u8d70\u4f4d\u7684\u95f4"
                + "\u9699\uff09\u2192 \u90fd\u00a7e\u8ddf\u7740\u4f60\u8d70\u00a7r\uff0c\u591f\u8fd1\u5c31\u505c\u3001\u9a6c\u5934"
                + "\u8f6c\u5411\u4f60\uff1b\u53ea\u6709\u00a7e\u4efb\u52a1\u771f\u7ed9\u51fa\u76ee\u6807\u00a7r\u65f6\u624d\u8d70"
                + "\u4efb\u52a1\u81ea\u5df1\u7684\u8def\u3002\n\u00a7e\u63a5\u654c\u65f6\u4e00\u5f8b\u4e0d\u770b\u8ddd\u79bb\u00a7r"
                + "\uff1a\u5979\u6709\u00a7e\u6d3b\u7684\u653b\u51fb\u76ee\u6807\u00a7r\u65f6\uff0c\u8fc2\u56de\u8d70\u4f4d\uff08"
                + "\u7ed5\u5708 / \u86c7\u5f62 / \u6253\u4e00\u5200\u9000\u4e00\u6b65\uff09\u539f\u6837\u8f6c\u8fbe\u7ed9\u5750"
                + "\u9a91\uff1b\u90a3\u9053\u300c\u843d\u5728\u4f60 1.5 \u683c\u5185\u5c31\u5f53\u8ddf\u968f\u300d\u7684\u7b5b"
                + "\u5b50\u00a7e\u53ea\u5728\u5e73\u65f6\u751f\u6548\u00a7r\u3002\n\n\u00a7e\u3010\u8f6e\u6905\u7684\u8f6c\u5411"
                + "\u00a7r\u3011\u8f6e\u6905\u5f15\u64ce\u53ea\u8ba4",
                "\u00a7e\u300c\u7b2c\u4e00\u4f4d\u4e58\u5ba2\u7684\u5934\u671d\u5411 \u2212 \u8f66\u8eab\u671d\u5411\u300d\u00a7r"
                + "\u90a3\u4e2a\u5dee\u503c\uff08\u4e0d\u8bfb\u5de6\u53f3\u952e\uff09\uff1a\u76f4\u5199\u8f66\u8eab\u671d\u5411"
                + "\u65f6\n\u00a7e\u540c\u65f6\u5199\u5b83\u7684\u670d\u52a1\u7aef\u671d\u5411\u00a7r\uff0c\u5e76\u6309\u8f6e\u5f0f"
                + "/\u5c65\u5e26\u90a3\u53f0\u300c\u76f4\u5199\u673a\u5934\u300d\u7684\u5199\u6cd5\u8865\u4e0a\n\u00a7e\u89d2\u5ea6"
                + "\u56de\u7ed5\u00a7r\uff0c\u5750\u4e0a\u5c31\u80fd\u6b63\u5e38\u8f6c\u5411\u3002",
                "\u00a7e坐骑自己的随机溜达会被压住\u00a7r（只要背上坐着的是本模组有主的女仆），免得它一边听指挥、一边自己乱走抢方向；原版玩家的马、别人的坐骑一个字都不动。\n"
                        + "\u00a7e速度\u00a7r：坐骑速度与女仆速度取\u00a7e最大值\u00a7r，再乘一个可调的总倍率（默认 1.0）——不会比你们俩任何一方更慢。\n"
                        + "\u00a7e她骑着的时候照常战斗\u00a7r——战斗 / 自保 / 落地水等链路一条都没改。",
                "\u00a7e五、别叠罗汉：多只女仆骑坐骑也不挤在一起\u00a7r",
                "\u00a7e与扫帚模式同一套标准\u00a7r（两边共用同一份间距与算式，不是各写一套）。\n"
                        + "\u00a7e做法\u00a7r：坐骑要去的那个点在\u00a7e「别的女仆正骑着的坐骑」附近\u00a7r时，\u00a7e把目标点朝远离同伴的方向推出去一点\u00a7r"
                        + "——只推水平方向、且\u00a7e有上限\u00a7r（最多挪 1.5 格），只做微调、绝不改「她本来要去哪」。\n"
                        + "\u00a7e平时的最小间距 2 格\u00a7r（别撞在一起的观感下限）；\u00a7e接敌时放宽到 4 格\u00a7r——敌人一箭穿过前面那只还会打到后面那只，"
                        + "拉开才是活路。\n"
                        + "\u00a7e只在默认档（跟着你走）生效\u00a7r：她接了任务时目标点是那个任务真正要去的地方，推偏等于让工作走位失真，所以那一档不推。\n"
                        + "\u00a7e空着的坐骑不算\u00a7r：它正是她要去骑的目标，不算「别人挡路」；\u00a7e你自己骑的那匹也不算\u00a7r。",
                "\u00a7e六、模组载具与龙\u00a7r",
                "\u00a7e\u5f00\u5173\u00a7r\uff1a\u9762\u677f\u00a7e\u300c\u79fb\u52a8\u4e0e\u884c\u4e3a \u2192 \u9a91\u4e58"
                + "\u6307\u6325\u68d2\u300d\u00a7r\u4e0b\u7684\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u517c\u5bb9\u300d\u00a7r"
                + "\u4e0e\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u4ee3\u5979\u5f00\u706b\u300d\u00a7r\uff08\u90fd\u9ed8\u8ba4"
                + "\u5f00\uff09\u3002\n\n\u00a7e\u5353\u8d8a\u524d\u7ebf\u7684\u8f7d\u5177\u00a7r\uff08\u5766\u514b / \u88c5\u7532"
                + "\u8f66 / \u76f4\u5347\u673a / \u56fa\u5b9a\u7ffc / \u98de\u8247\u2026\uff09\uff1a\u5979\u5750\u5728\u00a7e\u9a7e"
                + "\u9a76\u4f4d\uff08\u5ea7\u4f4d 0\uff09\u00a7r\u5c31\u80fd\u5f00\u2014\u2014\u5f15\u64ce\u8ba4\u300c\u7b2c\u4e00"
                + "\u4e58\u5ba2\u300d\uff0c\u4e0d\u8981\u6c42\u662f\u73a9\u5bb6\uff0c\u6240\u4ee5\u00a7e\u522b\u81ea\u5df1\u5360"
                + "\u9a7e\u9a76\u4f4d\u00a7r\uff08\u5360\u4e86\u6a21\u7ec4\u4f1a\u81ea\u52a8\u628a\u5979\u632a\u56de\u5ea7\u4f4d 0"
                + "\uff09\u3002\n\n\u00a7e\u4ee3\u5979\u5f00\u706b\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5353\u8d8a\u524d"
                + "\u7ebf\u7684\u8f7d\u5177\u652f\u6301\u300c\u4e58\u5ba2\u662f\u751f\u7269\u3001\u6709\u81ea\u5df1\u7684\u76ee"
                + "\u6807\u5c31\u81ea\u52a8\u5f00\u706b\u300d\uff0c\u5973\u4ec6\u5750\u8fdb\u6b66\u5668\u4f4d\u5c31\u4f1a\u66ff"
                + "\u4f60\u6253\u3002\u5173\u6389\u8fd9\u4e00\u9879 = \u5979\u7167\u5e38\u5f00\uff0c\u4f46\u8f7d\u5177\u4e0d\u5f00"
                + "\u706b\uff08\u4f60\u81ea\u5df1\u5f00\uff09\u3002\u5979\u628a\u76ee\u6807\u540c\u65f6\u5199\u8fdb\n\u00a7e\u70ae"
                + "\u5854\u4e0e\u6b66\u5668\u4f4d\u7684 AI \u76ee\u6807\u00a7r\uff0c\u7528\u8f7d\u5177\n\u00a7e\u81ea\u5df1\u7684"
                + "\u70ae\u5f39\u00a7r\u6253\uff1b\u5979\u80cc\u5305\u91cc\u5bf9\u5f97\u4e0a\u7684\u5b50\u5f39\u4f1a\n\u00a7e\u642c"
                + "\u8fdb\u8f7d\u5177\u7684\u5f39\u836f\u5bb9\u5668\u00a7r\uff08\u6bcf 0.5 \u79d2\u68c0\u67e5\u4e00\u6b21\u3001"
                + "\u6309\u9700\u642c\uff09\u2014\u2014",
                "\u00a7e\u8f66\u4e0a\u4e00\u70b9\u5f39\u90fd\u6ca1\u6709\u65f6\u8c01\u90fd\u6253\u4e0d\u54cd\u00a7r\u3002\n\n"
                + "\u00a7e\u88c5\u586b\u00a7r\u8ba4\u5f97\n\u00a7e\u6563\u88c5\u5f39\u00a7r\uff08\u300c\u6b65\u67aa\u5f39\u836f"
                + "\u300d\u672c\u8eab\u8fd9\u79cd\uff09\u3001\n\u00a7e\u76d2\u88c5\u5f39\u00a7r\uff08\u76d2\u88c5\u6b65\u67aa\u5f39"
                + "\u836f / \u76d2\u88c5\u624b\u67aa\u5f39\u836f\u2026\u81ea\u5e26\u578b\u53f7\u7684\u90a3\u4e9b\uff09\u4e0e\n"
                + "\u00a7e\u901a\u7528\u300c\u5f39\u836f\u76d2\u300d\u00a7r\uff08\u5f39\u836f\u5b58\u5728\u76d2\u5b50\u91cc\u90a3"
                + "\u79cd\uff0c\u6309\u76d2\u5185\u578b\u53f7\u4e0e\u5b58\u91cf\u5224\uff09\uff0c\u90fd\u4f1a\u642c\u8fdb\u8f66"
                + "\u5bb9\u5668\uff1b\u642c\u8fdb\u53bb\u4e4b\u540e\u7531\u5353\u8d8a\u524d\u7ebf\u81ea\u5df1\u8ba1\u6570\u3001"
                + "\u81ea\u5df1\u6d88\u8017\uff0c\u7528\u591a\u5c11\u6263\u591a\u5c11\u3001\u76d2\u5b50\u91cc\u5269\u7684\u8fd8"
                + "\u5728\u3002\n\n\u00a7e\u591a\u6839\u70ae\u7ba1\u4e00\u8d77\u6253\u00a7r\uff1a\n\u00a7e\u9010\u5ea7\u9010\u95e8"
                + "\u00a7r\u628a\u8f66\u4e0a\u6bcf\u4e00\u95e8\u70ae\u90fd\u5217\u51fa\u6765\uff08\u4f60\u81ea\u5df1\u5750\u7740"
                + "\u7684\u90a3\u4e00\u5ea7\u6574\u5ea7\u8ba9\u5f00\uff09\uff0c\u8c01\u6709\u5f39\u3001\u8c01\u80fd\u6253\u8c01"
                + "\u5c31\u4e00\u8d77\u6253\u2014\u2014M1A2 \u7684 120mm \u4e3b\u70ae\u4e0e\u5e76\u5217\u673a\u67aa\u4f1a\n\u00a7e"
                + "\u540c\u65f6\u54cd\u00a7r\uff0c\u70ae\u8247\u7684\u4e09\u95e8\u70ae\u4e5f\u5404\u6253\u5404\u7684\u3002",
                "\u00a7e\u5c04\u901f\u6309\u5404\u70ae\u81ea\u5df1\u7684 RPM\u00a7r\uff1a\u95f4\u9694 = 20 \u00f7 (RPM \u00f7 60)"
                + " \u62cd\u2014\u2014\u8f66\u8f7d\u673a\u67aa 600 RPM = 10 \u53d1/\u79d2\u3001M61 \u673a\u70ae 1200 RPM = 20 "
                + "\u53d1/\u79d2\uff0c\u4e3b\u70ae\u4ecd\u53d7\u5b83\u81ea\u5df1\u7684\u88c5\u586b\u65f6\u95f4\u7ea6\u675f\u3002"
                + "\u8fd9\u6761\u4e0e\n\u00a7e\u5973\u4ec6\u7684\u6b66\u5668\u6a21\u5f0f\u65e0\u5173\u00a7r\u2014\u2014\u4efb\u4f55"
                + "\u6a21\u5f0f\u4e0b\u90fd\u6309\u6b66\u5668\u8be5\u6709\u7684\u901f\u5ea6\u6253\u3002\n\n\u00a7e\u5c04\u901f"
                + "\u6309\u70ae\u81ea\u5df1\u7684\u5f39\u5323\u5faa\u73af\u00a7r\uff1a\u4e00\u5323 N \u53d1\u3001\u88c5\u6ee1\u4e00"
                + "\u5323\u8981 T \u62cd \u21d2 \u5b83\u81ea\u5df1\u8bbe\u8ba1\u7684\u6301\u7eed\u5c04\u901f\u5c31\u662f\n\u00a7e"
                + "\u6bcf T\u00f7N \u62cd\u4e00\u53d1\u00a7r\uff08\u4e3b\u70ae = 100\u00f71 = 100 \u62cd = \u00a7e5 \u79d2\u00a7r"
                + "\uff09\uff0c\u4e0e RPM \u90a3\u4e00\u9053\u00a7e\u53d6\u6162\u7684\u00a7r\u3002\u5e76\u5217\u673a\u67aa\uff08RPM"
                + " 600\uff09\u4ecd\u662f 2 \u62cd\u3001Bofors\uff08RPM 180 + 12 \u53d1\u5f39\u5323\uff09\u4ecd\u7531 RPM \u8bf4"
                + "\u4e86\u7b97\u3002",
                "\u00a7e\u6295\u5f39\u00a7r\u4e24\u53d1\u4e4b\u95f4\u81f3\u5c11\u9694\u00a7e2 \u79d2\u00a7r\uff08\u5e76\u4fdd"
                + "\u7559\u300c\u5148\u722c\u5230\u76ee\u6807\u4e0a 20 \u683c\u518d\u6295\u300d\u7684\u5b89\u5168\u9ad8\u5ea6\u95f8"
                + "\uff09\uff0c\u98de\u673a\u4f1a\u5148\u98de\u79bb\u4e0a\u4e00\u53d1\u7684\u843d\u70b9\u3002\u57fa\u6d1b\u592b"
                + "\u7684\u70b8\u5f39\u5f39\u5323 7 \u53d1\u3001\u7206\u70b8\u534a\u5f84 42 \u683c\uff0c\u800c\u98de\u8239\u81ea"
                + "\u5df1\u6328\u822a\u7a7a\u70b8\u5f39\u662f\u00a7e 3 \u500d\u4f24\u5bb3\u00a7r\uff0c\u6240\u4ee5\u8fd9\u6761"
                + "\u95f4\u9694\u5f88\u6709\u5fc5\u8981\u3002\n\u00a7e\u4e3b\u70ae\u7684\u5f39\u79cd\u662f\u4e00\u5f20\u8868\uff08"
                + "\u7a7f\u7532 / \u9ad8\u7206 / \u9730\u5f39\uff09\u00a7r\uff1a\u88c5\u586b\u6309\u00a7e\u8fd9\u95e8\u70ae\u7684"
                + "\u5168\u90e8\u5f39\u79cd\u00a7r\u8bc6\u522b\uff0c\u6253\u4e0d\u54cd\u65f6\u8fd8\u4f1a\u5728\u540c\u4e00\u95e8"
                + "\u70ae\u7684\u5f39\u79cd\u8868\u91cc\u00a7e\u6362\u4e00\u4e2a\u6709\u5f39\u7684\u5f39\u79cd\u00a7r\u518d\u88c5"
                + "\u586b\uff1b\u5f7b\u5e95\u6ca1\u5f39\u65f6\u65e5\u5fd7\u5199\u4e00\u884c\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91"
                + "\u00b7\u7f3a\u5f39\u300d\u00a7r\uff08\u641c\u5b83\u5c31\u80fd\u770b\u51fa\u662f\u7f3a\u5f39\u8fd8\u662f\u522b"
                + "\u7684\u539f\u56e0\uff09\u3002\n\u00a7e\u6295\u5f39\u5b89\u5168\u9ad8\u5ea6 = \u6700\u5927(\u914d\u7f6e\u503c, "
                + "\u8be5\u70b8\u5f39\u7684\u7206\u70b8\u534a\u5f84 + 6)\u00a7r\u2014\u2014\u56fa\u5b9a 20 \u683c\u662f\u00a7e"
                + "\u4ece\u76ee\u6807\u7b97\u00a7r\u7684\uff0c\u800c\u57fa\u6d1b\u592b\u90a3\u9897\u822a\u7a7a\u70b8\u5f39\u7206"
                + "\u70b8\u534a\u5f84 \u00a7e42\u00a7r \u683c\uff0c\u7b49\u4e8e\u7ad9\u5728\u7206\u5fc3\u9876\u4e0a\uff0c\u914d"
                + "\u7f6e\u9879\u5728\u8fd9\u91cc\u662f\u300c\u4e0b\u9650\u300d\u3002",
                "\u00a7e\u56db\u67b6\u56fa\u5b9a\u7ffc\uff08Ju-87 / A-10 / AC-130H / KV-16\uff09\u00a7r\u53ef\u7ed1\uff0c\u8d70"
                + "\u00a7e\u5b9a\u5236\u8d77\u98de\u94fe\u8def\u00a7r\uff1a\u843d\u5730\u5f85\u98de\u65f6\u5148\u516b\u5411\u626b"
                + "\u52a9\u8dd1\u9053\uff08\u00a728\u00d79 \u683c\u3001\u843d\u5dee \u2264 6 \u683c\u00a7r\uff09\uff0c\u4e00\u6761"
                + "\u90fd\u4e0d\u5408\u683c\u5c31\u53d1\u4e00\u53e5\u00a7e\u300c\u73af\u5883\u4e0d\u5141\u8bb8\u8d77\u98de\u300d"
                + "\u00a7r\u5e76\u9489\u5728\u539f\u5730\uff08\u4e0d\u786c\u62d4\u3001\u4e0d\u6ed1\u8dd1\uff09\uff1b\u5408\u683c"
                + "\u5c31\u671d\u6700\u5e73\u90a3\u6761\u00a7e\u6ed1\u8dd1\u52a0\u901f\u00a7r\uff0c\u901f\u5ea6\u591f\u4e86\u624d"
                + "\u00a7e\u62ac\u673a\u5934\u79bb\u5730\u00a7r\uff0c\u4e4b\u540e\u4ea4\u7ed9\u5f15\u64ce\u76d8\u65cb\uff08\u5706"
                + "\u5fc3 = \u4e3b\u4eba / \u654c\u4eba\uff09\u5e76\u7167\u5e38\u5f00\u706b\u3002\u6c64\u59c6 F6F / \u8ff7\u4f60"
                + "\u5feb\u8247\u4ecd\u4e0d\u5f00\uff08\u5f15\u64ce\u91cc\u53ea\u8ba4\u73a9\u5bb6\uff09\u3002\n\u00a7e\u8f7d\u5177"
                + "\u907f\u9669\u00a7r\uff08\u4e0e\u626b\u5e1a\u540c\u4e00\u5957\u4e09\u6761\u89c4\u5219\uff09\uff1a\u00a7e\u4e0d"
                + "\u8d34\u5730\u00a7r\uff08\u79bb\u5730\u4e0d\u8db3 3 \u683c\u5c31\u62ac\u5230\u51c0\u7a7a\u7ebf\uff09\u3001\u00a7"
                + "e\u4e0d\u649e\u5899 / \u4e0d\u94bb\u4e00\u683c\u00a7r\uff08\u524d\u65b9 8 \u683c\u3001\u673a\u8eab\u9ad8\u5ea6"
                + "\u8d77\u4e09\u5c42\u6709\u65b9\u5757\u5c31\u62ac\u9ad8 6 \u683c\u4ece\u9876\u4e0a\u8fc7\uff09\u3002\u65e5\u5fd7"
                + "\u641c\u00a7e\u300c\u8f7d\u5177\u907f\u9669\u300d\u00a7r\u3002",
                "\u00a7e\u521b\u9020\u6a21\u5f0f\u5f39\u836f\u76d2\u00a7r\uff1a\u00a7e\u8f66\u91cc\u653e\u7740\u521b\u9020\u6a21"
                + "\u5f0f\u5f39\u836f\u76d2 = \u5168\u8f66\u65e0\u9650\u5f39\u00a7r\uff08\u5353\u8d8a\u524d\u7ebf\u7684\u88c5\u586b"
                + "\u8ba1\u6570\u76f4\u63a5\u8fd4\u56de\u6700\u5927\u503c\u3001\u6d88\u8017\u76f4\u63a5\u8df3\u8fc7\uff09\u3002"
                + "\u5979\u4e5f\u4f1a\u628a\u00a7e\u521b\u9020\u76d2\u5f53\u6210\u5f39\u4e00\u6837\u642c\u8fdb\u8f66\u5bb9\u5668"
                + "\u00a7r\u2014\u2014\u642c\u8fdb\u53bb\u90a3\u4e00\u523b\u8d77\uff0c\u4e3b\u70ae / \u673a\u67aa / \u673a\u70ae"
                + "\u5c31\u90fd\u4e0d\u7f3a\u5f39\u4e86\u3002\u65e5\u5fd7\u641c\u00a7e\u300c\u521b\u9020\u5f39\u836f\u76d2\u300d"
                + "\u00a7r\u3002\u8f66\u91cc\u6709\u521b\u9020\u76d2\u65f6\uff0c\u5979\u6bcf\u8f6e\u5f00\u706b\u524d\u4f1a\u00a7e"
                + "\u628a\u6709\u5f39\u5323\u7684\u70ae\uff08\u5766\u514b\u4e3b\u70ae / \u5e76\u5217\u673a\u67aa\uff09\u7684\u5f39"
                + "\u5323\u6309\u5f15\u64ce\u7684\u65e0\u9650\u5f39\u8d26\u586b\u6ee1\u00a7r\uff08\u5f15\u64ce\u7684\u81ea\u52a8"
                + "\u88c5\u586b\u5bf9\u8f7d\u5177\u6b66\u5668\u9ed8\u8ba4\u5173\u7740\uff0c\u8f66\u4e0a\u6ca1\u4eba\u66ff\u5b83"
                + "\u6309\u88c5\u586b\u952e\uff09\uff0c\u6d88\u8017\u7167\u65e7\u7531\u70ae\u81ea\u5df1\u6263\u3002\u65e5\u5fd7"
                + "\u641c\u00a7e\u300c\u65e0\u9650\u5f39\u88c5\u586b\u300d\u00a7r\u3002",
                "\u00a7e\u521b\u9020\u5f39\u836f\u76d2 = \u5f3a\u5236\u5141\u8bb8\u5f00\u70ae\u00a7r\uff1a\u00a7e\u4e00\u68c0"
                + "\u6d4b\u5230\u521b\u9020\u5f39\u836f\u76d2\uff0c\u5c31\u628a\u8fd9\u4e00\u95e8\u70ae\u6309\u5230\u80fd\u5f00"
                + "\u706b\u00a7r\u2014\u2014\u5f39\u5323\u4e0e\u540e\u5907\u5f39\u5199\u8db3\u3001\u6e05\u6389\u00a7e\u88c5\u586b"
                + "\u4e2d / \u62c9\u6813\u4e2d / \u84c4\u529b\u4e2d / \u8fc7\u70ed\u00a7r\u56db\u9053\u95f8\u3001\u8fc7\u70ed\u5ea6"
                + "\u5f52\u96f6\uff0c\u5e76\u8df3\u8fc7\u300c\u67e5\u5f39\u79cd / \u6362\u70ae / \u62a5\u7f3a\u5f39\u300d\u7684"
                + "\u5ba1\u67e5\uff08\u8f7d\u5177\u6b66\u5668\u8d70\u7684\u662f\u5f15\u64ce\u81ea\u5df1\u91cd\u5199\u8fc7\u7684 can"
                + "Shoot\uff0c\u6700\u540e\u4e00\u9053\u662f\u00a7e\u300c\u8f66\u4fa7\u5f39\u91cf\u300d\u00a7r\uff0c\u65e0\u5f39"
                + "\u5323\u6b66\u5668\u8bfb\u7684\u662f\u540e\u5907\u5f39\u7684\u663e\u793a\u503c\uff09\u3002\u65e5\u5fd7\u641c"
                + "\u00a7e\u300c\u65e0\u9650\u5f39\u5f00\u70ae\u300d\u00a7r\uff1b\u4e07\u4e00\u8fd8\u6709\u4e00\u9053\u6ca1\u6599"
                + "\u5230\u7684\u95f8\uff0c\u4f1a\u6253\u4e00\u6761\u00a7e\u300c\u65e0\u9650\u5f39\u53d7\u963b\u300d\u00a7r\u628a"
                + "\u6bcf\u9053\u95f8\u7684\u8bfb\u6570\u90fd\u5e26\u51fa\u6765\u3002",
                "\u00a7e\u76f4\u7784\u5f00\u706b\u00a7r\uff08\u4e0e\u5973\u4ec6\u67aa\u68b0\u6a21\u5f0f\u540c\u4e00\u5957\u7784"
                + "\u51c6\uff09\uff1a\u00a7e\u5f00\u706b\u90a3\u4e00\u523b\u00a7r\u628a\u00a7e\u5f39\u9053\u89e3\u7b97\u51fa\u6765"
                + "\u7684\u65b9\u5411\u00a7r\uff08\u5f15\u64ce\u81ea\u5df1\u7684 calculateFiringSolution\uff1a\u91cd\u529b\u4e0b"
                + "\u5760 + \u63d0\u524d\u91cf\uff09\u00a7e\u76f4\u63a5\u4ea4\u7ed9\u70ae\u00a7r\uff08GunData.shoot\uff09\uff0c"
                + "\u00a7e\u4e0d\u518d\u7b49\u70ae\u5854\u6162\u6162\u8f6c\u8fc7\u53bb\u00a7r\uff1b\u5f39\u836f / \u51b7\u5374 / "
                + "\u8fc7\u70ed / \u97f3\u6548 / \u540e\u5750\u7167\u65e7\u7531\u6b66\u5668\u81ea\u5df1\u90a3\u6761\u94fe\u5904"
                + "\u7406\u3002\u00a7e\u6295\u5f39\uff08\u822a\u7a7a\u70b8\u5f39\uff09\u00a7r\u4ecd\u8d70\u90a3\u6761\u6295\u5f39"
                + "\u94fe\u8def\u3002\n\u00a7e\u4f60\u5750\u8fdb\u9a7e\u9a76\u4f4d\uff0c\u5979\u5c31\u4ea4\u8fd8\u65b9\u5411\u76d8"
                + "\u00a7r\uff1a\u5de6\u51fb\u6362\u5ea7\u628a\u4f60\u6362\u5230 0 \u53f7\uff08\u9a7e\u9a76\uff09\u5ea7\u540e\uff0c"
                + "\u5353\u8d8a\u524d\u7ebf\u7684\u5f15\u64ce\u53ea\u8ba4\u300c\u7b2c\u4e00\u4f4d\u4e58\u5ba2\u300d\uff0c\u6240"
                + "\u4ee5\u00a7e\u65b9\u5411\u76d8\u5f52\u4f60\u00a7r\u2014\u2014\u6a21\u7ec4\u4f1a\u628a\u6b8b\u7559\u7684\u81ea"
                + "\u52a8\u8f93\u5165\u6e05\u4e00\u4e0b\u3001\u6b64\u540e\u00a7e\u4e00\u4e2a\u5b57\u90fd\u4e0d\u518d\u5199\u9a7e"
                + "\u9a76\u00a7r\uff08\u6b66\u5668\u4e0e\u88c5\u5f39\u7167\u5e38\uff09\u3002\u4f60\u6362\u56de\u526f\u9a7e\u3001"
                + "\u6216\u5979\u6362\u56de\u9a7e\u9a76\u4f4d\uff0c\u5979\u53c8\u4f1a\u63a5\u7740\u5f00\u3002",
                "\u00a7e\u5bfc\u5f39\u4e0e\u6295\u63b7 TNT \u540c\u4e00\u6761\u94fe\u8def\u00a7r\uff1a\u63a5\u7ba1\u540e\u00a7e"
                + "\u53ea\u5728\u524d 0.2 \u79d2\u00a7r\u628a\u5979\u654c\u4eba\u63b0\u7ed9\u5b83\uff0c\u4e4b\u540e\u7acb\u523b"
                + "\u6492\u624b\u3001\u00a7e\u5b8c\u5168\u4ea4\u8fd8\u5b83\u81ea\u5df1\u7684\u672b\u7aef\u5236\u5bfc\u00a7r\u2014"
                + "\u2014\u65e2\u4e0d\u4e00\u76f4\u76ef\u7740\u654c\u4eba\u76f4\u51b2\uff08\u90a3\u4f1a\u5931\u53bb\u672b\u7aef"
                + "\u673a\u52a8\uff09\uff0c\u4e5f\u4e0d\u4f1a\u4e00\u79bb\u67b6\u5c31\u671d\u522b\u5904\u62d0\u3002\u666e\u901a"
                + "\u70ae\u5f39\u7167\u65e7\u7ea0\u5411\u7ea6 3 \u79d2\u3002\n\n\u00a7e\u98de\u884c\u8f7d\u5177\u00a7r\u53e6\u6709"
                + "\u4e00\u5957\u98de\u6cd5\uff08\u9762\u677f\u00a7e\u300c\u9a91\u98de\u884c\u8f7d\u5177\u00b7\u60ac\u505c\u4e0e"
                + "\u76d8\u65cb\u300d\u00a7r\uff09\uff1a\u76f4\u5347\u673a\u822a\u5411 / \u4fef\u4ef0\u8d70\u9f20\u6807\u901a\u9053"
                + "\u3001\u9ad8\u5ea6\u8d70\u603b\u8ddd\uff1b\u56fa\u5b9a\u7ffc\u6ca1\u6709\u7ad6\u76f4\u8f74\uff0c\u6539\u7528"
                + "\u5f15\u64ce\u81ea\u5e26\u7684\u76d8\u65cb\uff08loiter\uff09\uff0c\u4e0d\u4f1a\u60ac\u505c\uff1b\u98de\u8247"
                + "\u63a5\u654c\u65f6\u4f1a\u81ea\u5df1\u5347\u5230\u654c\u4eba\u4e0a\u65b9\u3002\u5979\u8ddf\u7740\u4f60\u65f6"
                + "\u6309\u00a7e\u300c\u60ac\u505c\u9ad8\u5ea6\u300d\u00a7r\u60ac\u505c\uff0c\u63a5\u654c\u65f6\u5347\u5230\u00a7e"
                + "\u300c\u63a5\u654c\u9ad8\u5ea6\u300d\u00a7r\u5e76\u7ed5\u7740\u654c\u4eba\u6253\uff08\u534a\u5f84\u00a7e\u300c"
                + "\u76d8\u65cb\u534a\u5f84\u300d\u00a7r\uff09\u3002",
                "\u00a7e\u901a\u7528\u653b\u51fb\u6863\uff08\u5176\u4ed6\u6a21\u7ec4\u7684\u5750\u9a91\uff09\u00a7r\uff1a\u4efb"
                + "\u4f55\u300c\u7528\u6b63\u5e38\u4f18\u5148\u7ea7\u5224\u5b9a\u300d\u7684\u53ef\u9a91\u4e58\u751f\u7269\uff0c"
                + "\u5ea7\u4e0a\u5979\u4e4b\u540e\u90fd\u4f1a\u65e0\u6761\u4ef6\u670d\u4ece\u5979\u7684\u653b\u51fb\u76ee\u6807"
                + "\u2014\u2014\u7784\u51c6 / \u63a5\u8fd1 / \u5f00\u706b\u5168\u7528\u5750\u9a91\u81ea\u5df1\u90a3\u5957\u3002\n\n"
                + "\u00a7e\u51b0\u706b\u4f20\u8bf4\u7684\u9f99\uff08\u53ef\u4ee5\u6302\u4e0a\u53bb\uff0c\u4f46\u4e0d\u5efa\u8bae"
                + "\uff09\u00a7r\uff1a\u9f99\u53ef\u4ee5\u7ed1\uff0c\u5973\u4ec6\u4f1a\u88ab\u6446\u5230\u00a7e\u9f99\u7ed9\u73a9"
                + "\u5bb6\u7684\u90a3\u4e2a\u978d\u4f4d\u00a7r\u4e0a\uff08\u5979\u4e0d\u662f\u4e58\u5ba2\uff0c\u9f99\u7684\u884c"
                + "\u52a8\u8f6c\u6210\u8ddf\u968f\u4f60\uff0c\u4f20\u9001\u53ea\u4f20\u5979\u4e0d\u4f20\u9f99\uff09\u3002\u4f46"
                + "\u00a7e\u89c2\u611f\u4e0a\u5341\u5206\u8fdd\u548c\u00a7r\u2014\u2014\u6446\u4f4d\u9760\u516c\u5f0f\u786c\u7b97"
                + "\uff0c\u98de\u8d77\u6765\u3001\u8f6c\u8eab\u65f6\u80fd\u770b\u51fa\u660e\u663e\u7684\u9519\u4f4d\u4e0e\u4e0d"
                + "\u81ea\u7136\uff0c\u6240\u4ee5\u00a7e\u4e0d\u63a8\u8350\u5927\u5bb6\u8fd9\u4e48\u505a\u00a7r\u3002\u5979\u6ca1"
                + "\u6cd5\u771f\u6b63\u4e58\u5750\u5728\u9f99\u4e0a\u3001\u76f4\u63a5\u64cd\u7eb5\u5b83\uff0c\u53ea\u80fd\u8fd9"
                + "\u6837\u300c\u6302\u5728\u978d\u4f4d\u4e0a\u300d\u3002",
                "\u00a7e七、固定翼也能开了（另两台她不开）\u00a7r",
                "\u00a7e\u56db\u67b6\u56fa\u5b9a\u7ffc\u53ef\u7528\u9a91\u4e58\u6307\u6325\u68d2\u7ed1\u5b9a\u00a7r\uff1a\u00a7eJ"
                + "u-87 \u65af\u56fe\u5361\u8f70\u70b8\u673a\u00a7r\u3001\u00a7eA-10 \u96f7\u7535\u4e8c\u653b\u51fb\u673a\u00a7r"
                + "\u3001\u00a7eAC-130H \u7a7a\u4e2d\u70ae\u8247\u00a7r\u3001\u00a7eKV-16 \u5e7d\u7075\u6218\u6597\u673a\u00a7r"
                + "\u3002\u5979\u4eec\u8d70\u7684\u662f\u00a7e\u5b9a\u5236\u8d77\u98de\u94fe\u8def\u00a7r\uff1a\n\u00a7e\u2460 "
                + "\u9a8c\u5e73\u5730\u00a7r\uff1a\u843d\u5730\u5f85\u98de\u65f6\u5148\u5411\u516b\u4e2a\u65b9\u5411\u5404\u626b"
                + "\u4e00\u6761\u00a728\u00d79 \u683c\u00a7r\u7684\u52a9\u8dd1\u9053\uff0c\u770b\u5730\u9762\u843d\u5dee\uff1b"
                + "\u4e00\u6761\u90fd\u4e0d\u5408\u683c\uff08\u843d\u5dee > 6 \u683c\uff09\u5c31\u00a7e\u62a5\u300c\u73af\u5883"
                + "\u4e0d\u5141\u8bb8\u8d77\u98de\u300d\u00a7r\u5e76\u9489\u5728\u539f\u5730\u4e0d\u52a8\u3002\n\u00a7e\u2461 "
                + "\u6ed1\u8dd1\u00a7r\uff1a\u671d\u6700\u5e73\u7684\u90a3\u6761\u52a9\u8dd1\u9053\u52a0\u901f\uff08\u6ee1\u63a8"
                + "\u529b\u3001\u673a\u5934\u9501\u5728\u52a9\u8dd1\u65b9\u5411\uff09\u3002\n\u00a7e\u2462 \u62ac\u5934\u79bb\u5730"
                + "\u00a7r\uff1a\u901f\u5ea6\u591f\u4e86\u624d\u62ac\u673a\u5934\uff08\u00a7e25\u00b0\u00a7r\uff09\u8d77\u98de"
                + "\uff0c\u4e4b\u540e\u4ea4\u7ed9\u5f15\u64ce\u81ea\u5df1\u7684\u76d8\u65cb\uff08\u5706\u5fc3 = \u4e3b\u4eba / "
                + "\u654c\u4eba\uff09\uff0c\u00a7e\u6b66\u5668\u7167\u5e38\u5f00\u706b\u00a7r\u3002",
                "\u00a7e\u56fa\u5b9a\u7ffc\u8d77\u98de\u540e\u7684\u722c\u5347\u00a7r\uff1a\u5f15\u64ce\u81ea\u5df1\u7684\u76d8"
                + "\u65cb\uff08loiter\uff09\u8981\u00a7e\u540c\u65f6\u00a7r\u6ee1\u8db3\u300c\u5df2\u79bb\u5730 + \u5f15\u64ce"
                + "\u5df2\u70b9\u706b + \u00a7e\u7535\u91cf > 1024\u00a7r + \u76d8\u65cb\u5f00\u5173\u300d\u624d\u63a5\u7ba1\u3002"
                + "\u6240\u4ee5\u79bb\u5730\u540e\u5979\u5148\u8fdb\u5165\u00a7e\u722c\u5347\u7a97\u53e3\u00a7r\uff1a\u6bcf\u62cd"
                + "\u6309\u9ad8\u5dee\u76f4\u63a5\u7ed9\u722c\u5347\u7387\uff08\u62ac\u5934\u89d2 25\u00b0\uff09\uff0c\u00a7e\u722c"
                + "\u5230\u76ee\u6807\u9ad8\u5ea6 2 \u683c\u4ee5\u5185\u624d\u6492\u624b\u00a7r\u4ea4\u7ed9\u5f15\u64ce\uff1b\u82e5"
                + "\u00a7e\u7535\u91cf\u89c1\u5e95\u8fd8\u4f1a\u81ea\u52a8\u8865\u6ee1\u00a7r\uff08\u8f66\u7684\u7535\u91cf\u53ea"
                + "\u80fd\u9760\u5f80\u8f66\u91cc\u585e\u80fd\u91cf\u7269\u54c1\u5145\uff0c\u5973\u4ec6\u4e0d\u4f1a\u5145\u7535"
                + "\uff09\u3002\u65e5\u5fd7\u641c\u00a7e\u300c\u56fa\u5b9a\u7ffc\u722c\u5347\u300d/\u300c\u56fa\u5b9a\u7ffc\u8865"
                + "\u80fd\u300d\u00a7r\u3002\n\u00a7e\u56fa\u5b9a\u7ffc\u4e0d\u53c2\u4e0e\u300c\u5468\u671f\u6025\u505c\u300d\u00a7"
                + "r\uff1a\u90a3\u5957\u00a7e\u5468\u671f\u6025\u505c\u00a7r\u53ea\u7ed9\u60ac\u505c\u578b\u98de\u884c\u5668\uff08"
                + "\u76f4\u5347\u673a / \u98de\u8247\uff09\u9632\u6f02\u79fb\u7528\uff1b\u56fa\u5b9a\u7ffc\u7684\u00a7e\u5347\u529b"
                + "\u6b63\u6bd4\u4e8e\u901f\u5ea6\u00a7r\uff0c\u6bcf\u534a\u79d2\u62b9\u4e00\u6b21\u901f\u5ea6\u5c31\u7b49\u4e8e"
                + "\u62b9\u4e00\u6b21\u5347\u529b\uff0c\u6240\u4ee5\u56fa\u5b9a\u7ffc\u53ea\u4fdd\u7559\u9632\u8d85\u901f\u7684"
                + "\u4e0a\u9650\uff0c\u901f\u5ea6\u80fd\u4e00\u8def\u6512\u8d77\u6765\u2014\u2014\u8d77\u98de / \u76d8\u65cb / "
                + "\u722c\u5347\u624d\u7acb\u5f97\u4f4f\u3002\u65e5\u5fd7\u91cc\u90a3\u4e00\u6863\u4f1a\u5199\u00a7e\u300c\u6025"
                + "\u505c=\u653e\u5f00\u300d\u00a7r\u3002",
                "\u00a7e\u56fa\u5b9a\u7ffc\u7684\u8d77\u98de\u901f\u5ea6\u00a7r\uff1a\u5f15\u64ce\u7684\u5347\u529b\u9879\u662f"
                + "\u00a7e\u300c\u5347\u529b \u221d \u5f53\u524d\u901f\u5ea6\u300d\u00a7r\uff0c\u800c\u6bcf\u62cd\u91cd\u529b\u7ea6"
                + " 0.06\u2014\u2014\u4ee5 AC-130H \u7684\u53c2\u6570\u4e3a\u4f8b\uff0c\u00a7e\u901f\u5ea6 0.30 \u65f6\u5347\u529b"
                + "\u53ea\u6709 0.01/\u62cd\u30010.70 \u65f6\u4e5f\u53ea\u6709 0.02/\u62cd\u00a7r\uff0c\u90fd\u8fdc\u5c0f\u4e8e 0.0"
                + "6\uff0c\u901f\u5ea6\u4e0d\u591f\u5c31\u62ac\u673a\u5934\u7b49\u4e8e\u521a\u79bb\u5730\u5c31\u5f80\u4e0b\u6389"
                + "\u3002\u6240\u4ee5\uff1a\u00a7e\u8d77\u98de\u95e8\u69db 1.20\u00a7r\uff08\u52a9\u8dd1\u4e00\u76f4\u6ee1\u63a8"
                + "\u529b 3.0\u3001\u6302\u51b2\u523a\u4f4d\uff09\u3001\u00a7e\u76d8\u65cb / \u722c\u5347\u6863\u7ed9\u6cb9\u95e8"
                + "\u4e0b\u9650\uff081.8 / 3.0\uff09\u00a7r\u3001\u00a7e\u901f\u5ea6\u4e0a\u9650\u7528\u56fa\u5b9a\u7ffc\u81ea"
                + "\u5df1\u7684 2.60\u00a7r\u3002\u65e5\u5fd7\u90a3\u4e00\u6863\u4f1a\u591a\u5199\u4e00\u4e2a\u00a7e\u300c\u63a8"
                + "\u529b=\u300d\u00a7r\uff0c\u6ed1\u8dd1\u65e5\u5fd7\u4f1a\u5199\u00a7e\u300c\u6c34\u5e73\u901f\u5ea6=x/1.20\u300d"
                + "\u00a7r\u3002",
                "\u00a7e\u56fa\u5b9a\u7ffc\u5de1\u822a\u6863\u00a7r\uff1a\u5979\u00a7e\u81ea\u5df1\u7ba1\u56db\u4e2a\u73af\u00a7r"
                + "\u2014\u2014\u822a\u5411\u8d70\u9f20\u6807\u901a\u9053\u3001\u8f6c\u5f2f\u65f6\u76f4\u63a5\u628a\u6eda\u8f6c"
                + "\u89d2\u9876\u6ee1\uff0845\u00b0\uff09\u3001\u63a8\u529b\u53ea\u4fdd\u300c\u4e0d\u7184\u706b\u4e5f\u4e0d\u62d6"
                + "\u540e\u817f\u300d\u3001\u00a7e\u9ad8\u5ea6\u76f4\u63a5\u62c9\u7ad6\u76f4\u901f\u5ea6\u00a7r\uff08\u4e0d\u7528"
                + "\u4fef\u4ef0\u53bb\u8ffd\u9ad8\u5ea6\uff0c\u90a3\u6837\u5fc5\u7136\u8fc7\u51b2\uff09\u3002\u8f6c\u5f2f\u53d7"
                + "\u6c14\u52a8\u9650\u5236\uff1a\u8235\u91cf\u4e0a\u9650\u53ea\u6709\u00a7e\u300c0.3 + 3.2 \u00d7 |\u6eda\u8f6c|/9"
                + "0\u300d\u00a7r\uff0c\u914d AC-130H \u7684\u504f\u822a\u7cfb\u6570 0.9 \u21d2 \u00a7e\u6700\u5927\u89d2\u901f"
                + "\u5ea6 1.71\u00b0/\u62cd\u00a7r\uff0c\u00a7e\u8f6c\u5f2f\u534a\u5f84 \u2248 \u901f\u5ea6 \u00f7 0.0298\u00a7r"
                + "\u2014\u2014\u60f3\u8ba9\u534a\u5f84\u5c0f\uff0c\u5c31\u8981\u538b\u901f\u5ea6\u5e76\u628a\u6eda\u8f6c\u89d2"
                + "\u5199\u6ee1\u3002\u80e1\u841d\u535c\u53ea\u7ed9\u5979\u00a7e\u4e00\u4e2a\u70b9\u00a7r\uff1a\u6ca1\u654c\u4eba ="
                + " \u00a7e\u4e3b\u4eba\u4e0a\u65b9\u00a7r\uff08\u51b2\u8fc7\u53bb\u3001\u62d0\u4e2a\u5927\u5f2f\u518d\u56de\u6765 "
                + "= \u7ed5\u7740\u4e3b\u4eba\u76d8\u65cb\uff09\uff1b\u6709\u654c\u4eba = \u00a7e\u654c\u4eba\u6b63\u4e0a\u65b9"
                + "\u00a7r\uff08\u4e00\u904d\u904d\u4ece\u5934\u9876\u51b2\u8fc7\u53bb\u518d\u6389\u5934 = \u6765\u56de\u7a7f\u68ad"
                + "\u8f70\u70b8\uff0c\u70b8\u5f39\u7531\u6295\u5f39\u94fe\u8def\u5728\u6bcf\u6b21\u8fc7\u573a\u65f6\u7167\u5e38"
                + "\u4e22\uff09\u3002\u00a7e\u300c\u4e3b\u4eba\u79bb\u592a\u8fdc\u5c31\u653e\u5f03\u654c\u4eba\u300d\u90a3\u9053"
                + "\u95f8\u5bf9\u56fa\u5b9a\u7ffc\u653e\u5bbd\u5230 200 \u683c\u00a7r\uff08\u4e00\u8d9f\u901a\u573a + \u6389\u5934"
                + "\u672c\u6765\u5c31\u8981\u98de\u51fa 100~200 \u683c\uff09\u3002\u65e5\u5fd7\u641c\u00a7e\u300c\u56fa\u5b9a\u7ffc"
                + "\u5de1\u822a\u6863\u300d\u00a7r\uff08\u5e26 \u9f20\u6807X / \u63a8\u529b / \u6c34\u5e73\u901f\u5ea6 / \u7ad6"
                + "\u76f4\u901f\u5ea6 / \u8ddd\u76ee\u6807 / \u9ad8\u5dee\uff09\u3002",
                "\u00a7e\u534a\u5f84\u00a7r\uff1a\u00a7e\u5de1\u822a\u901f\u5ea6 0.80\uff08\u534a\u5f84 \u224827 \u683c\uff09"
                + "\u00a7r\u3001\u00a7e\u8f6c\u5f2f\u65f6\u76f4\u63a5\u5199\u6eda\u8f6c\u89d2\u9876\u5230 45\u00b0\u00a7r\uff08"
                + "\u4e0d\u7b49\u5de6\u53f3\u4f4d\u6162\u6162\u6eda\uff09\u3001\u00a7e\u9f20\u6807\u901a\u9053 12\u00a7r\uff080.80 "
                + "\u7684\u901f\u5ea6\u4e0b\u624d\u62ff\u5f97\u6ee1\u8235\u91cf\uff09\u3002\u00a7e\u9ad8\u5ea6\u00a7r\uff1a\u80e1"
                + "\u841d\u535c\u7684\u9ad8\u5ea6\u53ea\u8ddf\u4e3b\u4eba/\u654c\u4eba\u6709\u5173\uff0c\u4e0e\u811a\u4e0b\u7684"
                + "\u5c71\u4e18\u65e0\u5173\uff0c\u5c71\u4e00\u62ac\u5934\u5979\u5c31\u4e00\u5934\u649e\u8fdb\u53bb\uff1b\u800c"
                + "\u649e\u5730\u4f24\u5bb3\u662f\u00a7e18 \u00d7 (\u901f\u5ea6 \u2212 0.2)\u00b2\u00a7r\uff08\u901f\u5ea6 0.80 "
                + "\u65f6\u7ea6 6.5 \u70b9/\u6b21\uff09\u3002\u6240\u4ee5\u5979\u53e6\u52a0\u4e00\u6761\u00a7e\u300c\u5730\u5f62"
                + "\u51c0\u7a7a\u7ebf\u300d\u00a7r\uff1a\u76ee\u6807\u9ad8\u5ea6 = \u00a7e\u6700\u5927(\u80e1\u841d\u535c\u9ad8"
                + "\u5ea6, \u811a\u4e0b\u4e0e\u524d\u77bb\u8def\u5f84\u4e0a\u6700\u9ad8\u7684\u5730 + 14 \u683c)\u00a7r\uff0c\u524d"
                + "\u77bb\u8ddd\u79bb\u6309\u5f53\u524d\u901f\u5ea6\u6362\u7b97\uff08\u7ea6 80 \u683c\uff09\u3001\u6cbf\u884c\u8fdb"
                + "\u65b9\u5411\u4e0e\u76ee\u6807\u65b9\u5411\u5404\u626b\u4e09\u5217\uff1b\u88ab\u5730\u5f62\u9876\u8d77\u6765"
                + "\u65f6\u722c\u5347\u7387\u653e\u5bbd\u5230 \u00a7e0.30 \u683c/\u62cd\u00a7r\u3002\u5de1\u822a\u63a8\u529b\u4e0b"
                + "\u9650 \u00a7e1.20\u00a7r\uff08\u901f\u5ea6\u5df2\u7531\u901f\u5ea6\u73af\u538b\u4f4f\uff0c\u4e0d\u5fc5\u518d"
                + "\u9760\u63a8\u529b\u9876\uff09\u3002\u65e5\u5fd7\u91cc\u90a3\u4e00\u6863\u4f1a\u591a\u5199\u00a7e\u300c\u6eda"
                + "\u8f6c=\u300d\u00a7r\uff0c\u88ab\u5730\u5f62\u9876\u8d77\u6765\u65f6\u5199\u00a7e\u300c\u5730\u5f62\u51c0\u7a7a("
                + "\u62ac\u5230\u5730\u9762\u4e0a14\u683c) \u9ad8\u5dee=x\u2192y\u300d\u00a7r\u3002",
                "\u00a7e\u56fa\u5b9a\u7ffc\u52a0\u9ad8\u00a7r\uff1a\u65b0\u589e\u56fa\u5b9a\u7ffc\u4e13\u5c5e\u00a7e\u300c\u56fa"
                + "\u5b9a\u7ffc\u52a0\u9ad8 15 \u683c\u300d\u00a7r\u2014\u2014\u80e1\u841d\u535c\uff08\u8ddf\u968f = \u4e3b\u4eba +"
                + " 3 + 15\u3001\u63a5\u654c = \u654c\u4eba + 15 + 15\uff09\u4e0e\u5730\u5f62\u51c0\u7a7a\u7ebf\uff08\u5730\u9762 +"
                + " 14 + 15 = \u00a7e\u5730\u9762 + 29 \u683c\u00a7r\uff09\u5404\u52a0 15\uff0c\u76d8\u65cb\u4e0e\u63a5\u654c\u7ad9"
                + "\u4f4d\u6574\u4f53\u4e0a\u79fb 15 \u683c\u3002\u51c0\u7a7a\u7ebf\u7684\u5730\u9762\u8bfb\u6570\u7528\u00a7e"
                + "\u4e16\u754c\u9ad8\u5ea6\u56fe\u00a7r\uff08O(1)\u3001\u6ca1\u6709\u6df1\u5ea6\u4e0a\u9650\uff09\u3002\u53e6"
                + "\u5916\u6ce8\u610f\u00a7e\u5760\u673a\u662f\u300c\u5373\u65f6\u5904\u6b7b\u300d\u800c\u975e\u64e6\u5730\u6389"
                + "\u8840\u00a7r\uff1aSWB \u5728\u8f7d\u5177\u88ab\u6467\u6bc1\u4e14\u5e26 crash \u6807\u8bb0\u65f6\uff0c\u4f1a"
                + "\u628a\u4e58\u5ba2\u00a7e\u4e00\u6b21 114514 \u4f24\u5bb3\u00a7r\u6253\u6b7b\uff08VehicleDestroyUtils.crashPasse"
                + "ngers + VehicleMotionUtils.bounceVertical \u7684 setCrash(true)\uff09\u2014\u2014\u6240\u4ee5\u300c\u4e0d\u649e"
                + "\u5730\u300d\u662f\u552f\u4e00\u7684\u89e3\u6cd5\uff0c\u62ac\u9ad8\u5ea6\u5c31\u662f\u62ac\u5b89\u5168\u8fb9"
                + "\u754c\u3002\u00a7e\u53ea\u52a8\u56fa\u5b9a\u7ffc\u8fd9\u4e00\u6863\u00a7r\uff1a\u76f4\u5347\u673a / \u98de"
                + "\u8247 / \u626b\u5e1a / \u5730\u9762\u8f7d\u5177\u4e00\u4e2a\u6570\u90fd\u6ca1\u53d8\u3002\u65e5\u5fd7\u90a3"
                + "\u4e00\u6863\u4f1a\u591a\u5199\u00a7e\u300c\u56fa\u5b9a\u7ffc\u52a0\u9ad815\u683c\u300d\u00a7r\uff0c\u88ab\u5730"
                + "\u5f62\u9876\u8d77\u6765\u65f6\u5199\u00a7e\u300c\u5730\u5f62\u51c0\u7a7a(\u62ac\u5230\u5730\u9762\u4e0a29\u683c"
                + ")\u300d\u00a7r\u3002",
                "\u00a7e\u56fa\u5b9a\u7ffc\u52a0\u9ad8 30 \u683c\u00a7r\uff08\u8ddf\u968f = \u4e3b\u4eba + 33\u3001\u63a5\u654c ="
                + " \u654c\u4eba + 45\uff09\uff0c\u51c0\u7a7a\u7ebf = \u5730\u9762 + 14 + 30 = \u00a7e\u5730\u9762 + 44 \u683c"
                + "\u00a7r\u3002\u7ad6\u76f4\u81ea\u9a7e\u6bcf\u62cd\u6700\u591a\u62c9\u00a7e0.12\u00a7r\u683c\uff0c\u800c SWB "
                + "\u6bcf\u62cd\u672b\u5c3e\u7edf\u4e00\u6263\u91cd\u529b\u00a7e0.06\u00a7r\uff0c\u51c0\u589e \u22480.06 > 0\uff0c"
                + "\u4f4e\u901f/\u505c\u6ede\u65f6\u4e5f\u80fd\u771f\u6b63\u722c\u5347\u5e76\u5b88\u4f4f\u8fd9\u4e2a\u9ad8\u5ea6"
                + "\u3002\u4ecd\u00a7e\u53ea\u52a8\u56fa\u5b9a\u7ffc\u8fd9\u4e00\u6863\u00a7r\u3002\u65e5\u5fd7\u90a3\u4e00\u6863"
                + "\u73b0\u5728\u4f1a\u5199\u00a7e\u300c\u56fa\u5b9a\u7ffc\u52a0\u9ad830\u683c\u300d\u00a7r\uff0c\u88ab\u5730\u5f62"
                + "\u9876\u8d77\u6765\u65f6\u5199\u00a7e\u300c\u5730\u5f62\u51c0\u7a7a(\u62ac\u5230\u5730\u9762\u4e0a44\u683c)"
                + "\u300d\u00a7r\u3002\n\u00a7e\u56fa\u5b9a\u7ffc\u4fdd\u6301\u9ad8\u5ea6\u00a7r\uff1a\u9ad8\u5ea6\u8d70\u00a7e"
                + "\u5f15\u64ce\u539f\u751f\u7684\u4fef\u4ef0\u901a\u9053\u00a7r\u2014\u2014\u4e32\u7ea7\u63a7\u5236\u300c\u9ad8"
                + "\u5dee \u2192 \u671f\u671b\u7ad6\u76f4\u901f\u5ea6 \u2192 \u62ac\u5934/\u4f4e\u5934\u89d2\u300d\uff0c\u8d1f"
                + "\u89d2 = \u62ac\u5934\uff08\u4e0e\u8d77\u98de\u6863\u540c\u4e00\u7ea6\u5b9a\uff09\uff0c\u4e0b\u6c89/\u722c\u5347"
                + "\u90fd\u53d7\u63a7\u3002\u5979\u4f1a\u00a7e\u81ea\u5df1\u628a\u9ad8\u5ea6\u7a33\u4f4f\u3001\u722c\u56de\u76ee"
                + "\u6807\u9ad8\u5ea6\u00a7r\uff0c\u4e0d\u4f1a\u300c\u8d8a\u98de\u8d8a\u4f4e\u300d\u3002",
                "\u00a7ehome \u6a21\u5f0f\uff08\u5b88\u5bb6/\u9a7b\u5b88\uff09\u4e0b\u7684\u56fa\u5b9a\u7ffc\u300c\u5b89\u5168"
                + "\u964d\u843d\u300d\u00a7r\uff1a\u00a7e\u5728\u5730\u9762\u00a7r \u2192 \u4e0e\u522b\u7684\u5750\u9a91\u4e00"
                + "\u6837\u00a7e\u505c\u4f4f\u4e0d\u52a8\u00a7r\uff1b\u00a7e\u5728\u7a7a\u4e2d\u00a7r \u2192 \u7acb\u523b\u00a7e"
                + "\u9009\u4e00\u5757\u9644\u8fd1\u591f\u5e73\u7684\u5730\u9762\u00a7r\u5f53\u843d\u70b9\uff0c\u671d\u5b83\u00a7e"
                + "\u6536\u6cb9\u95e8\u5230\u6020\u901f\u3001\u6bcf\u62cd\u6536\u4e00\u70b9\u6c34\u5e73\u901f\u5ea6\u3001\u6309"
                + "\u53d7\u63a7\u4e0b\u6c89\u7387\u4e0b\u964d\u00a7r\uff0c\u79bb\u5730 6 \u683c\u8f6c\u300c\u63a5\u5730\u6bb5\u300d"
                + "\u628a\u4e0b\u6c89\u7387\u538b\u5230\u6700\u5c0f\uff0c\u00a7e\u8f7b\u8f7b\u63a5\u5730\u00a7r\uff1b\u843d\u5730"
                + "\u540e\u81ea\u52a8\u8f6c\u56de\u300c\u505c\u4f4f\u4e0d\u52a8\u300d\u3002\u7528\u300c\u53d7\u63a7\u4e0b\u6c89"
                + "\u300d\u800c\u4e0d\u662f\u5173\u6cb9\u95e8\u4efb\u5b83\u6389\uff1aSWB \u91cc\u8f7d\u5177\u5e26 crash \u6807"
                + "\u8bb0\u53c8\u88ab\u6467\u6bc1\u4f1a\u628a\u4e58\u5ba2\u00a7e\u4e00\u6b21\u4f24\u5bb3\u6253\u6b7b\u00a7r\uff08ai"
                + "r_crash\uff09\uff0c\u800c\u64e6\u5730\u5c31\u4f1a\u7f6e crash\u2014\u2014\u53ea\u6709\u00a7e\u4f4e\u901f\u3001"
                + "\u5c0f\u4e0b\u6c89\u7387\u63a5\u5730\u00a7r\u624d\u4e0d\u81f4\u547d\uff08\u649e\u51fb\u4f24\u5bb3 18\u00d7(v"
                + "\u22120.2)\u00b2\uff0c\u4f4e\u901f\u65f6\u8d8b\u8fd1 0\uff09\uff1b\u63a5\u5730\u90a3\u4e00\u523b\u8fd8\u4f1a"
                + "\u628a crash \u6807\u8bb0\u6e05\u6389\uff0c\u514d\u5f97\u7559\u4e00\u9897\u300c\u4ee5\u540e\u518d\u88ab\u6253"
                + "\u4e00\u4e0b\u5c31\u8fde\u5750\u300d\u7684\u96f7\u3002",
                "\u00a7e\u53ea\u52a8\u56fa\u5b9a\u7ffc\u8fd9\u4e00\u6863\u00a7r\uff1a\u76f4\u5347\u673a / \u98de\u8247 / \u626b"
                + "\u5e1a / \u5730\u9762\u8f7d\u5177\u4e00\u4e2a\u6570\u90fd\u6ca1\u53d8\u3002\u65b0\u589e\u65e5\u5fd7\u5173\u952e"
                + "\u8bcd\uff1a\u00a7e\u300c\u56fa\u5b9a\u7ffc\u964d\u843d\u00b7\u4e0b\u964d\u300d\u00a7r\u3001\u00a7e\u300c\u56fa"
                + "\u5b9a\u7ffc\u964d\u843d\u00b7\u63a5\u5730\u6bb5\u300d\u00a7r\u3001\u00a7e\u300c\u56fa\u5b9a\u7ffc\u964d\u843d"
                + "\u5b8c\u6210\uff1a\u5df2\u63a5\u5730\u300d\u00a7r\u3002",
                "\u00a7e\u56fa\u5b9a\u7ffc\u7684\u62ac\u5934\u4e0e\u9ad8\u5ea6\u73af\u00a7r\uff1a\u8d77\u98de\u62ac\u5934\u89d2 "
                + "\u00a7e35\u00b0\u00a7r\uff08\u4ecd\u5728\u5f15\u64ce ClampPitch 40\u00b0 \u4ee5\u5185\uff09\uff1b\u9ad8\u5ea6"
                + "\u73af\u7528\u300c\u00a7e\u8d1f = \u62ac\u5934\u00a7r\u300d\u7684\u7ea6\u5b9a\uff08\u4e0e\u5f15\u64ce\u539f"
                + "\u751f\u76d8\u65cb\u4e00\u81f4\uff09\uff0c\u5185\u73af\u589e\u76ca\u00a7e80\u00a7r\u3001\u62ac\u5934/\u4f4e"
                + "\u5934\u9650\u5e45\u00a7e30/12\u00b0\u00a7r\u3001\u4fef\u4ef0\u6b65\u8fdb\u00a7e1.0\u00b0/\u62cd\u00a7r\u3001"
                + "\u5de1\u822a\u7ad6\u76f4\u901f\u5ea6\u4e0a\u9650\u00a7e0.30\u00a7r\u2014\u2014\u5979\u4f1a\u4e3a\u9ad8\u5dee"
                + "\u771f\u6b63\u62ac\u5934\u3001\u6162\u6162\u722c\u5230\u76ee\u6807\u9ad8\u5ea6\u3002\u00a7e\u6ca1\u7535 = home "
                + "\u6a21\u5f0f\u00a7r\uff1a\u56fa\u5b9a\u7ffc\u00a7e\u7535\u91cf\u89c1\u5e95\u7acb\u523b\u8d70\u90a3\u5957\u5b89"
                + "\u5168\u964d\u843d\u00a7r\uff08\u9009\u5e73\u5730 \u2192 \u6020\u901f \u2192 \u53d7\u63a7\u4e0b\u6c89 \u2192 "
                + "\u8f7b\u63a5\u5730 \u2192 \u505c\u4f4f\uff09\uff0c\u65e5\u5fd7\u5199\u00a7e\u300c\u56fa\u5b9a\u7ffc\u7535\u91cf"
                + "\u89c1\u5e95 \u2192 \u5b89\u5168\u964d\u843d\u300d\u00a7r\uff0c\u4e0b\u964d/\u63a5\u5730\u6bb5\u90a3\u4e24\u884c"
                + "\u4f1a\u5e26\u00a7e\u300c\uff08\u7535\u91cf\u89c1\u5e95\uff09\u300d\u00a7r\u3002\u5de1\u822a\u65e5\u5fd7\u65b0"
                + "\u589e\u00a7e\u300c\u4fef\u4ef0=\u300d\u00a7r\u8bfb\u6570\uff0c\u4e00\u773c\u80fd\u770b\u51fa\u5979\u5f53\u65f6"
                + "\u7684\u59ff\u6001\u89d2\u3002",
                "\u00a7e\u4ecd\u4e0d\u5f00\u7684\u4e24\u53f0\u00a7r\uff1a\u00a7e\u6c64\u59c6 F6F\u00a7r\u3001\u00a7e\u8ff7\u4f60"
                + "\u5feb\u8247\u00a7r\u2014\u2014\u5b83\u4eec\u7684\u6cb9\u95e8\u4e0e\u59ff\u6001\u6574\u6bb5\u53ea\u5199\u7ed9"
                + "\u300c\u4e58\u5ba2\u662f\u73a9\u5bb6\u300d\u90a3\u4e00\u652f\uff0c\u5973\u4ec6\u662f\u751f\u7269\u3001\u8fdb"
                + "\u4e0d\u53bb\u90a3\u6761\u8f93\u5165\u901a\u9053\uff1b\u62ff\u6307\u6325\u68d2\u53f3\u51fb\u5b83\u4eec\uff0c"
                + "\u5979\u4f1a\u56de\u4e00\u53e5\u00a7e\u300c\u8fd9\u67b6 XXX \u64cd\u4f5c\u95e8\u69db\u592a\u9ad8\uff08\u6216"
                + "\u53ea\u8ba4\u73a9\u5bb6\u6765\u5f00\uff09\uff0c\u6211\u9a7e\u9a6d\u4e0d\u4e86\uff5e\u300d\u00a7r\u3002\n\u00a7e"
                + "\u5176\u4f59\u8f7d\u5177\u4e00\u5f8b\u4e0d\u53d7\u5f71\u54cd\u00a7r\uff1a\u5766\u514b / \u88c5\u7532\u8f66 / "
                + "\u76f4\u5347\u673a / \u98de\u8247\uff08\u57fa\u6d1b\u592b\u7b49\uff09\u7167\u65e7\u80fd\u9a91\u3001\u80fd\u5f00"
                + "\u3001\u80fd\u6253\u3002\u00a7e\u5df2\u7ecf\u5750\u4e0a\u8fd9\u56db\u67b6\u56fa\u5b9a\u7ffc\u7684\u5973\u4ec6"
                + "\u00a7r\u4e5f\u4f1a\u6bcf\u62cd\u81ea\u68c0\u3001\u81ea\u52a8\u89e3\u7ed1\uff08\u641c\u65e5\u5fd7\u300c\u9a91"
                + "\u4e58\u6307\u6325\u68d2\u300d\u80fd\u770b\u5230\u90a3\u4e00\u884c\uff09\u3002",
                "\u00a7e\u56fa\u5b9a\u7ffc\u7d22\u654c\u00a7r\uff1a\u53d1\u73b0\u4e0e\u7ef4\u6301\u90fd\u6309\u00a7e\u6c34\u5e73"
                + "\u8ddd\u79bb\u00a7r\u7b97\u2014\u2014\u9ad8\u5ea6\u5dee\u662f\u5979\u81ea\u5df1\u7684\u7ad9\u4f4d\u9020\u6210"
                + "\u7684\uff0c\u4e0d\u8be5\u5403\u6389\u300c\u770b\u5f97\u89c1\u8c01\u300d\uff1b\u65b0\u9501\u5b9a\u4ee5\u00a7e"
                + "\u4e3b\u4eba\u4e3a\u5706\u5fc3\u00a7r\u626b 50 \u683c\uff0c\u62ff\u4e0d\u5230\u4e3b\u4eba\u624d\u56de\u843d"
                + "\u5230\u81ea\u8eab\uff1b\u7ef4\u6301\u9501\u5b9a\u4ecd\u662f 128 \u683c\u3001\u540c\u6837\u6309\u6c34\u5e73"
                + "\u7b97\u3002\u5979\u5de1\u822a\u5728\u00a7e\u5730\u9762\u4e0a 44 \u683c\u00a7r\u3001\u63a5\u654c\u6863\u662f"
                + "\u00a7e\u654c\u4e0a 45 \u683c\u00a7r\uff0c\u6309\u6c34\u5e73\u5ea6\u91cf\u624d\u80fd\u771f\u6b63\u652f\u63f4"
                + "\u5230\u4e3b\u4eba\u8eab\u8fb9\u7684\u6218\u573a\u3002\u00a7e\u53ea\u52a8\u56fa\u5b9a\u7ffc\u8fd9\u4e00\u6863"
                + "\u00a7r\uff1a\u76f4\u5347\u673a / \u98de\u8247 / \u626b\u5e1a / \u5730\u9762\u8f7d\u5177\u4ecd\u662f\u81ea\u8eab"
                + "\u5706\u5fc3 + 3D 50 \u683c\u7403\u3002\n\u00a7e\u65b0\u589e\u65e5\u5fd7\u5173\u952e\u8bcd\u00a7r\uff1a\u00a7e"
                + "\u300c\u56fa\u5b9a\u7ffc\u7d22\u654c\u300d\u00a7r\uff08\u8282\u6d41 5 \u79d2\u4e00\u884c\uff0c\u5199\u660e\u5706"
                + "\u5fc3\u662f\u4e3b\u4eba\u8fd8\u662f\u81ea\u8eab\u3001\u6c34\u5e73\u591a\u5c11\u683c\uff09\u2014\u2014\u641c"
                + "\u5b83\u5c31\u80fd\u770b\u51fa\u5979\u6709\u6ca1\u6709\u5728\u4e3b\u4eba\u8eab\u8fb9\u9501\u5230\u4eba\u3002",
                "\u00a7e\u5766\u514b\u4e3b\u70ae\u5c04\u901f\u515c\u5e95\u00a7r\uff1a\u00a7e\u6709\u5f39\u5323\u00a7r\u7684\u70ae"
                + "\uff08M1A2 / T-90A / ZTZ-99A \u7684 Cannon\uff1a\u5f39\u5323 1 + \u88c5\u586b 100 \u62cd \u21d2 5 \u79d2\u4e00"
                + "\u53d1\uff09\u6309\u70ae\u81ea\u5df1\u7684\u5f39\u5323\u5faa\u73af\u5b9a\u95f4\u9694\uff1b\u00a7e\u6ca1\u6709"
                + "\u5f39\u5323\u00a7r\u7684\u70ae\u76f4\u63a5\u4ece\u8f66\u91cc\u53d6\u5f39\uff0c\u521b\u9020\u76d2\u8ba9\u5f39"
                + "\u53d6\u4e0d\u5b8c\uff0c\u4e8e\u662f\u53ea\u5269 RPM \u4e00\u9053\u95f8\u2014\u2014\u5f15\u64ce RPM \u7684\u9ed8"
                + "\u8ba4\u503c\u662f\u00a7e600\u00a7r\uff08ceil(1200/600) = \u00a7e2 \u62cd = \u6bcf 0.1 \u79d2\u4e00\u53d1\u00a7r"
                + "\uff09\u3002SWB \u91cc\u00a7etype_63.Main\u00a7r\u3001\u00a7emortar.Main\u00a7r\u3001\u00a7esodayo_pick_up_rocke"
                + "t.Main\u00a7r \u7684\u6761\u76ee\u53ea\u6709 Velocity/Gravity/Spread\uff0c\u6ca1\u6709 RPM/\u5f39\u5323/\u88c5"
                + "\u586b/\u70ed\u5ea6\u3002\u5224\u5b9a\u300c\u5f39\u5323 / \u88c5\u586b / \u6bcf\u53d1\u88c5\u586b / \u6bcf\u53d1"
                + "\u79ef\u70ed\u5168\u4e3a 0\u300d\u547d\u4e2d\u4e14\u8bfb\u5230\u7684 RPM \u6b63\u597d\u662f\u5f15\u64ce\u9ed8"
                + "\u8ba4 600 \u65f6\uff0c\u4e24\u53d1\u95f4\u9694\u515c\u5e95 \u00a7e20 \u62cd = 1 \u79d2\u00a7r\u3002\u8bfb\u7684"
                + "\u662f\u8fd0\u884c\u671f\u6570\u636e\uff0c\u6240\u4ee5 `\"Template\": \"@MG\"` \u8fd9\u7c7b\u7ee7\u627f\u771f"
                + "\u6570\u636e\u7684\u6302\u70b9\u4e0d\u7b97\uff08\u5b83\u4eec\u8fd0\u884c\u671f\u6709 RPM 600 + \u6bcf\u53d1"
                + "\u79ef\u70ed 4\uff09\u3002\u5199\u4e86 RPM \u7684 13 \u95e8\u70ae\u5168\u90fd\u5e26\u300c\u6bcf\u53d1\u79ef"
                + "\u70ed\u300d\uff0c\u5224\u5b9a\u4e00\u95e8\u90fd\u547d\u4e2d\u4e0d\u4e86\uff1b\u00a7eM1A2 / T-90A / ZTZ-99A "
                + "\u7b49\u4e3b\u70ae\u4e0e\u6240\u6709\u5199\u4e86 RPM \u7684\u673a\u67aa/\u673a\u70ae\u7684\u95f4\u9694\u4e00"
                + "\u4e2a\u6570\u90fd\u6ca1\u53d8\u00a7r\u3002",
                "\u65b0\u589e\u65e5\u5fd7\u5173\u952e\u8bcd\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u5c04\u901f\u300d\u00a7r"
                + "\uff08\u515c\u5e95\u751f\u6548\u65f6\u7559\u4e00\u884c\uff0c\u5199\u660e\u54ea\u95e8\u70ae\u3001\u515c\u5230"
                + "\u591a\u5c11\u62cd\uff09\u3002",
                "\u00a7e八、投弹安全高度（基洛夫先拉高再投）\u00a7r",
                "\u00a7e\u5f00\u00a7r\uff08\u9762\u677f\u00a7e\u300c\u9a91\u98de\u884c\u8f7d\u5177\u00b7\u60ac\u505c\u4e0e\u76d8\u65cb \u2192 \u6295\u5f39\u5b89\u5168\u9ad8\u5ea6\u300d\u00a7r\uff0c\u9ed8\u8ba4 \u00a7e20\u00a7r \u683c\uff0c\u5b83\u662f\u300c\u4e0b\u9650\u300d\uff1a\u5b9e\u9645\u5b89\u5168\u9ad8\u5ea6 = \u00a7e\u6700\u5927(\u8fd9\u4e2a\u503c, \u8fd9\u679a\u70b8\u5f39\u7684\u7206\u70b8\u534a\u5f84 + 6)\u00a7r\uff09\u3002\n\u00a7e\u4ec0\u4e48\u65f6\u5019\u751f\u6548\u00a7r\uff1a\u5979\u5f00\u7740\u00a7e\u98de\u884c\u8f7d\u5177\u00a7r\u3001\u4e14\u8fd9\u4e00\u4e0b\u662f\u00a7e\u5f80\u4e0b\u6295\u5f39\u00a7r\u65f6\u2014\u2014\u2460 \u673a\u8eab\u9ad8\u5ea6\u88ab\u62ac\u5230\u00a7e\u300c\u76ee\u6807\u9ad8\u5ea6 + \u8fd9\u4e2a\u683c\u6570\u300d\u00a7r\uff08\u8d70\u7684\u662f\u4e0e\u300c\u63a5\u654c\u5347\u5230\u654c\u4e0a\u300d\u540c\u4e00\u6761\u901a\u9053\uff1a\u98de\u8247\u7528\u5347\u529b\u8f74\u3001\u76f4\u5347\u673a\u7528\u603b\u8ddd\uff09\uff1b\u2461 \u00a7e\u6ca1\u722c\u5230\u4f4d\u5c31\u6309\u4f4f\u8fd9\u4e00\u53d1\u4e0d\u6295\u00a7r\uff08\u4e0d\u8017\u5f39\u3001\u4e0d\u5360\u51b7\u5374\uff09\uff0c\u5230\u4f4d\u4e86\u624d\u7167\u5e38\u6295\u3002\n\u00a7e\u4ec0\u4e48\u53eb\u300c\u8fd9\u4e00\u4e0b\u662f\u5f80\u4e0b\u6295\u5f39\u300d\u00a7r\uff1a\u8f66\u4e0a\u5f53\u524d\u90a3\u95e8\u6b66\u5668\u00a7e\u540d\u5b57\u91cc\u5e26 Bomb\u00a7r\uff08\u57fa\u6d1b\u592b\u7684\u552f\u4e00\u6b66\u5668\u5c31\u53eb Bomb\uff0c\u5f80\u4e0b\u4e22\u822a\u7a7a\u70b8\u5f39\uff09\uff0c\u00a7e\u6216\u8005\u00a7r\u5979\u81ea\u5df1\u80cc\u5305\u91cc\u5e26\u7740\u80fd\u653e\u7684\u70b8\u6599\uff08TNT / \u672b\u5730\u6c34\u6676 / \u91cd\u751f\u951a / \u5e8a\uff09\u3002\u4e0d\u6295\u5f39\u65f6\uff08\u6bd4\u5982\u53ea\u5f00\u673a\u70ae\u62a4\u822a\uff09\u9ad8\u5ea6\u7167\u5e38\u6309\u63a5\u654c\u6863\u8d70\uff0c\u4e0d\u4f1a\u767d\u767d\u98de\u9ad8\u4e22\u6389\u547d\u4e2d\u7387\u3002\n\u00a7e\u8fd9\u4e00\u6863\u7684\u4f5c\u7528\u00a7r\uff1a\u57fa\u6d1b\u592b\u90a3\u9897\u822a\u7a7a\u70b8\u5f39\uff08SWB \u91cc\u7684 Bor-57\uff09\u7206\u70b8\u534a\u5f84 \u00a7e42\u00a7r \u683c\u2014\u2014\u8d34\u5730\u6295\u5f39\u7b49\u4e8e\u628a\u5979\u81ea\u5df1\u4e5f\u5708\u8fdb\u7206\u5fc3\uff0c\u8fd9\u4e00\u6863\u5c31\u662f\u300c\u5148\u62c9\u9ad8\u518d\u4e22\u300d\u7684\u90a3\u9053\u9650\u5236\u3002\n\u00a7e\u586b 0 = \u5173\u6389\u8fd9\u9053\u9650\u5236\u00a7r\uff08\u60f3\u6295\u5c31\u6295\uff09\u3002\u53ea\u4f5c\u7528\u4e8e\u00a7e\u98de\u884c\u8f7d\u5177\u00a7r\uff0c\u5730\u9762\u5766\u514b / \u88c5\u7532\u8f66\u4e0d\u53d7\u5f71\u54cd\uff1b\u00a7e\u300c\u9a91\u98de\u884c\u8f7d\u5177\u00b7\u60ac\u505c\u4e0e\u76d8\u65cb\u300d\u603b\u5f00\u5173\u5173\u7740\u65f6\u672c\u95f8\u4e5f\u4e0d\u751f\u6548\u00a7r\uff08\u90a3\u65f6\u6ca1\u4eba\u8d1f\u8d23\u628a\u5979\u62ac\u4e0a\u53bb\uff0c\u518d\u6309\u4f4f\u6295\u5f39\u5c31\u7b49\u4e8e\u6c38\u8fdc\u4e0d\u6295\uff09\u3002",
                "\u00a7e九、数值（面板：移动与行为 → 骑乘指挥棒 / 骑飞行载具·悬停与盘旋）\u00a7r",
                "\u00a7e\u9a91\u4e58\u6307\u6325\u68d2\u00b7\u603b\u5f00\u5173\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5173"
                + "\u6389 = \u518d\u4e5f\u4e0d\u7ed1\u5b9a\uff0c\u5750\u9a91\u7167\u539f\u7248\u81ea\u7531\u884c\u52a8\u3002\n"
                + "\u00a7e\u9a91\u4e58\u00b7\u8ddf\u968f\u505c\u4e0b\u8ddd\u79bb\u00a7r\uff08\u9ed8\u8ba4 5.0 \u683c\uff0c1~16"
                + "\uff09\uff1a\u79bb\u4f60\u591a\u8fd1\u5c31\u505c\u4e0b\u4e0d\u8ffd\u4e86\u3002\u5927\u8f66\uff08\u5766\u514b"
                + "\uff09\u7684\u505c\u8f66\u8ddd\u79bb\u4f1a\u6309\u8f66\u4f53\u534a\u5bbd\u81ea\u52a8\u653e\u5927\uff08\u7ea6 3~4"
                + " \u683c\uff09\uff0c\u4e0e\u8fd9\u4e00\u9879\u00a7e\u53d6\u5927\u00a7r\uff0c\u6240\u4ee5\u5728\u8f66\u4f53\u4e4b"
                + "\u5916\u5c31\u505c\u4f4f\u3001\u4e0d\u518d\u649e\u4eba\u3002\n\u00a7e\u9a91\u4e58\u00b7\u901f\u5ea6\u603b\u500d"
                + "\u7387\u00a7r\uff08\u9ed8\u8ba4 1.0\uff0c0.2~3.0\uff09\uff1a\u5acc\u6162\uff08\u9a91\u9a74 / \u732a\u8ddf\u4e0d"
                + "\u4e0a\uff09\u5f80\u4e0a\u8c03\uff1b\u5acc\u5feb\uff08\u590d\u6742\u5730\u5f62\u4e0a\u5bb9\u6613\u88ab\u7529"
                + "\u4e0b\u6765\uff09\u5f80 0.5 \u8c03\u3002",
                "\u00a7e\u9a91\u4e58\u00b7\u5bb6\u5177\u7c7b\u5750\u9a91\u9ed1\u540d\u5355\u00a7r\uff08\u9ed8\u8ba4 = TLM \u81ea"
                + "\u5e26\u7684\u00a7e\u6905\u5b50 chair\u00a7r \u4e0e \u00a7e\u5750\u57ab sit\u00a7r\uff09\uff1a\u5217\u5728\u8fd9"
                + "\u91cc\u7684\u5b9e\u4f53\u88ab\u5f53\u4f5c\u300c\u5bb6\u5177\u300d\u2014\u2014\u5973\u4ec6\u5750\u5728\u4e0a"
                + "\u9762\u65f6\u672c\u6a21\u7ec4\u00a7e\u6240\u6709\u9a91\u4e58\u6539\u52a8\u4e00\u5f8b\u4e0d\u751f\u6548\u00a7r"
                + "\uff08\u4e0d\u4f1a\u88ab\u7ed1\u5b9a\u3001\u4e0d\u4f1a\u88ab\u9a71\u52a8\u3001\u4f20\u9001\u65f6\u8d70\u539f"
                + "\u7248\u4e58\u5ba2\u89c4\u5219\uff09\u3002\u522b\u7684\u6a21\u7ec4\u7684\u53ef\u5750\u5bb6\u5177\u5f80\u8fd9"
                + "\u4e00\u884c\u586b\u4e00\u6761\u00a7e\u5b9e\u4f53\u7c7b\u578b id\u00a7r\uff08modid:entity\uff09\u5373\u53ef"
                + "\u3002\n\u00a7e\u9a91\u4e58\u6307\u6325\u68d2\u00b7\u72ec\u5360\u53f3\u51fb\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09"
                + "\uff1a\u624b\u91cc\u62ff\u7740\u6307\u6325\u68d2\u65f6\uff0c\u53f3\u51fb\u4efb\u4f55\u5b9e\u4f53\u00a7e\u53ea"
                + "\u89e6\u53d1\u6307\u6325\u68d2\u81ea\u5df1\u7684\u6548\u679c\u00a7r\uff0c\u4e0d\u518d\u89e6\u53d1\u8be5\u5b9e"
                + "\u4f53\u81ea\u8eab\u7684\u53f3\u51fb\u2014\u2014\u6700\u76f4\u63a5\u7684\u4e00\u6761\u5c31\u662f\u00a7e\u62ff"
                + "\u68cd\u5b50\u9a91\u4e0d\u4e0a\u9f99 / \u8f66\u5b50\u00a7r\u3002\u5173\u6389 = \u53ea\u6709\u672c\u6a21\u7ec4"
                + "\u8ba4\u5f97\u51fa\u7684\u76ee\u6807\u624d\u7531\u68cd\u5b50\u63a5\u7ba1\u3002\n\u00a7e\u6a21\u7ec4\u5750\u9a91"
                + "\u00b7\u517c\u5bb9\u00a7r\u4e0e\u00a7e\u6a21\u7ec4\u5750\u9a91\u00b7\u4ee3\u5979\u5f00\u706b\u00a7r\uff08\u90fd"
                + "\u9ed8\u8ba4\u5f00\uff09\uff1a\u89c1\u7b2c\u4e94\u8282\u3002",
                "\u00a7e\u65e0\u978d\u53ef\u9a91\u4ec6\u4ece\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u8ba9\u5973\u4ec6\u80fd"
                + "\u9a91\u90a3\u4e9b\u00a7e\u4e0d\u9700\u8981\u978d\u00a7r\u7684\u6a21\u7ec4\u4ec6\u4ece\uff08\u8be1\u5384\u5deb"
                + "\u6cd5\u7684\u7ea2\u77f3\u5de8\u517d\u7b49\uff09\u3002\u53e3\u5f84 = \u00a7e\u662f Mob + \u58f0\u660e\u4e86 Play"
                + "erRideable \u6216\u8be1\u5384 IAutoRideable + \u4e0d\u80fd\u88c5\u978d\u00a7r\uff1b\u00a7e\u6ca1\u4e0a\u978d"
                + "\u7684\u539f\u7248\u9a6c / \u9a86\u9a7c\u7167\u6837\u8981\u5148\u88c5\u978d\u00a7r\uff0c\u4e0d\u4f1a\u88ab\u8fd9"
                + "\u6761\u7ed5\u8fc7\u3002\n\u00a7e\u6a21\u7ec4\u4ec6\u4ece\u5750\u9a91\u00b7\u5355\u72ec\u533a\u95f4\u00a7r\uff08"
                + "\u9ed8\u8ba4\u5f00\uff09\uff1a\u65e0\u978d\u53ef\u9a91\u4ec6\u4ece\u9a91\u4e0a\u4e4b\u540e\u00a7e\u53ea\u8d4b"
                + "\u901f\u5ea6\u3001\u5176\u4f59\u5f52\u5b83\u81ea\u5df1\u7684 AI\u00a7r\uff08\u89c1\u7b2c\u4e00\u8282\uff09\uff1b"
                + "\u5173\u95ed = \u7531\u6a21\u7ec4\u4ee3\u5b83\u5f00\u706b\u3002\u00a7e\u6a21\u7ec4\u4ec6\u4ece\u5750\u9a91\u00b7"
                + "\u4f24\u5bb3\u8f6c\u79fb\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5979\u53d7\u7684\u4f24\u5bb3\u8f6c\u7ed9"
                + "\u5750\u9a91\uff1b\u5173\u95ed = \u5979\u81ea\u5df1\u7167\u5e38\u53d7\u4f24\u3002\u4e3b\u4eba\u00a7e\u7a7a\u624b"
                + "\u53f3\u51fb\u00a7r\u5b83\u5373\u53ef\u00a7e\u76f4\u63a5\u63a5\u7ba1\u00a7r\uff08\u5973\u4ec6\u5e72\u51c0\u4e0b"
                + "\u978d\uff0c\u4f60\u6309\u539f\u7248\u81ea\u5df1\u5f00\uff09\u3002\u7ec6\u8282\u89c1\u7b2c\u4e00\u8282\u3002",
                "\u00a7e\u60ac\u505c\u9ad8\u5ea6\u00a7r\uff08\u9ed8\u8ba4 3 \u683c\uff09/ \u00a7e\u63a5\u654c\u9ad8\u5ea6\u00a7r"
                + "\uff08\u9ed8\u8ba4 15 \u683c\uff09/ \u00a7e\u76d8\u65cb\u534a\u5f84\u00a7r\uff08\u9ed8\u8ba4 4 \u683c\uff09/ "
                + "\u00a7e\u6295\u5f39\u5b89\u5168\u9ad8\u5ea6\u00a7r\uff08\u9ed8\u8ba4 20 \u683c\uff09\uff1a\u89c1\u7b2c\u4e94"
                + "\u3001\u4e03\u8282\u3002\n\u00a7e\u53ea\u8ba4\u6307\u6325\u68d2\u7ed1\u5b9a\u7684\u5750\u9a91\u00a7r\uff1a\u672c"
                + "\u94fe\u8def\u53ea\u8ba4\u00a7e\u672c\u6a21\u7ec4\u81ea\u5df1\u7528\u6307\u6325\u68d2\u7ed1\u4e0a\u53bb\u7684"
                + "\u00a7r\u90a3\u6bb5\u9a91\u4e58\u5173\u7cfb\u3002\u539f\u7248 / \u522b\u7684\u6a21\u7ec4\u8ba9\u5979\u5750\u8239"
                + "\u3001\u5750\u77ff\u8f66\u3001\u88ab\u62fd\u4e0a\u522b\u4eba\u7684\u5750\u9a91\u2014\u2014\u672c\u6a21\u7ec4"
                + "\u7684\u00a7e\u9a71\u52a8 / \u95f2\u901b\u6291\u5236 / \u8fde\u5750\u9a91\u4f20\u9001\u4e00\u5f8b\u4e0d\u751f"
                + "\u6548\u00a7r\uff0c\u5b8c\u5168\u6309\u539f\u7248\u4e58\u5ba2\u89c4\u5219\u8d70\u3002\u00a7e\u626b\u5e1a\u4e5f"
                + "\u4e0d\u662f\u5750\u9a91\u00a7r\uff1a\u5b83\u6709\u81ea\u5df1\u90a3\u6574\u5957\u98de\u6cd5\uff0c\u6307\u6325"
                + "\u68d2\u9009\u4e2d\u4e0d\u4e86\u5b83\u3001\u4e5f\u4e0d\u4f1a\u53bb\u52a8\u5b83\u3002\u62ff\u68cd\u5b50\u70b9"
                + "\u6905\u5b50 / \u5750\u57ab / \u626b\u5e1a\u4f1a\u00a7e\u76f4\u63a5\u7ed9\u4e00\u53e5\u62d2\u7edd\u00a7r\uff08"
                + "\u4e0d\u662f\u6ca1\u53cd\u5e94\uff09\u3002",
                "\u00a7e十、排查\u00a7r",
                "\u00a7e\u53f3\u51fb\u6ca1\u53cd\u5e94\u00a7r \u2192 \u786e\u8ba4\u624b\u91cc\u62ff\u7684\u662f\u00a7e\u9a91"
                + "\u4e58\u6307\u6325\u68d2\u00a7r\u3001\u987a\u5e8f\u662f\u00a7e\u5148\u5750\u9a91\u540e\u5973\u4ec6\u00a7r\u3001"
                + "\u5750\u9a91\u00a7e\u5df2\u4e0a\u978d / \u8f7d\u5177\u6709\u5ea7\u4f4d / \u9f99\u5df2\u9a6f\u670d\u4e14\u9636"
                + "\u6bb5 \u2265 2\u00a7r\uff0c\u4e14\u5b83\u80cc\u4e0a\u6ca1\u6709\u522b\u4eba\uff08\u63d0\u793a\u6c14\u6ce1\u4f1a"
                + "\u5199\u660e\u662f\u54ea\u4e00\u6761\uff09\u3002\n\u00a7e\u5148\u53f3\u51fb\u5973\u4ec6\u518d\u53f3\u51fb\u5750"
                + "\u9a91\uff0c\u7ed1\u4e0d\u4e0a\u00a7r \u2192 \u8fd9\u662f\u00a7e\u6545\u610f\u5835\u6b7b\u00a7r\u7684\uff0c"
                + "\u5fc5\u987b\u5148\u7528\u6307\u6325\u68d2\u53f3\u51fb\u5750\u9a91\u3002\n\u00a7e\u53f3\u51fb\u63d0\u793a\u300c"
                + "\u8fd9\u53ea\u5750\u9a91\u5df2\u7ecf\u6709\u5973\u4ec6\u4e86\u300d\u00a7r \u2192 \u8fd9\u8f86\u8f66\u4e0a\u5df2"
                + "\u7ecf\u7ed1\u4e86\u53e6\u4e00\u4f4d\u5973\u4ec6\uff1b\u5148\u628a\u4e0a\u4e00\u4f4d\u00a7e\u6f5c\u884c\u53f3"
                + "\u51fb\u00a7r\u89e3\u4e0b\u6765\uff0c\u6216\u6362\u4e00\u8f86\u3002\n\u00a7e\u62ff\u7740\u68cd\u5b50\u5374\u8fd8"
                + "\u662f\u80fd\u9a91\u4e0a\u9f99 / \u8f66\u5b50\u00a7r \u2192 \u90a3\u662f\u00a7e\u300c\u9a91\u4e58\u6307\u6325"
                + "\u68d2\u00b7\u72ec\u5360\u53f3\u51fb\u300d\u00a7r\u8fd9\u9879\u5173\u4e86\uff0c\u6253\u5f00\u5373\u53ef\uff08"
                + "\u9762\u677f\uff1a\u79fb\u52a8\u4e0e\u884c\u4e3a \u2192 \u9a91\u4e58\u6307\u6325\u68d2\uff09\u3002",
                "\u00a7e\u5979\u5750\u4e0a\u53bb\u5374\u4e0d\u52a8\u00a7r \u2192 \u770b\u5979\u662f\u4e0d\u662f\u00a7e\u79bb"
                + "\u4f60\u5df2\u7ecf 5 \u683c\u5185\u00a7r\uff08\u90a3\u5c31\u4e0d\u9a71\u52a8\uff0c\u6b63\u5e38\uff09\u3001\u6216"
                + "\u5750\u9a91\u88ab\u5899 / \u6805\u680f\u56f0\u4f4f\uff08\u90a3\u662f\u5750\u9a91\u81ea\u5df1\u5bfb\u8def\u7684"
                + "\u5224\u65ad\uff09\uff1b\u5353\u8d8a\u524d\u7ebf\u7684\u8f7d\u5177\u8fd8\u8981\u770b\u5979\u00a7e\u5728\u4e0d"
                + "\u5728\u9a7e\u9a76\u4f4d\uff08\u5ea7\u4f4d 0\uff09\u00a7r\u3002\n\u00a7e\u5927\u8f66\u9876\u7740 / \u649e\u5012"
                + "\u4e3b\u4eba\u00a7r \u2192 \u505c\u8f66\u8ddd\u79bb\u6309\u8f66\u4f53\u534a\u5bbd\u81ea\u52a8\u653e\u5927\uff08"
                + "\u5766\u514b\u7ea6 3~4 \u683c\uff09\uff1b\u5acc\u8fdc\u5c31\u628a\u00a7e\u300c\u8ddf\u968f\u505c\u4e0b\u8ddd"
                + "\u79bb\u300d\u00a7r\u8c03\u5c0f\uff0c\u4e24\u8005\u53d6\u5927\u3002\n\u00a7e\u5766\u514b\u4e0d\u5f00\u70ae\u00a7"
                + "r \u2192 \u5148\u786e\u8ba4\u9762\u677f\u5f00\u4e86\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u4ee3\u5979\u5f00"
                + "\u706b\u300d\u00a7r\uff0c\u518d\u641c\u65e5\u5fd7\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u70ae\u4f4d\u300d"
                + "\u00a7r\u770b\u70ae\u5854\u6709\u6ca1\u6709\u62ff\u5230\u76ee\u6807\uff1b\u00a7e\u5979\u6ca1\u6709\u653b\u51fb"
                + "\u76ee\u6807\u5c31\u4e0d\u4f1a\u5f00\u70ae\u00a7r\uff08\u5468\u56f4\u6709\u654c\u4eba\u65f6\u5979\u4f1a\u4e3b"
                + "\u52a8\u7d22\u654c\uff09\u3002",
                "\u00a7e\u5979\u5e26\u4e86\u4e00\u5806\u5b50\u5f39\u8f66\u8fd8\u662f\u6253\u4e0d\u54cd\u00a7r \u2192 \u641c\u00a7"
                + "e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u88c5\u5f39\u300d\u00a7r\uff1a\u6709\u8fd9\u884c\u8bf4\u660e\u786e\u5b9e"
                + "\u642c\u4e86\uff08\u6570\u5b57 = \u51e0\u53d1\uff09\uff1b\u4e00\u884c\u90fd\u6ca1\u6709\u901a\u5e38\u662f\u00a7e"
                + "\u5979\u80cc\u5305\u91cc\u6ca1\u6709\u300c\u8fd9\u8f66\u4efb\u610f\u4e00\u95e8\u6b66\u5668\u5403\u7684\u90a3"
                + "\u79cd\u300d\u5b50\u5f39\u00a7r\u3002\u4e5f\u53ef\u4ee5\u76f4\u63a5\u6253\u5f00\u8f66\u7684\u5bb9\u5668\u754c"
                + "\u9762\u770b\u5f39\u836f\u683c\u3002\n\u00a7e\u5979\u5f00\u76f4\u5347\u673a\u4e71\u98de / \u4e0d\u52a8 / \u6389"
                + "\u9ad8\u5ea6\u88ab\u53cd\u590d\u62c9\u56de\u00a7r \u2192 \u641c\u00a7e\u300c\u98de\u884c\u6863\u300d\u00a7r"
                + "\uff08\u4f1a\u5199\u9f20\u6807\u901a\u9053\u503c\u3001\u603b\u8ddd\u4f4d\u3001\u8ddd\u76ee\u6807\u4e0e\u9ad8"
                + "\u5dee\uff09\uff1b\u5979\u5f00\u76f4\u5347\u673a\u65f6\u504f\u822a / \u4fef\u4ef0\u8d70\u9f20\u6807\u901a\u9053"
                + "\u3001\u5347\u964d\u8d70\u603b\u8ddd\uff0c\u8d34\u5230\u76ee\u6807\u4f1a\u60ac\u505c\u2014\u2014\u8fd9\u662f"
                + "\u98de\u884c\u8f7d\u5177\u7684\u4e13\u5c5e\u884c\u4e3a\uff0c\u4e0e\u5730\u9762\u8f66\u5b8c\u5168\u4e0d\u540c"
                + "\u3002",
                "\u00a7e\u76f4\u5347\u673a\u6253\u4ed7\u8d34\u5730\u4e71\u7a9c / \u5708\u592a\u5927 / \u9ad8\u5ea6\u4e0d\u5bf9"
                + "\u00a7r \u2192 \u641c\u00a7e\u300c\u7a7a\u6218\u300d\u00a7r\uff1a\u4f1a\u5199\u300c\u63a5\u654c \u2192 \u722c"
                + "\u5230\u654c\u4e0a N \u683c\u3001\u7ed5\u7740\u654c\u4eba\u76d8\u65cb\uff08\u534a\u5f84 M \u683c\uff09\u300d"
                + "\uff1b\u6ca1\u8fd9\u884c\u8bf4\u660e\u5979\u6b64\u523b\u6ca1\u6709\u653b\u51fb\u76ee\u6807\uff0c\u6216\u9762"
                + "\u677f\u00a7e\u300c\u9a91\u98de\u884c\u8f7d\u5177\u00b7\u60ac\u505c\u4e0e\u76d8\u65cb\u300d\u00a7r\u5173\u7740"
                + "\u3002\u9ad8\u5ea6\u8c03\u00a7e\u300c\u63a5\u654c\u9ad8\u5ea6\u300d\u00a7r\u3001\u5708\u5927\u5708\u5c0f\u8c03"
                + "\u00a7e\u300c\u76d8\u65cb\u534a\u5f84\u300d\u00a7r\u3002\n\u00a7e\u6295\u5f39\u5b89\u5168\u9ad8\u5ea6\u6ca1"
                + "\u751f\u6548 / \u5979\u4e0d\u6295\u5f39\u00a7r \u2192 \u641c\u00a7e\u300c\u7a7a\u6218\u300d\u00a7r\u770b\u6709"
                + "\u6ca1\u6709\u300c\u6295\u5f39\u5b89\u5168\u9ad8\u5ea6\u672a\u5230 \u2192 \u5148\u722c\u5347\u3001\u8fd9\u4e00"
                + "\u53d1\u6309\u4f4f\u300d\uff1b\u6709\u8fd9\u884c\u8bf4\u660e\u9650\u5236\u5728\u6b63\u5e38\u5de5\u4f5c\uff0c"
                + "\u7b49\u722c\u5230\u4f4d\u5c31\u4f1a\u6295\u3002\u00a7e\u586b 0 \u6216\u5173\u6389\u603b\u5f00\u5173\u90fd\u4f1a"
                + "\u8ba9\u8fd9\u9053\u9650\u5236\u5931\u6548\u00a7r\u3002\n\u00a7e\u9f99\u80cc\u4e0a\u7684\u5149\u6807\u4e00\u76f4"
                + "\u4eae\u7740\u00a7r \u2192 \u4e0d\u7528\u7ba1\uff0c\u00a7e30 \u79d2\u81ea\u52a8\u7184\u706f\u00a7r\uff1b\u5e26"
                + "\u6807\u8bb0\u4f46\u5df2\u67e5\u65e0\u5f52\u5c5e\u7684\u6bcf 5 \u79d2\u626b\u4e00\u6b21\u3001\u89c1\u5230\u5c31"
                + "\u7184\u3002\u60f3\u7acb\u523b\u5f04\u6389\u5c31\u62ff\u6307\u6325\u68d2\u53f3\u51fb\u5b83\u4e00\u4e0b\u518d"
                + "\u8d70\u5f00\uff0c\u6216\u76f4\u63a5\u628a\u5973\u4ec6\u89e3\u7ed1\u3002",
                "\u00a7e\u5750\u5728\u9f99\u4e0a\u600e\u4e48\u90fd\u4e0b\u4e0d\u6765\u00a7r \u2192 \u62ff\u00a7e\u9a91\u4e58"
                + "\u6307\u6325\u68d2\u76f4\u63a5\u53f3\u51fb\u5979\u6216\u90a3\u6761\u9f99\u00a7r\u5373\u53ef\uff08\u4e0e\u8f7d"
                + "\u5177\u540c\u53e3\u5f84\uff09\u3002\n\u00a7e\u9f99\u4e0a\u7684\u5979\u89c2\u611f\u8fdd\u548c / \u76f8\u5bf9"
                + "\u9f99\u5728\u6f02\u00a7r \u2192 \u8fd9\u662f\u00a7e\u5df2\u77e5\u7684\u6298\u4e2d\u65b9\u6848\u00a7r\uff08"
                + "\u89c1\u7b2c\u4e94\u8282\uff09\uff1a\u4f4d\u7f6e\u9760\u516c\u5f0f\u6446\u5230\u9f99\u7684\u73a9\u5bb6\u978d"
                + "\u4f4d\uff0c\u98de\u8d77\u6765\u3001\u8f6c\u8eab\u65f6\u6709\u660e\u663e\u9519\u4f4d\u3002\u00a7e\u4e0d\u5f71"
                + "\u54cd\u529f\u80fd\uff0c\u4f46\u4e0d\u5efa\u8bae\u957f\u671f\u8fd9\u4e48\u7528\u00a7r\uff1b\u82e5\u4ecd\u6709"
                + "\u7591\u95ee\u8bf7\u63cf\u8ff0\u9f99\u7684\u989c\u8272\u4e0e\u9636\u6bb5\u3002\n\u00a7e\u7279\u6b8a\u8f7d\u5177"
                + "\u4e0a\u7684\u5979\u600e\u4e48\u4f20\u90fd\u4f20\u4e0d\u8fc7\u6765\u00a7r \u2192 \u5353\u8d8a\u524d\u7ebf\u8f7d"
                + "\u5177 / \u9f99\u4e0a\u00a7e\u53ea\u6709\u4f60\u624b\u52a8\u7528\u6392\u73ed\u8868\u4f20\u9001\u00a7r\u624d"
                + "\u53eb\u5f97\u52a8\uff0c\u4e14\u00a7e\u53ea\u4f20\u4eba\u4e0d\u4f20\u8f7d\u5177\u00a7r\u3001\u4f20\u9001\u65f6"
                + "\u81ea\u52a8\u89e3\u9664\u7ed1\u5b9a\uff1b\u60f3\u8ba9\u5979\u8ddf\u7740\u8d70\u8bf7\u81ea\u5df1\u5f00\u7740"
                + "\u8f7d\u5177\u8d70\u3002\n\u00a7e\u65e5\u5fd7\u00a7r\uff1alatest.log \u641c\u00a7e\u300c\u9a91\u4e58\u6307\u6325"
                + "\u68d2\u300d\u00a7r\u2014\u2014\u9009\u4e2d\u5973\u4ec6 / \u9009\u4e2d\u5750\u9a91 / \u7ed1\u5b9a / \u89e3\u9664"
                + "\uff08\u539f\u56e0\uff09/ \u6362\u7ed1 / \u8fde\u4eba\u5e26\u5750\u9a91\u4f20\u9001 \u90fd\u4f1a\u5199\u4e00"
                + "\u884c\uff0c\u5e26\u5973\u4ec6\u540d\u4e0e\u5750\u9a91\u540d\uff0c\u7ed1\u5b9a\u90a3\u884c\u8fd8\u4f1a\u5199"
                + "\u51fa\u7b97\u51fa\u6765\u7684\u901f\u5ea6\u500d\u7387\u4e0e\u8ddf\u968f\u8ddd\u79bb\u3002\u8f7d\u5177\u9a7e"
                + "\u9a76\u53e6\u6709\u4e00\u8def\uff1a\u641c\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u300d\u00a7r\uff08\u542b\u5f15"
                + "\u64ce\u540d / \u9f99\u7684\u9636\u6bb5\uff09\u3001\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u76ee\u6807\u300d"
                + "\u00a7r\u3001\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u70ae\u4f4d\u300d\u00a7r\u3001\u00a7e\u300c\u6a21\u7ec4"
                + "\u5750\u9a91\u00b7\u5f00\u706b\u300d\u00a7r\u3001\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u88c5\u5f39\u300d"
                + "\u00a7r\u3001\u00a7e\u300c\u6a21\u7ec4\u5750\u9a91\u00b7\u5f39\u79cd\u300d\u00a7r / \u00a7e\u300c\u6a21\u7ec4"
                + "\u5750\u9a91\u00b7\u6362\u70ae\u300d\u00a7r\uff1b\u98de\u884c\u6863\u641c\u00a7e\u300c\u98de\u884c\u6863\u300d"
                + "\u00a7r\u3001\u7a7a\u6218\u641c\u00a7e\u300c\u7a7a\u6218\u300d\u00a7r\u3002");
    }

    /**
     * v1.5.393 实测八百零四 【饰品「大运」】手册章节。
     *
     * <p>需求原文："加入一个新饰品，可以由玩家和女仆进行佩戴。佩戴的效果是使用鞘翅飞行的过程中
     * 可以直接击毁自身周边 5×5 范围内除硬度大于等于黑曜石以及硬度&lt;0 的一切方块。配置选项里面
     * 也可以写。这个效果在女仆空袭的时候生效。"
     *
     * <p>正文只回答"现在怎么用"：是什么 / 谁能戴 / 清什么 / 怎么调。过程叙事归更新日志。
     */
    static GuideContent.Chapter daYunGuide() {
        return new GuideContent.Chapter("饰品「大运」（鞘翅飞行时开路）",
                "\u00a7e【大运】\u00a7r是一件\u00a7e戴在身上就生效\u00a7r的饰品：只要你\u00a7e使用鞘翅飞行\u00a7r，"
                        + "自身周边\u00a7e5×5×5（前后左右上下各 2 格，共 125 格）\u00a7r内符合条件的方块会被\u00a7e直接击毁\u00a7r——"
                        + "贴着山壁滑翔就是一条隧道，掠过树林就是一条走廊。",
                // 实测八百一十三：合成表整块画出来（物品图标 + 产物），不再只是文字配方
                "\u00a7e合成\u00a7r（工作台）："
                        + "[[#shaped;IDI;RMR;IDI;I=minecraft:iron_block;D=minecraft:diamond_block;R=minecraft:redstone_block;M=minecraft:minecart;>maid_smart:da_yun;@铁块×4 + 钻石块×2 + 红石块×2 + 矿车×1]]",
                "\u00a7e一、两种佩戴方式（同一个物品，戴在谁身上就给谁开路）\u00a7r",
                "\u00a7e女仆\u00a7r：把「大运」放进\u00a7e她自己的饰品栏\u00a7r（TLM 的饰品格，就是放头饰、"
                        + "背包那排格子）。她戴着它时\u00a7e只有在空袭模式下\u00a7r（飞行作战 / 飞行远战这两种"
                        + "真的用鞘翅飞起来打的任务）\u00a7e且真的在滑翔\u00a7r，才会开路。\n"
                        + "\u00a7e玩家\u00a7r：放进你自己的\u00a7eCurios 饰品栏\u00a7r（任意接受它的槽位都行），"
                        + "自己\u00a7e鞘翅滑翔\u00a7r时开路——判定口径与女仆侧一模一样（同一个破坏引擎、同一份配置）。"
                        + "\u00a7e需要装 Curios\u00a7r；没装时这一档静默不生效，物品本身与女仆侧都不受影响。\n"
                        + "\u00a7e物品本身不带状态\u00a7r：不写数据、不记冷却——「谁戴着」由饰品栏回答。"
                        + "所以同一件反复取放、换人佩戴都不会残留。",
                "\u00a7e二、清什么、不清什么（这里最容易搞错）\u00a7r",
                "\u00a7e判的是「硬度」，不是「能不能挖」\u00a7r。门槛写成\u00a7f0 ≤ 硬度 < 50\u00a7r：\n"
                        + "\u00a7e不清\u00a7r：黑曜石（硬度正好 \u00a7f50\u00a7r → 被排除，正是需求说的「硬度大于等于黑曜石不清」）；"
                        + "基岩 / 屏障 / 命令方块之类硬度为 \u00a7e-1\u00a7r 的（\u00a7e永远不清\u00a7r，与配置里的数字无关）。\n"
                        + "\u00a7e照清\u00a7r：石头 1.5、深板岩 3、铁块 5、各种矿石与建材——都能铲。\n"
                        + "\u00a7e容器整个跳过\u00a7r（默认开）：箱子 / 熔炉 / 漏斗 / 潜影盒 / 刷怪笼这类\u00a7e带方块实体\u00a7r的方块"
                        + "\u00a7e一个都不碰\u00a7r——不然一路飞过去就是把自家仓库炸成满地战利品。\n"
                        + "\u00a7e流体也不碰\u00a7r：水 / 岩浆没有硬度概念，且破开源头会引发大面积流动计算，一概跳过。\n"
                        + "\u00a7e掉落\u00a7r（默认开）：普通方块按\u00a7e原版战利品表\u00a7r正常掉落，与原版手挖一致。",
                "\u00a7e三、女仆为什么「只在空袭时生效」\u00a7r",
                "本模组一共有\u00a7e四种上天方式\u00a7r：空袭近战 / 空袭远战（鞘翅 + 烟花）、"
                        + "\u00a7e扫帚模式\u00a7r（骑扫帚实体）、\u00a7e仿创造飞行\u00a7r（控制器直飞）、"
                        + "\u00a7e飞行跟随\u00a7r（跟着主人飞）。需求说的是「这个效果在女仆空袭的时候生效」——"
                        + "所以只认前两种。\n"
                        + "\u00a7e不加这道限制会怎样\u00a7r：你给自己穿上鞘翅起飞，她跟着你飞一趟，"
                        + "\u00a7e你家的屋顶就没了\u00a7r。所以扫帚、仿创造飞行、飞行跟随一律不触发。",
                "\u00a7e四、佩戴者免疫撞墙伤害\u00a7r",
                "戴着\u00a7e「大运」\u00a7r的人（玩家或女仆）在\u00a7e鞘翅滑翔中撞到方块，不再掉血\u00a7r——"
                        + "原版对鞘翅玩家也会照常结算「撞墙」伤害（飞得越快撞得越疼），这条把它免掉。\n"
                        + "\u00a7e谁算佩戴者\u00a7r：玩家放进 \u00a7eCurios 饰品栏\u00a7r、女仆放进 \u00a7eTLM 饰品栏\u00a7r，"
                        + "戴在身上就算——\u00a7e不看任务\u00a7r（女仆不在空袭也生效；「开路」才只认空袭）。\n"
                        + "\u00a7e怎么关\u00a7r：面板：移动与行为 → 饰品「大运」 → 佩戴者的保护 → 免疫冲撞伤害（默认开）。\n"
                        + "\u00a7e与飞行作战那条免疫的关系\u00a7r：那是另一道闸（女仆在执行飞行任务 / 跟随期间免撞），"
                        + "这条只认「戴着饰品 + 在滑翔」——两条各管各的，都开着也不冲突，日志里也分得开"
                        + "（本条搜\u00a7e「大运免疫冲撞」\u00a7r）。",
                "\u00a7e五、怎么调（面板：移动与行为 → 饰品「大运」）\u00a7r",
                "\u00a7e\u516b\u9879\u914d\u7f6e\uff0c\u5168\u90e8\u53ef\u8c03\u00a7r\uff1a\n\u00a7e\u2460 \u603b\u5f00\u5173"
                + "\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5173\u6389 = \u5973\u4ec6\u4fa7\u4e0e\u73a9\u5bb6\u4fa7\u4e00\u8d77"
                + "\u505c\uff08\u7269\u54c1\u8fd8\u80fd\u5408\u6210\u3001\u8fd8\u80fd\u4f69\u6234\uff0c\u53ea\u662f\u4e0d\u518d"
                + "\u7834\u574f\uff09\u3002\n\u00a7e\u2461 \u73a9\u5bb6\u4fa7\u5f00\u5173\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09"
                + "\uff1a\u53ea\u505c\u73a9\u5bb6\u90a3\u4e00\u4fa7\u3002\u00a7e\u670d\u52a1\u5668\u5e38\u7528\u00a7r\u2014\u2014"
                + "\u4e0d\u8ba9\u73a9\u5bb6\u4e00\u8def\u98de\u4e00\u8def\u94f2\uff0c\u4f46\u5141\u8bb8\u5973\u4ec6\u5e72\u6d3b"
                + "\u65f6\u5f00\u8def\u3002\n\u00a7e\u2462 \u786c\u5ea6\u4e0a\u9650\u00a7r\uff08\u9ed8\u8ba4 50\uff0c\u8303\u56f4 0"
                + "~100\uff09\uff1a\u53ea\u6e05\u00a7e\u786c\u5ea6\u5c0f\u4e8e\u6b64\u503c\u00a7r\u7684\u65b9\u5757\u3002\u8c03"
                + "\u5230 \u00a7f51\u00a7r = \u8fde\u9ed1\u66dc\u77f3\u4e00\u8d77\u94f2\uff08\u6316\u9ed1\u66dc\u77f3\u4e13\u7528"
                + "\uff09\uff1b\u8c03\u5230 \u00a7f3\u00a7r = \u53ea\u6e05\u6df1\u677f\u5ca9\u53ca\u66f4\u8f6f\u7684\u3002\n\u00a7e"
                + "\u2463 \u8df3\u8fc7\u5bb9\u5668\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5173\u6389 = \u5bb9\u5668\u4e5f"
                + "\u7167\u7834\uff0c\u91cc\u9762\u7684\u4e1c\u897f\u5168\u6389\u51fa\u6765\u3002\n\u00a7e\u2464 \u7834\u574f\u540e"
                + "\u6389\u843d\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5173\u6389 = \u65b9\u5757\u76f4\u63a5\u6d88\u5931\u3001"
                + "\u4e0d\u4ea7\u751f\u4efb\u4f55\u7269\u54c1\uff08\u7eaf\u6e05\u573a\uff0c\u6027\u80fd\u6700\u597d\uff09\u3002",
                "\u00a7e\u2465 \u7834\u574f\u7c92\u5b50\u00a7r\uff08\u9ed8\u8ba4\u5f00\uff09\uff1a\u5173\u6389 = \u65b9\u5757"
                + "\u9759\u9759\u6d88\u5931\uff0c\u6ca1\u6709\u788e\u5c51\u4e5f\u6ca1\u6709\u7834\u574f\u97f3\uff08\u5acc\u4e00"
                + "\u8def\u98de\u8fc7\u53bb\u7c92\u5b50\u592a\u591a\u3001\u6216\u60f3\u7701\u5ba2\u6237\u7aef\u5f00\u9500\u65f6"
                + "\u5173\uff09\u3002\n\u00a7e\u2466 \u5355 tick \u7834\u574f\u4e0a\u9650\u00a7r\uff08\u9ed8\u8ba4 64\uff0c\u8303"
                + "\u56f4 1~512\uff09\uff1a\u6bcf tick \u6700\u591a\u6e05\u591a\u5c11\u683c\uff0c\u8d85\u51fa\u7684\u00a7e\u4e0b"
                + "\u4e00 tick \u7ee7\u7eed\u00a7r\uff08\u4e0d\u4f1a\u6f0f\uff0c\u53ea\u662f\u6162\u4e00\u70b9\uff09\u3002\u6ed1"
                + "\u7fd4\u901f\u5ea6\u5feb\u65f6\u53ef\u8c03\u5927\uff0c\u4f46\u6bcf\u683c\u90fd\u8981\u8d70\u4e00\u904d\u6218"
                + "\u5229\u54c1\u8868\u7ed3\u7b97\uff0c\u00a7e\u670d\u52a1\u5668\u8d1f\u62c5\u968f\u4e4b\u4e0a\u5347\u00a7r\u2014"
                + "\u2014\u5355\u4eba / \u6574\u5408\u5305\u5efa\u8bae 64~128\u3002",
                "\u00a7e\u2467 \u7834\u574f\u8303\u56f4\u00a7r\uff08\u9ed8\u8ba4 5\uff0c\u8303\u56f4 1~15\uff09\uff1a\u4ee5\u5979"
                + "/\u4ed6\u6240\u7ad9\u90a3\u4e00\u683c\u4e3a\u4e2d\u5fc3\uff0c\u6e05\u6389\u00a7e\u3010\u8fd9\u4e2a\u6570 \u00d7 "
                + "\u8fd9\u4e2a\u6570 \u00d7 \u8fd9\u4e2a\u6570\u3011\u7684\u7acb\u65b9\u4f53\u00a7r\u3002\u586b \u00a7f5\u00a7r = "
                + "\u5404 2 \u683c = 5\u00d75\u00d75\uff08125 \u683c\uff0c\u5373\u9ed8\u8ba4\uff09\uff1b\u586b \u00a7f3\u00a7r = 3"
                + "\u00d73\u00d73\uff0827 \u683c\uff0c\u8d34\u8eab\u7a7f\u884c\u6700\u4e0d\u5bb9\u6613\u8bef\u4f24\uff09\uff1b"
                + "\u586b \u00a7f9\u00a7r = 9\u00d79\u00d79\uff08729 \u683c\uff0c\u4e00\u6761\u5f88\u5bbd\u7684\u96a7\u9053\uff09"
                + "\uff1b\u586b \u00a7f15\u00a7r = 15\u00d715\u00d715\uff083375 \u683c\uff0c\u51e0\u4e4e\u662f\u5728\u7281\u5730"
                + "\uff09\u3002\u00a7e\u5076\u6570\u4f1a\u81ea\u52a8\u8fdb\u4e00\u4f4d\u00a7r\uff08\u586b 4 \u5b9e\u9645\u6309 5 "
                + "\u751f\u6548\u2014\u2014\u5947\u6570\u8fb9\u957f\u624d\u524d\u540e/\u5de6\u53f3/\u4e0a\u4e0b\u5bf9\u79f0\uff09"
                + "\u3002\u00a7e\u6ce8\u610f\u00a7r\uff1a\u8303\u56f4\u8c03\u5927\u540e\u6bcf tick \u8981\u68c0\u67e5\u7684\u683c"
                + "\u5b50\u6309\u7acb\u65b9\u589e\u957f\uff0c\u8c03\u5230 11 \u4ee5\u4e0a\u5efa\u8bae\u540c\u65f6\u8c03\u5927\u2466"
                + "\uff1b\u6cbf\u524d\u8fdb\u65b9\u5411\u63d0\u524d\u6e05\u7684\u90a3\u4e00\u6bb5\u4e5f\u6309\u8fd9\u4e2a\u8fb9"
                + "\u957f\u8d70\u3002",
                "\u00a7e六、常见问题\u00a7r",
                "\u00a7e女仆戴着它飞过去却什么都没清\u00a7r → 先看\u00a7e任务是不是空袭\u00a7r（飞行作战 / 飞行远战），"
                        + "再看她\u00a7e是不是真的在滑翔\u00a7r（悬停、落地、骑扫帚都不算），最后看总开关。\n"
                        + "\u00a7e玩家戴着却没反应\u00a7r → 确认装的是 \u00a7eCurios\u00a7r、物品\u00a7e真的放进了饰品栏\u00a7r"
                        + "（不是拿在手上或放背包），并且\u00a7e你正在滑翔\u00a7r。\n"
                        + "\u00a7e想清黑曜石清不动\u00a7r → 硬度上限调到 51（50 是「大于等于黑曜石不清」的那个 50）。\n"
                        + "\u00a7e担心铲掉自家东西\u00a7r → 保持「跳过容器」开，并注意「破坏后掉落」开着时铲掉的东西会真的掉一地；"
                        + "把⑧「破坏范围」调小到 3 也能明显减小误伤面。\n"
                        + "\u00a7e日志\u00a7r：logs/promaid.log 搜\u00a7e「大运」\u00a7r 相关条目；配置项名 \u00a7eaccessory.daYun.*\u00a7r。");
    }
}
      